update public.exercises set
  instructions = coalesce(instructions, ARRAY['Párate sosteniendo una barra con agarre supino a la anchura de los hombros.','Sube la barra hacia los hombros.','Aprieta en la parte superior, luego baja de forma controlada.','Repite.']),
  tips = coalesce(tips, ARRAY['Evita balancear el torso.','Mantén los codos pegados a los costados.']),
