update public.exercises set
  instructions = coalesce(instructions, ARRAY['Empieza con un trote suave y sube hasta tu ritmo durante los primeros minutos, en lugar de salir directamente a la velocidad objetivo.','Apoya el pie bajo la cadera, no por delante del cuerpo, y mantén el contacto con el suelo corto y silencioso.','Corre erguido desde la cadera, con una ligera inclinación desde los tobillos y sin doblarte por la cintura.','Flexiona los codos unos noventa grados y lleva los brazos adelante y atrás, sin cruzarlos sobre el pecho.','Respira con ritmo y mantén sueltos los hombros, la mandíbula y las manos.','Sostén el ritmo el tiempo o la distancia deseados, luego trota y camina unos minutos para terminar.']),
  tips = coalesce(tips, ARRAY['Aumenta el volumen semanal poco a poco. Casi toda lesión al correr viene de sumar kilómetros más rápido de lo que se adaptan tendones y huesos, no de una sola tirada dura.','La mayor parte de tus carreras debe ser lo bastante suave como para poder hablar. Correr cada sesión a un ritmo medio-fuerte es la vía más rápida al estancamiento.','Si notas que pisas con estruendo, acorta la zancada y deja subir la cadencia — buscar un paso más largo pone el freno en cada apoyo.']),
  image_url = coalesce(image_url, '/exercises/running-main.webp'),
  thumbnail_url = coalesce(thumbnail_url, '/exercises/running-main.webp'),
  image_source = coalesce(image_source, 'RepDB (repdb.co)'),
  image_license = coalesce(image_license, 'Free tier - commercial in-app use with attribution')
where slug = 'running';

update public.exercises set
  instructions = coalesce(instructions, ARRAY['Siéntate en la estación de remo y coloca los pies en los apoyos.','Sujeta la manija y siéntate erguido con una ligera inclinación hacia adelante.','Lleva los codos hacia atrás y tira de la manija hacia la parte baja del abdomen.','Contrae los omóplatos al final del tirón.','Extiende los brazos con control de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']),
  tips = coalesce(tips, ARRAY['Mantén el torso erguido con un balanceo mínimo.','Lleva los codos directamente hacia atrás, no hacia los lados.','Contrae los omóplatos al final del tirón.']),
  image_url = coalesce(image_url, '/exercises/seated-cable-row-main.webp'),
