-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Rueda Abdominal', 'ab-wheel-rollout', 'core', ARRAY['shoulders','back'], NULL, 'intermediate', 'compound', 'Un ejercicio de core haciendo rodar una rueda adelante y atrás, que entrena la antiextensión de la columna.', ARRAY['Arrodíllate en el suelo y agarra las asas de la rueda a la anchura de los hombros.','Activa fuertemente el core para que la zona lumbar quede neutra.','Rueda la rueda lentamente hacia adelante, extendiendo el cuerpo lo más lejos que puedas controlar.','Detente antes de que las caderas se hundan o la espalda se arquee.','Tira de la rueda de regreso hacia las rodillas contrayendo los abdominales.'], ARRAY['Activa el core antes de cada repetición — no dejes que la lumbar se arquee.','Aumenta el rango progresivamente, parando antes de que las caderas se hundan.','Usa un tope contra la pared si no puedes controlar la posición baja.'], '/exercises/ab-wheel-rollout-main.webp', '/exercises/ab-wheel-rollout-main.webp'),
  ('Bicicleta de Aire', 'air-bike', 'hamstrings', ARRAY['glutes','back','chest','core'], 'machine', 'intermediate', 'cardio', 'Un ejercicio de cuerpo completo en bicicleta de aire que combina el empuje y la tracción de los brazos con el pedaleo continuo.', ARRAY['Siéntate en la bicicleta de aire y sujeta los manillares móviles.','Coloca los pies en los pedales y contrae el core.','Empuja y jala los manillares mientras pedaleas a un ritmo constante.','Impulsa con brazos y piernas para mantener la potencia.','Continúa durante la duración o distancia deseada.'], ARRAY['Mantén las rodillas alineadas con los pedales al pedalear.','Evita encorvar la espalda cuando aumente la fatiga.','Respira de forma rítmica para sostener la potencia.'], '/exercises/air-bike-main.webp', '/exercises/air-bike-main.webp'),
  ('Dominadas Arquero', 'archer-pull-ups', 'back', ARRAY['biceps','forearms','shoulders'], 'bodyweight', 'advanced', 'compound', 'Una dominada unilateral desplazando el cuerpo hacia una mano mientras el otro brazo permanece estirado, desarrollando fuerza de tracción a un brazo.', ARRAY['Agarra la barra más ancha que la anchura de los hombros con las palmas mirando hacia afuera.','Tírate hacia arriba desplazando el cuerpo hacia una mano.','Mantén el brazo opuesto extendido como soporte.','Bájate de forma controlada hasta quedar colgado.','Alterna lados en cada repetición o completa las repeticiones de un lado primero.'], ARRAY['Mantén el brazo estirado completamente extendido y úsalo solo como guía.','Lleva la barbilla hacia la mano que trabaja, no directamente hacia arriba.','Domina las dominadas con agarre ancho antes de progresar a las arqueras.'], '/exercises/archer-pull-ups-main.webp', '/exercises/archer-pull-ups-main.webp'),
  ('Push-Ups Arquero', 'archer-push-ups', 'chest', ARRAY['shoulders','core','triceps'], NULL, 'advanced', 'compound', 'Una flexión ancha bajando hacia una mano mientras el brazo contrario permanece estirado, cargando un lado cada vez.', ARRAY['Colócate en posición de push-up amplia con los brazos extendidos.','Bájate hacia una mano mientras mantienes el otro brazo extendido.','Mantén el core apretado y el cuerpo en línea recta.','Empuja de vuelta a la posición inicial.','Alterna lados en cada repetición el número de veces deseado.'], ARRAY['Mantén las caderas paralelas al suelo mientras te desplazas hacia el lado.','Deja que el brazo estirado ayude lo menos posible.','Empieza con flexiones anchas y desplázate un poco más en cada sesión.'], '/exercises/archer-push-ups-main.webp', '/exercises/archer-push-ups-main.webp'),
  ('Press Arnold', 'arnold-press', 'shoulders', ARRAY['core','traps','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un press de hombros con mancuernas que rota las palmas durante el ascenso, dirigido al deltoides anterior y lateral.', ARRAY['Sostén un par de mancuernas a la altura de los hombros con las palmas mirando hacia ti.','Empuja las mancuernas sobre la cabeza mientras rotas las palmas hacia adelante.','Extiende los brazos por completo en la parte superior sin bloquear los codos.','Invierte el movimiento y rota de vuelta a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Evita arquear la zona lumbar al empujar hacia arriba.','Mantén las muñecas firmes y alineadas con los antebrazos.','Controla la bajada en lugar de dejar caer el peso.'], '/exercises/arnold-press-main.webp', '/exercises/arnold-press-main.webp'),
  ('Fondos en Máquina Asistida', 'assisted-dips', 'chest', ARRAY['shoulders','back'], 'machine', 'beginner', 'compound', 'Un ejercicio de fondos en máquina asistida que descarga parte del peso corporal para fortalecer pecho y tríceps.', ARRAY['Sube a la máquina de fondos asistidos con las rodillas en el pad.','Agarra las barras paralelas y soporta tu peso con los brazos extendidos.','Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.','Empuja de vuelta a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Baja de forma controlada, sin rebotar en la parte inferior.','Mantén los hombros alejados de las orejas durante todo el recorrido.','Reduce la asistencia de forma gradual a medida que ganes fuerza.'], '/exercises/assisted-dips-main.webp', '/exercises/assisted-dips-main.webp'),
  ('Dominadas Asistidas', 'assisted-pull-ups', 'back', ARRAY['biceps','forearms','shoulders'], 'machine', 'beginner', 'compound', 'Una dominada en máquina asistida que contrarresta parte del peso corporal, pensada para construir la fuerza de espalda necesaria para dominadas estrictas.', ARRAY['Coloca las rodillas en el pad de la máquina de dominadas asistidas.','Agarra la barra con las palmas mirando hacia afuera, ligeramente más ancho que los hombros.','Tira del pecho hacia la barra impulsando los codos hacia abajo.','Bájate de forma controlada hasta quedar colgado con los brazos extendidos.','Repite el número de repeticiones deseado.'], ARRAY['Inicia el movimiento bajando los omóplatos antes de doblar los codos.','Evita balancearte para no restar trabajo a la espalda.','Ajusta el contrapeso para completar todas las repeticiones con buena técnica.'], '/exercises/assisted-pull-ups-main.webp', '/exercises/assisted-pull-ups-main.webp'),
  ('Extensión de Espalda', 'back-extension', 'back', ARRAY['glutes','hamstrings'], NULL, 'beginner', 'isolation', 'Un movimiento de aislamiento que trabaja los erectores espinales de la zona lumbar en un banco de hiperextensión.', ARRAY['Acuéstate boca abajo en un banco de hiperextensión con las caderas en el borde del pad.','Baja el torso hacia el suelo.','Sube el torso hasta que el cuerpo quede recto.','Repite.'], ARRAY['Mantén los movimientos controlados.','No hiperextiendas más allá de la posición neutra de la columna.'], '/exercises/back-extension-main.webp', '/exercises/back-extension-main.webp'),
  ('Back lever', 'back-lever', 'back', ARRAY['shoulders','glutes','core'], 'bodyweight', 'advanced', 'compound', 'Un isométrico gimnástico avanzado: colgado de una barra, el cuerpo se mantiene horizontal y boca abajo en línea recta, exigiendo tensión de todo el cuerpo a través de dorsales, core y cadena posterior.', ARRAY['Cuélgate de una barra con agarre prono y rota hacia atrás a través de los brazos hasta quedar invertido.','Baja el cuerpo hacia delante y abajo hasta que quede horizontal, con la cara hacia el suelo.','Mantén los brazos rectos y todo el cuerpo en una línea rígida de la cabeza a los pies.','Aprieta el core y los glúteos para que la cadera y los hombros no se hundan.','Mantén la posición el tiempo deseado y rota de nuevo hacia arriba de forma controlada.'], ARRAY['Progresa con variantes agrupadas y a una pierna antes de intentar el lever completo con el cuerpo recto.','Deprime y retrae las escápulas para proteger los hombros.','Mantente rígido: cualquier flexión o arqueo colapsa la postura.'], '/exercises/back-lever-main.webp', '/exercises/back-lever-main.webp'),
  ('Curl de Piernas con Pelota de Estabilidad', 'ball-leg-curl', 'hamstrings', ARRAY['calves','glutes'], 'bodyweight', 'intermediate', 'isolation', 'Un curl de isquiotibiales con el propio peso usando una pelota de estabilidad, rodando los talones hacia los glúteos mientras se eleva la cadera.', ARRAY['Acuéstate boca arriba en el suelo con los talones y la parte inferior de las pantorrillas sobre la pelota de estabilidad y los brazos estirados para hacer equilibrio.','Presiona con los talones para elevar las caderas formando una línea recta desde los hombros hasta los tobillos.','Manteniendo las caderas arriba, flexiona las rodillas para rodar la pelota hacia los glúteos.','Extiende las piernas de vuelta de forma controlada sin bajar las caderas.','Completa todas las repeticiones, luego baja las caderas y sepárate de la pelota.'], ARRAY['Las caderas permanecen arriba durante toda la serie: es una combinación de puente y curl.','Empieza con ambos pies; progresa a una sola pierna cuando se vuelva fácil.'], '/exercises/ball-leg-curl-main.webp', '/exercises/ball-leg-curl-main.webp'),
  ('Pike con Pelota', 'ball-pike', 'core', ARRAY['shoulders'], 'bodyweight', 'advanced', 'compound', 'Un ejercicio avanzado de core en el que las caderas se elevan mientras los pies ruedan una pelota suiza hacia el pecho.', ARRAY['Coloca las espinillas sobre una pelota suiza y las manos en el suelo en plancha alta.','Activa el core y mantén las piernas rectas.','Eleva las caderas, rodando la pelota hacia el pecho hasta formar una V invertida.','Pausa brevemente arriba.','Rueda la pelota de vuelta a la posición inicial de plancha.'], ARRAY['Mantén las piernas rectas todo el tiempo — sin doblar las rodillas.','Mueve desde la cadera, no desde la zona lumbar.','Trabaja primero con flexiones de rodilla si el pike es demasiado difícil.'], '/exercises/ball-pike-main.webp', '/exercises/ball-pike-main.webp'),
  ('Dominadas Asistidas con Banda', 'band-assisted-pull-ups', 'back', ARRAY['biceps','forearms','shoulders'], 'band', 'beginner', 'compound', 'Una dominada con banda elástica enganchada a la barra que reduce el peso corporal a vencer en cada repetición.', ARRAY['Engancha una banda elástica en la barra de dominadas e introduce un pie en ella.','Agarra la barra con las palmas mirando hacia afuera, a la anchura de los hombros.','Tira del pecho hacia la barra impulsando los codos hacia abajo.','Bájate de forma controlada hasta quedar colgado con los brazos extendidos.','Repite el número de repeticiones deseado.'], ARRAY['Comprueba que la banda esté bien sujeta antes de colgarte.','No tomes impulso con las piernas, deja que trabaje la espalda.','Usa una banda más fina a medida que progreses.'], '/exercises/band-assisted-pull-ups-main.webp', '/exercises/band-assisted-pull-ups-main.webp'),
  ('Separación de Banda Elástica', 'band-pull-apart', 'shoulders', ARRAY['back','traps'], 'band', 'beginner', 'isolation', 'Un ejercicio de alto volumen para el deltoides posterior y los retractores escapulares que se realiza separando una banda elástica a la altura de los hombros.', ARRAY['Párate sosteniendo una banda elástica ligera con ambas manos, brazos extendidos al frente a la altura de los hombros.','Las manos comienzan a la anchura de los hombros, palmas mirando hacia abajo.','Manteniendo los brazos extendidos, separa la banda llevando las manos hacia los lados.','Termina con la banda tocando el pecho y los omóplatos juntos.','Vuelve lentamente a la posición inicial y repite.'], ARRAY['Lidera el movimiento con los meñiques: esto rota externamente los hombros.','Usa una banda lo suficientemente ligera para hacer 15-30 repeticiones limpias; es un ejercicio preventivo de alto número de repeticiones.'], '/exercises/band-pull-apart-main.webp', '/exercises/band-pull-apart-main.webp'),
  ('Estiramiento de Aductores con Banda', 'banded-adductor-stretch', 'adductors', ARRAY['hamstrings'], 'band', 'beginner', 'mobility', 'Un estiramiento tumbado que usa una banda para llevar una pierna estirada hacia el lado y alargar el aductor.', ARRAY['Acuéstate boca arriba con una banda en un pie.','Eleva esa pierna y déjala abrir hacia el lado.','Sujeta la banda para controlar cuánto baja la pierna.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén las caderas planas y ambos glúteos en el suelo.','Estira hasta una tensión leve, nunca hasta el dolor.'], '/exercises/banded-adductor-stretch-main.webp', '/exercises/banded-adductor-stretch-main.webp'),
  ('Estiramiento de Tobillo con Banda', 'banded-ankle-stretch', 'calves', NULL, 'band', 'beginner', 'mobility', 'Un estiramiento sentado que usa una banda en el antepié para flexionar el tobillo y alargar la pantorrilla.', ARRAY['Siéntate con una pierna extendida y una banda en el antepié.','Sujeta la banda con ambas manos.','Tira para que los dedos se acerquen a la espinilla.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén la pierna estirada y relajada.','Estira hasta una tensión leve, nunca hasta el dolor.'], '/exercises/banded-ankle-stretch-main.webp', '/exercises/banded-ankle-stretch-main.webp'),
  ('Estiramiento de Pantorrilla con Banda', 'banded-calf-stretch', 'calves', NULL, 'band', 'beginner', 'mobility', 'Un estiramiento tumbado que usa una banda en la planta del pie para flexionar el tobillo y alargar la pantorrilla.', ARRAY['Acuéstate boca arriba y pasa una banda por la planta de un pie.','Eleva la pierna y mantenla bastante recta.','Tira de la banda para que los dedos se acerquen a la espinilla.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén el tirón constante, sin tirones bruscos.','Mantén la rodilla suavemente estirada.'], '/exercises/banded-calf-stretch-main.webp', '/exercises/banded-calf-stretch-main.webp'),
  ('Estiramiento de Pecho con Banda', 'banded-chest-stretch', 'chest', ARRAY['shoulders'], 'band', 'beginner', 'mobility', 'Un estiramiento de pie que abre el pecho sujetando una banda tras la espalda y separando los brazos.', ARRAY['Sujeta una banda con ambas manos tras la espalda.','Estira los brazos y sepáralos.','Eleva el pecho y junta los omóplatos.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén los hombros abajo, lejos de las orejas.','Estira hasta una tensión leve, nunca hasta el dolor.'], '/exercises/banded-chest-stretch-main.webp', '/exercises/banded-chest-stretch-main.webp'),
  ('Almeja con Banda', 'banded-clamshell', 'glutes', NULL, 'band', 'beginner', 'isolation', 'Una abducción de cadera tipo almeja con una banda circular por encima de las rodillas, que aísla el glúteo medio.', ARRAY['Túmbate de lado con las caderas y rodillas flexionadas a unos 45 grados y los pies juntos uno sobre otro.','Coloca una banda circular alrededor de ambas piernas por encima de las rodillas.','Mantén los pies pegados y la pelvis estable; no rotes hacia atrás durante el movimiento.','Abre la rodilla de arriba contra la banda, como una almeja al abrirse, hasta notar que el glúteo se activa.','Haz una breve pausa arriba y baja de forma controlada hasta la posición inicial.','Completa todas las repeticiones de un lado y luego cambia.'], ARRAY['La pelvis se queda fija; en cuanto rotas hacia atrás, el glúteo deja de trabajar.','Un tempo lento y controlado vale más que una banda dura.','Si te da un calambre en el lateral de la cadera, acorta la serie.'], '/exercises/banded-clamshell-main.webp', '/exercises/banded-clamshell-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
