-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Estiramiento Figura 4 con Banda', 'banded-figure-4-stretch', 'glutes', NULL, 'band', 'beginner', 'mobility', 'Un estiramiento de glúteos tumbado en posición de figura 4, usando una banda para acercar ambas piernas al pecho.', ARRAY['Acuéstate boca arriba y cruza un tobillo sobre el muslo opuesto.','Pasa una banda por el muslo de apoyo.','Lleva ambas piernas al pecho con la banda.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén la cabeza y los hombros relajados en el suelo.','Deja que la rodilla cruzada caiga hacia afuera.'], '/exercises/banded-figure-4-stretch-main.webp', '/exercises/banded-figure-4-stretch-main.webp'),
  ('Hidrante de Fuego con Banda', 'banded-fire-hydrant', 'glutes', NULL, 'band', 'beginner', 'isolation', 'Este ejercicio de aislamiento utiliza una banda de resistencia para fortalecer el glúteo medio y mayor, mejorando la abducción y estabilidad de la cadera.', ARRAY['Coloca una banda de resistencia justo por encima de tus rodillas y ponte en posición de cuadrupedia, manos bajo los hombros y rodillas bajo las caderas.','Mantén tu core activado y la espalda recta, conservando una columna vertebral neutra durante todo el movimiento.','Levanta lentamente una rodilla hacia un lado, manteniendo la rodilla flexionada a 90 grados, hasta que tu muslo esté paralelo al suelo.','Sostén brevemente en la parte superior, contrayendo el glúteo, luego baja la pierna de forma controlada a la posición inicial.','Completa todas las repeticiones de un lado antes de cambiar al otro lado.'], ARRAY['Concéntrate en un movimiento controlado; evita usar el impulso para levantar la pierna.','Mantén tus caderas estables y evita que tu torso rote o se incline.','Asegúrate de que la banda permanezca tensa durante todo el rango de movimiento.'], '/exercises/banded-fire-hydrant-main.webp', '/exercises/banded-fire-hydrant-main.webp'),
  ('Puente de Glúteos con Banda', 'banded-glute-bridge', 'glutes', ARRAY['hamstrings'], 'band', 'beginner', 'compound', 'Un puente de glúteos con una banda circular por encima de las rodillas que suma tensión de abducción al empuje de cadera.', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo a la anchura de los hombros.','Coloca una banda circular alrededor de ambas piernas justo por encima de las rodillas.','Presiona la zona lumbar contra el suelo y activa el core.','Empuja con los talones y aprieta los glúteos para elevar las caderas en puente, manteniendo la tensión de la banda al empujar las rodillas hacia afuera.','Arriba, el cuerpo forma una línea recta de los hombros a las rodillas. Haz una breve pausa.','Baja de forma controlada hasta la posición inicial y repite el número de repeticiones recomendado.'], ARRAY['Las rodillas tienden a irse hacia dentro; empújalas hacia afuera contra la banda.','Detén la subida cuando las caderas queden a la altura de hombros y rodillas; no hiperextiendas la lumbar.','Aprieta fuerte arriba; un puente rápido a medio recorrido se siente fácil porque lo es.'], '/exercises/banded-glute-bridge-main.webp', '/exercises/banded-glute-bridge-main.webp'),
  ('Buenos Días con Banda', 'banded-good-morning', 'glutes', ARRAY['back'], 'band', 'beginner', 'compound', 'Un hip-hinge con banda elástica sobre la espalda alta, que trabaja isquiotibiales y glúteos.', ARRAY['Pisa una banda elástica con ambos pies y pásala por la nuca.','Coloca los pies a la anchura de las caderas, ligera flexión de rodillas.','Flexiona desde la cadera empujándola atrás, espalda recta.','Baja hasta sentir el estiramiento en los isquiotibiales.','Empuja las caderas adelante para volver a la posición inicial.'], ARRAY['Mueve desde la cadera, no desde la zona lumbar.','Pecho arriba y espalda recta.','Usa una banda lo bastante ligera para permitir el rango completo.'], '/exercises/banded-good-morning-main.webp', '/exercises/banded-good-morning-main.webp'),
  ('Estiramiento de Isquiotibiales con Banda', 'banded-hamstring-stretch', 'hamstrings', ARRAY['calves'], 'band', 'beginner', 'mobility', 'Un estiramiento tumbado que usa una banda en el pie para acercar la pierna estirada al torso y alargar el isquiotibial.', ARRAY['Acuéstate boca arriba y pasa una banda por un pie.','Eleva esa pierna recta, sujetando la banda con ambas manos.','Tira suavemente de la banda para acercar la pierna.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén la pierna elevada lo más recta posible.','Mantén la otra pierna plana en el suelo.'], '/exercises/banded-hamstring-stretch-main.webp', '/exercises/banded-hamstring-stretch-main.webp'),
  ('Empuje de Cadera con Banda', 'banded-hip-thrust', 'glutes', ARRAY['hamstrings'], 'band', 'beginner', 'compound', 'Este ejercicio utiliza una banda de bucle para aumentar la activación de los glúteos durante un empuje de cadera, trabajando eficazmente el glúteo mayor, los isquiotibiales y el glúteo medio para mejorar la fuerza de la parte inferior del cuerpo.', ARRAY['Coloca una banda de bucle justo por encima de tus rodillas y siéntate en el suelo con la parte superior de tu espalda contra un banco.','Dobla las rodillas, apoya los pies al ancho de las caderas y posiciona la banda para crear tensión.','Impúlsate a través de los talones, extiende las caderas y levanta los glúteos del suelo hasta que tu cuerpo forme una línea recta.','Aprieta los glúteos con fuerza en la parte superior, asegurándote de empujar las rodillas hacia afuera contra la banda.','Baja lentamente las caderas a la posición inicial con control.'], ARRAY['Mantén una tensión constante en la banda durante todo el movimiento.','Concéntrate en una fuerte contracción de los glúteos en el pico del empuje.','Mantén la barbilla metida y la mirada al frente para una columna vertebral neutra.','Asegúrate de que tus espinillas estén verticales en la parte superior del movimiento.'], '/exercises/banded-hip-thrust-main.webp', '/exercises/banded-hip-thrust-main.webp'),
  ('Estiramiento de Banda Iliotibial con Banda', 'banded-it-band-stretch', 'abductors', ARRAY['glutes'], 'band', 'beginner', 'mobility', 'Un estiramiento tumbado que usa una banda para cruzar una pierna sobre el cuerpo y trabajar el muslo y la cadera externos.', ARRAY['Acuéstate boca arriba con una banda en un pie elevado.','Sujeta la banda con la mano contraria.','Lleva la pierna estirada cruzando el cuerpo hacia el suelo.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén ambos hombros en el suelo.','Detente al sentir el estiramiento en el muslo externo.'], '/exercises/banded-it-band-stretch-main.webp', '/exercises/banded-it-band-stretch-main.webp'),
  ('Empuje de Cadera Arrodillado con Banda', 'banded-kneeling-hip-thrust', 'glutes', ARRAY['hamstrings'], 'band', 'beginner', 'compound', 'Este ejercicio fortalece los glúteos y los isquiotibiales al impulsar las caderas hacia adelante contra la resistencia de una banda desde una posición arrodillada.', ARRAY['Coloca una banda de bucle justo por encima de tus rodillas. Arrodíllate en el suelo con el torso erguido y las rodillas separadas al ancho de las caderas.','Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el core contraído.','Inicia el movimiento apretando los glúteos, impulsando las caderas hacia adelante hasta que tu torso esté erguido.','Aprieta los glúteos con fuerza en la parte superior, manteniendo la tensión en la banda.','Invierte lentamente el movimiento, controlando la resistencia de la banda mientras regresas a la posición inicial.'], ARRAY['Concéntrate en una fuerte contracción de los glúteos en la parte superior del movimiento.','Mantén el core activado en todo momento para evitar arquear la espalda baja.','Mantén una tensión constante en la banda empujando las rodillas ligeramente hacia afuera.'], '/exercises/banded-kneeling-hip-thrust-main.webp', '/exercises/banded-kneeling-hip-thrust-main.webp'),
  ('Estiramiento de Dorsales con Banda', 'banded-lat-stretch', 'back', ARRAY['shoulders'], 'band', 'beginner', 'mobility', 'Un estiramiento de pie que alarga los dorsales al inclinarse hacia adelante sosteniendo una banda en tensión sobre la cabeza.', ARRAY['Sujeta una banda sobre la cabeza con ambas manos en tensión ligera.','Inclínate desde las caderas con los brazos extendidos al frente.','Deja caer el pecho para alargar los lados de la espalda.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén los brazos estirados y los hombros relajados.','Relájate y sigue respirando todo el tiempo.'], '/exercises/banded-lat-stretch-main.webp', '/exercises/banded-lat-stretch-main.webp'),
  ('Caminata Lateral con Banda', 'banded-lateral-walk', 'glutes', ARRAY['quads'], 'band', 'beginner', 'compound', 'Un desplazamiento lateral a pasos con una banda circular por encima de las rodillas o en los tobillos, que activa el glúteo medio.', ARRAY['Coloca una banda circular alrededor de las piernas por encima de las rodillas (o en los tobillos para una versión más difícil).','Ponte en cuarto de sentadilla: pies a la anchura de los hombros, caderas atrás, pecho alto y rodillas alineadas con los pies.','Da un paso lateral con un pie directamente hacia el lado contra la tensión de la banda.','Acerca el pie de atrás hacia el de delante manteniendo la tensión de la banda en todo momento; no dejes que los pies se junten de golpe.','Sigue dando pasos laterales en una dirección durante las repeticiones o la distancia indicada y luego invierte.','Permanece abajo todo el rato; no te incorpores entre paso y paso.'], ARRAY['Mantén las puntas de los pies hacia el frente; no dejes que el pie de delante se abra.','Las caderas se quedan niveladas; no te balancees de lado a lado al caminar.','Si las rodillas se van hacia dentro, la banda es demasiado dura; usa una más suave.'], '/exercises/banded-lateral-walk-main.webp', '/exercises/banded-lateral-walk-main.webp'),
  ('Estiramiento de Deltoides Posterior con Banda', 'banded-rear-delt-stretch', 'shoulders', ARRAY['back','traps'], 'band', 'beginner', 'mobility', 'Un estiramiento de pie para el hombro posterior llevando un brazo cruzado contra la tensión de la banda.', ARRAY['Pasa una banda por un brazo y sujeta el otro extremo.','Lleva ese brazo en horizontal sobre el pecho.','Usa la banda para profundizar el tirón suavemente.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén el hombro que trabaja relajado y abajo.','Relájate y sigue respirando todo el tiempo.'], '/exercises/banded-rear-delt-stretch-main.webp', '/exercises/banded-rear-delt-stretch-main.webp'),
  ('Peso Muerto Rumano con Banda', 'banded-romanian-deadlift', 'glutes', ARRAY['back'], 'band', 'beginner', 'compound', 'Un peso muerto rumano con banda elástica, ideal para calentar y aprender el patrón de hip-hinge.', ARRAY['Pisa una banda elástica con ambos pies y agarra el extremo superior.','Coloca los pies a la anchura de las caderas, ligera flexión de rodillas.','Flexiona desde la cadera, deslizando las manos por las piernas.','Baja hasta sentir el estiramiento en los isquiotibiales.','Empuja las caderas adelante para volver a la posición inicial.'], ARRAY['Mantén la banda cerca de las piernas.','Detente en el punto bajo de tu rango limpio — no redondees la espalda.','El movimiento es un hinge, no una sentadilla — las rodillas casi no se flexionan.'], '/exercises/banded-romanian-deadlift-main.webp', '/exercises/banded-romanian-deadlift-main.webp'),
  ('Abducción de Cadera Sentado con Banda', 'banded-seated-hip-abduction', 'glutes', NULL, 'band', 'beginner', 'isolation', 'Este ejercicio de aislamiento trabaja el glúteo medio y mayor al rotar externamente las caderas contra la resistencia de una banda mientras estás sentado.', ARRAY['Siéntate en un banco o silla con una banda elástica alrededor de tus rodillas.','Mantén los pies apoyados en el suelo, separados al ancho de tus caderas, y conserva una postura erguida.','Empuja tus rodillas hacia afuera contra la banda, activando tus glúteos.','Sostén la contracción máxima brevemente, luego regresa lentamente tus rodillas a la posición inicial.','Controla el movimiento a lo largo de todo el rango de movimiento.'], ARRAY['Concéntrate en apretar tus glúteos para iniciar el movimiento.','Evita inclinarte hacia atrás o usar el impulso; mantén tu torso estable.','Elige una resistencia de banda que permita un movimiento controlado.','Mantén la tensión en la banda incluso en la posición inicial.'], '/exercises/banded-seated-hip-abduction-main.webp', '/exercises/banded-seated-hip-abduction-main.webp'),
  ('Estiramiento de Hombros con Banda', 'banded-shoulder-stretch', 'shoulders', ARRAY['chest'], 'band', 'beginner', 'mobility', 'Un estiramiento de pie que abre los hombros y el pecho sujetando una banda tras la espalda, una mano arriba y otra abajo.', ARRAY['Sujeta una banda tras la espalda, una mano arriba y otra abajo.','Mantén una tensión ligera en la banda.','Abre el pecho y lleva los hombros suavemente atrás.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén las costillas abajo y evita arquear la espalda.','Separa más las manos para suavizar el estiramiento.'], '/exercises/banded-shoulder-stretch-main.webp', '/exercises/banded-shoulder-stretch-main.webp'),
  ('Sentadilla con Banda', 'banded-squat', 'glutes', ARRAY['hamstrings'], 'band', 'beginner', 'compound', 'Una sentadilla con peso corporal y banda sobre las rodillas para enseñar a sacar las rodillas afuera.', ARRAY['Coloca una banda elástica justo sobre las rodillas.','Pies a la anchura de los hombros, puntas ligeramente afuera.','Empuja las rodillas hacia afuera contra la banda al bajar.','Desciende hasta que los muslos queden paralelos o más abajo.','Empuja con los talones para volver a subir.'], ARRAY['Empuja las rodillas contra la banda durante toda la repetición.','Pecho arriba y espalda recta.','No dejes que las rodillas se vayan hacia adentro.'], '/exercises/banded-squat-main.webp', '/exercises/banded-squat-main.webp'),
  ('Curl de Pierna de Pie con Banda', 'banded-standing-curl', 'hamstrings', ARRAY['calves'], 'band', 'beginner', 'isolation', 'Un curl femoral de pie con una banda elástica alrededor del tobillo, útil para viajes o como finalizador con poca carga para isquiotibiales.', ARRAY['Coloca una banda elástica alrededor de un tobillo y ancla el otro extremo bajo el pie de apoyo o en un punto fijo delante de ti.','Mantente erguido, sujétate a algo si necesitas equilibrio, con ligera flexión en la pierna de apoyo.','Sube el talón con la banda hacia el glúteo, manteniendo el muslo quieto.','Contrae el isquiotibial arriba, luego baja con control hasta el estiramiento completo.','Completa todas las repeticiones de un lado y cambia de pierna.'], ARRAY['Mantén el muslo quieto — solo se mueve la parte inferior de la pierna.','Evita balancear la cadera para tomar impulso.','Usa una banda más ligera si no puedes controlar el descenso.'], '/exercises/banded-standing-curl-main.webp', '/exercises/banded-standing-curl-main.webp'),
  ('Abducción de Cadera de Pie con Banda', 'banded-standing-hip-abduction', 'glutes', NULL, 'band', 'beginner', 'isolation', 'Este ejercicio de aislamiento trabaja el glúteo medio y mayor, mejorando la estabilidad y fuerza de la cadera al abducir la pierna contra la resistencia de la banda.', ARRAY['Coloca una banda elástica alrededor de tus tobillos o justo encima de tus rodillas.','Ponte de pie con una ligera flexión de rodillas y activa tu core.','Transfiere tu peso a una pierna, manteniendo el torso estable.','Abduce lentamente la pierna libre hacia un lado, sintiendo la contracción del glúteo.','Controla el movimiento mientras regresas la pierna a la posición inicial.','Completa todas las repeticiones por lado antes de cambiar.'], ARRAY['Mantén tu torso erguido y evita inclinarte hacia un lado.','Concéntrate en un movimiento controlado, no en el impulso.','Asegúrate de que la banda mantenga la tensión durante todo el rango de movimiento.','Inicia el movimiento desde tu cadera, no desde tu pie.'], '/exercises/banded-standing-hip-abduction-main.webp', '/exercises/banded-standing-hip-abduction-main.webp'),
  ('Aducción de Cadera de Pie con Banda', 'banded-standing-hip-adduction', 'adductors', NULL, 'band', 'beginner', 'isolation', 'Una aducción de cadera de pie con banda elástica, aislando los aductores del muslo interno.', ARRAY['Ancla una banda elástica a un poste firme a la altura del tobillo.','Pasa el bucle por la pierna que trabaja, orientada hacia el anclaje.','Aléjate algunos pasos para que la banda quede tensa.','Lleva la pierna que trabaja cruzando el cuerpo hacia la otra pierna.','Regresa lentamente. Completa las repeticiones por lado y cambia.'], ARRAY['Mantén la pierna de apoyo ligeramente flexionada para estabilidad.','Mueve solo la pierna que trabaja — el torso permanece quieto.','Controla la fase excéntrica para un estiramiento completo del aductor.'], '/exercises/banded-standing-hip-adduction-main.webp', '/exercises/banded-standing-hip-adduction-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Caminata Sumo con Banda', 'banded-sumo-walk', 'glutes', ARRAY['quads'], 'band', 'beginner', 'compound', 'Una caminata en posición sumo con banda sobre las rodillas, que trabaja el glúteo medio y mayor.', ARRAY['Coloca una banda elástica justo sobre las rodillas.','Baja a una media sentadilla con los pies más anchos que los hombros.','Avanza un paso al frente en posición ancha, mantén tensión en la banda.','Sigue avanzando alternando los pies por la distancia indicada.','Permanece bajo — no te incorpores entre pasos.'], ARRAY['Mantén tensión en la banda durante toda la serie.','Quédate en media sentadilla — no te levantes entre pasos.','Da pasos cortos y controlados con las puntas ligeramente afuera.'], '/exercises/banded-sumo-walk-main.webp', '/exercises/banded-sumo-walk-main.webp'),
  ('Extensión Terminal de Rodilla con Banda', 'banded-terminal-knee-extension', 'quads', NULL, 'band', 'beginner', 'isolation', 'Un ejercicio de aislamiento que extiende la rodilla contra la banda, usado para el VMO y rehabilitación.', ARRAY['Ancla una banda elástica a un poste firme a la altura de la rodilla.','Pasa el bucle de modo que la banda quede detrás de una rodilla.','Da un paso atrás para que la banda flexione ligeramente la rodilla.','Extiende la rodilla completamente contra la banda, contrayendo el cuádriceps.','Regresa lentamente. Repeticiones por lado y cambia.'], ARRAY['Contrae fuerte el cuádriceps en la extensión completa.','Mantén el pie plano — no levantes el talón.','Mueve solo la rodilla — la cadera permanece inmóvil.'], '/exercises/banded-terminal-knee-extension-main.webp', '/exercises/banded-terminal-knee-extension-main.webp'),
  ('Estiramiento de Tríceps con Banda', 'banded-triceps-stretch', 'triceps', ARRAY['back'], 'band', 'beginner', 'mobility', 'Un estiramiento de pie que alarga el tríceps llevando una mano tras la cabeza contra la tensión de la banda.', ARRAY['Sujeta una banda que baja por la espalda, con la mano de arriba tras la cabeza.','Fija la mano de abajo en la zona lumbar.','Baja la mano de arriba hasta sentir el tríceps estirarse.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén la cabeza erguida y las costillas abajo.','Relájate y sigue respirando todo el tiempo.'], '/exercises/banded-triceps-stretch-main.webp', '/exercises/banded-triceps-stretch-main.webp'),
  ('Rueda Abdominal con Barra', 'barbell-ab-rollout', 'core', ARRAY['back'], 'barbell', 'intermediate', 'compound', 'Una rueda abdominal de rodillas usando una barra cargada con discos, que ofrece un rodamiento más suave y carga ajustable en comparación con la rueda abdominal.', ARRAY['Carga discos del mismo tamaño en ambos extremos de la barra y colócala en el suelo.','Arrodíllate detrás de la barra y agárrala a la anchura de los hombros con los brazos extendidos.','Contrae el core con fuerza, luego rueda la barra hacia adelante alejándola del cuerpo.','Avanza hasta donde puedas mantener la columna neutra: detente antes de que las caderas se hundan.','Tira de la barra de vuelta a la posición inicial contrayendo los abdominales y el dorsal.','Repite el número de repeticiones recomendado.'], ARRAY['Empieza con discos pequeños para un rango limitado; pasa a los de 20 kg para rodamientos completos.','En el momento en que la zona lumbar se arquee o caiga, detente: has superado tu rango.'], '/exercises/barbell-ab-rollout-main.webp', '/exercises/barbell-ab-rollout-main.webp'),
  ('Elevación de Talones con Barra', 'barbell-calf-raise', 'calves', NULL, 'barbell', 'intermediate', 'isolation', 'Una elevación de talones con barra sobre la espalda realizada en una plataforma, que aísla los gemelos con un rango completo.', ARRAY['Coloca una barra en la parte alta de la espalda como en una sentadilla.','Párate con las puntas de los pies en una plataforma elevada.','Sube sobre los dedos de los pies lo más alto posible.','Haz una pausa y aprieta los gemelos en la parte superior.','Baja los talones por debajo de la plataforma y repite.'], ARRAY['Evita rebotar en la parte baja del movimiento.','Mantén las rodillas extendidas pero sin bloquearlas con fuerza.','Sube y baja en vertical, sin dejar que los tobillos se venzan hacia fuera.'], '/exercises/barbell-calf-raise-main.webp', '/exercises/barbell-calf-raise-main.webp'),
  ('Elevación Frontal con Barra', 'barbell-front-raise', 'shoulders', ARRAY['chest','core'], 'barbell', 'intermediate', 'isolation', 'Una elevación frontal con barra que aísla el deltoides anterior al subir el peso con los brazos rectos hasta la altura de los hombros.', ARRAY['Párate sosteniendo una barra con agarre prono a la altura de los muslos.','Mantén los brazos extendidos y el core contraído.','Eleva la barra frente a ti hasta la altura de los hombros.','Haz una breve pausa en la parte superior.','Baja de forma controlada y repite.'], ARRAY['Usa un peso moderado para no balancear el cuerpo.','Evita encoger los hombros mientras subes la barra.','Mantén las muñecas neutras, sin dejar que se doblen hacia atrás.'], '/exercises/barbell-front-raise-main.webp', '/exercises/barbell-front-raise-main.webp'),
  ('Puente de Glúteos con Barra', 'barbell-glute-bridge', 'glutes', ARRAY['hamstrings'], 'barbell', 'intermediate', 'compound', 'Un puente de glúteos con carga usando una barra para mayor resistencia.', ARRAY['Acuéstate en el suelo con una barra sobre las caderas y las rodillas flexionadas.','Eleva las caderas apretando los glúteos.','Aguanta en la parte superior con las caderas completamente extendidas.','Baja con control.','Repite.'], ARRAY['Evita arquear la zona lumbar al extender la cadera.','Empuja con los talones, no con las puntas de los pies.','Mete la barbilla y mantén la parte alta de la espalda apoyada.'], '/exercises/barbell-glute-bridge-main.webp', '/exercises/barbell-glute-bridge-main.webp'),
  ('Zancada con Barra', 'barbell-lunge', 'glutes', ARRAY['back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una zancada hacia delante con la barra sobre la parte alta de la espalda, entrenando cuádriceps y glúteos una pierna a la vez.', ARRAY['Coloca una barra en la parte alta de la espalda y párate erguido.','Da un paso adelante con una pierna en una zancada larga.','Baja la rodilla trasera hacia el suelo hasta que el muslo delantero quede paralelo.','Impulsa a través del talón delantero para volver a la posición inicial.','Completa las repeticiones de un lado, luego cambia.'], ARRAY['Da una zancada lo bastante larga para que la rodilla delantera quede sobre el tobillo.','Mantén el torso erguido y el core contraído bajo la barra.','Empuja el suelo con el talón delantero, no con los dedos.'], '/exercises/barbell-lunge-main.webp', '/exercises/barbell-lunge-main.webp'),
  ('Extensión de Barra por Encima de la Cabeza', 'barbell-overhead-extension', 'triceps', NULL, 'barbell', 'intermediate', 'isolation', 'Este ejercicio de aislamiento trabaja eficazmente el tríceps braquial al extender los codos por encima de la cabeza, promoviendo la hipertrofia y fuerza muscular.', ARRAY['Carga una barra con el peso adecuado y ponte de pie o siéntate con la columna neutra.','Agarra la barra con un agarre prono, al ancho de los hombros, y presiónala por encima de tu cabeza.','Baja lentamente la barra detrás de tu cabeza flexionando los codos, manteniendo los brazos estables.','Extiende los codos para presionar la barra de vuelta a la posición inicial por encima de la cabeza, contrayendo tus tríceps.','Mantén el control durante todo el movimiento, evitando el impulso.'], ARRAY['Mantén los codos pegados y apuntando hacia adelante para maximizar la activación del tríceps y proteger tus hombros.','Controla la fase excéntrica (descenso) para mejorar la tensión muscular y el crecimiento.','Evita arquear demasiado la espalda baja; contrae tu core para mantener la estabilidad.'], '/exercises/barbell-overhead-extension-main.webp', '/exercises/barbell-overhead-extension-main.webp'),
  ('Curl Predicador con Barra', 'barbell-preacher-curl', 'biceps', NULL, 'barbell', 'intermediate', 'isolation', 'Este ejercicio de aislamiento trabaja el bíceps braquial y el braquial al fijar los brazos en un banco predicador, minimizando el impulso y maximizando la tensión muscular.', ARRAY['Siéntate en un banco predicador con el pecho contra la almohadilla, sujetando una barra con agarre supino al ancho de los hombros.','Apoya firmemente tus brazos en la almohadilla, asegurándote de que tus codos estén ligeramente flexionados al inicio.','Sube la barra contrayendo tus bíceps, manteniendo tus brazos inmóviles sobre la almohadilla.','Aprieta los bíceps en la parte superior del movimiento, enfocándote en la contracción máxima.','Baja lentamente la barra a la posición inicial, controlando la fase excéntrica.','Extiende completamente tus brazos en la parte inferior para lograr un estiramiento completo en los bíceps.'], ARRAY['Mantén una tensión constante en los bíceps durante todo el rango de movimiento.','Evita levantar los codos de la almohadilla; esto indica que estás usando demasiado peso o impulso.','Concéntrate en una fase excéntrica (bajada) controlada para maximizar el daño muscular y el crecimiento.','Mantén tus muñecas rectas y alineadas con tus antebrazos para prevenir tensiones.'], '/exercises/barbell-preacher-curl-main.webp', '/exercises/barbell-preacher-curl-main.webp'),
  ('Pullover con Barra', 'barbell-pullover', 'back', ARRAY['triceps'], 'barbell', 'intermediate', 'compound', 'Un movimiento compuesto que estira y trabaja el dorsal y el pectoral a través de un arco amplio.', ARRAY['Acuéstate en un banco con una barra sostenida sobre el pecho.','Baja la barra hacia atrás sobre tu cabeza en un arco.','Tírala de vuelta al inicio sobre el pecho.','Repite.'], ARRAY['Mantén una ligera flexión en los codos.','Activa el dorsal para impulsar la barra de vuelta.'], '/exercises/barbell-pullover-main.webp', '/exercises/barbell-pullover-main.webp'),
  ('Remo con Barra para Deltoides Posterior', 'barbell-rear-delt-row', 'shoulders', ARRAY['back','traps'], 'barbell', 'intermediate', 'compound', 'Un remo con barra inclinado con los codos abiertos que traslada el énfasis de los dorsales a los deltoides posteriores y la parte alta de la espalda.', ARRAY['Inclínate en las caderas con la espalda plana hasta que el torso quede casi paralelo al suelo.','Sostén una barra con agarre prono, más ancho que la anchura de los hombros, brazos colgando.','Rema la barra hacia el pecho superior con los codos abiertos hacia los lados.','Haz una pausa y aprieta los deltoides posteriores y la parte alta de la espalda en la cima.','Baja la barra de forma controlada y repite.'], ARRAY['Jala con los codos, no con las manos: piensa en impulsarlos hacia arriba y hacia afuera.','Usa una carga menor que en un remo estándar; el agarre ancho reduce el brazo de palanca.'], '/exercises/barbell-rear-delt-row-main.webp', '/exercises/barbell-rear-delt-row-main.webp'),
  ('Zancada Inversa con Barra', 'barbell-reverse-lunge', 'glutes', ARRAY['back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una zancada con barra dando el paso hacia atrás en lugar de hacia delante, manteniendo la tibia delantera vertical mientras carga cuádriceps y glúteos.', ARRAY['Coloca una barra en la parte alta de la espalda y párate erguido.','Da un paso hacia atrás con un pie en una zancada larga.','Baja la rodilla trasera hacia el suelo de forma controlada.','Impulsa a través del talón delantero para volver a la posición inicial.','Completa las repeticiones de un lado, luego cambia.'], ARRAY['Da el paso atrás lo bastante largo para que la tibia delantera quede casi vertical.','Baja la rodilla trasera en línea recta en lugar de inclinarte hacia delante.','Mantén el pecho erguido y las caderas alineadas.'], '/exercises/barbell-reverse-lunge-main.webp', '/exercises/barbell-reverse-lunge-main.webp'),
  ('Remo con Barra Inclinado', 'barbell-row', 'back', ARRAY['biceps','shoulders'], 'barbell', 'intermediate', 'compound', 'Un movimiento de jalón compuesto que trabaja la parte superior e intermedia de la espalda.', ARRAY['Inclínate en las caderas con una ligera flexión de rodillas.','Agarra la barra ligeramente más ancho que la anchura de los hombros.','Tira de la barra hacia el pecho inferior apretando los omóplatos.','Baja la barra de forma controlada.','Repite.'], ARRAY['Mantén el torso a aproximadamente 45 grados.','No uses el impulso para balancear el peso.'], '/exercises/barbell-row-main.webp', '/exercises/barbell-row-main.webp'),
  ('Curl de Muñeca con Barra', 'barbell-wrist-curl', 'forearms', NULL, 'barbell', 'beginner', 'isolation', 'Un curl de muñeca con barra que aísla los flexores del antebrazo para fuerza de agarre y tamaño.', ARRAY['Siéntate en un banco con los antebrazos sobre los muslos, palmas hacia arriba.','Sujeta una barra con las manos a la anchura de los hombros, muñecas fuera de las rodillas.','Deja que la barra ruede hasta las puntas de los dedos.','Sube la barra flexionando las muñecas.','Baja con control.'], ARRAY['Mueve solo la muñeca — los antebrazos permanecen quietos.','Rueda la barra a las puntas de los dedos para el rango completo.','Usa un agarre sin pulgar si te resulta más cómodo.'], '/exercises/barbell-wrist-curl-main.webp', '/exercises/barbell-wrist-curl-main.webp'),
  ('Golpe Doble con Cuerdas de Batalla', 'battle-rope-double-slam', 'shoulders', ARRAY['forearms','glutes','core','quads','traps'], 'bodyweight', 'intermediate', 'cardio', 'Un ejercicio de acondicionamiento en el que ambos extremos de la cuerda suben y se golpean contra el suelo a la vez, generando una gran onda por repetición en lugar de las ondas alternas del ejercicio clásico.', ARRAY['Toma un extremo de la cuerda en cada mano y colócate frente al anclaje, lo bastante atrás como para que las cuerdas queden algo destensadas.','Separa los pies algo más que la anchura de las caderas y baja a una sentadilla de cuarto, con el pecho alto.','Sube ambos brazos a la vez, dejando que las cuerdas se eleven por delante mientras extiendes la cadera.','Golpea ambos extremos contra el suelo al mismo tiempo, flexionando por la cadera y empujando desde los dorsales.','Aprovecha el rebote para encadenar el siguiente golpe, manteniendo ambos brazos al unísono en lugar de alternarlos.','Sigue golpeando el tiempo o las repeticiones deseadas.'], ARRAY['Los dos brazos se mueven juntos — en cuanto empiezan a alternarse estás haciendo el ejercicio de ondas clásico, que es otro ejercicio distinto.','Impulsa el golpe con la cadera y los dorsales en vez de con los brazos, o los hombros se agotarán mucho antes que los pulmones.','Colócate a la distancia correcta del anclaje: demasiado cerca la cuerda queda floja, demasiado lejos no consigues meterle onda.'], '/exercises/battle-rope-double-slam-main.webp', '/exercises/battle-rope-double-slam-main.webp'),
  ('Cuerdas de Batalla', 'battle-ropes', 'shoulders', ARRAY['forearms','quads','core','traps'], 'bodyweight', 'intermediate', 'cardio', 'Un ejercicio de acondicionamiento de alta intensidad con cuerdas gruesas, trabaja espalda alta, hombros y agarre.', ARRAY['Ancla las cuerdas a un punto fijo y agarra un extremo en cada mano.','Da unos pasos atrás para que las cuerdas tengan tensión moderada.','Baja a una media sentadilla con los pies a la anchura de los hombros.','Mueve cada brazo arriba y abajo rápidamente generando ondas en las cuerdas.','Continúa durante el intervalo de trabajo indicado.'], ARRAY['Permanece en media sentadilla todo el intervalo.','Genera fuerza desde piernas y caderas, no solo desde los brazos.','Mantén las ondas constantes y compactas.'], '/exercises/battle-ropes-main.webp', '/exercises/battle-ropes-main.webp'),
  ('Caminata del Oso', 'bear-crawl', 'shoulders', ARRAY['core','quads','triceps'], NULL, 'beginner', 'compound', 'Un gateo en cuadrupedia sobre manos y puntas de los pies con las rodillas suspendidas justo por encima del suelo, que desarrolla la estabilidad del hombro y el control del core al desplazarse hacia adelante.', ARRAY['Empieza en cuadrupedia con las manos bajo los hombros y las rodillas bajo las caderas.','Apoya las puntas de los pies y eleva las rodillas unos centímetros del suelo.','Con la espalda plana y las caderas bajas, avanza juntos la mano derecha y el pie izquierdo.','Luego mueve la mano izquierda y el pie derecho, gateando hacia adelante con ritmo controlado.','Mantén el core firme y evita que las caderas se balanceen de lado a lado.'], ARRAY['Mueve juntos la mano y el pie opuestos, como un gateo exagerado.','Mantén las rodillas bajas y las caderas niveladas: que no suban ni se balanceen.'], '/exercises/bear-crawl-main.webp', '/exercises/bear-crawl-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Encogimiento de Hombros con Barra Detrás de la Espalda', 'behind-the-back-barbell-shrug', 'traps', ARRAY['forearms','back'], 'barbell', 'intermediate', 'isolation', 'Un encogimiento de hombros con la barra sujeta por detrás del cuerpo, una variante que concentra el trabajo en el trapecio.', ARRAY['Párate sosteniendo una barra detrás de la espalda con agarre prono.','Mantén los brazos extendidos y el pecho hacia arriba.','Encoge los hombros directamente hacia las orejas.','Haz una pausa y aprieta en la parte superior.','Baja de forma controlada y repite.'], ARRAY['Evita hacer círculos con los hombros al subir.','Mantén la cabeza neutra, sin adelantar la barbilla.','Elige un peso que permita un recorrido completo hacia arriba.'], '/exercises/behind-the-back-barbell-shrug-main.webp', '/exercises/behind-the-back-barbell-shrug-main.webp'),
  ('Jalón al Cuello Detrás de la Cabeza', 'behind-the-neck-lat-pulldown', 'back', ARRAY['shoulders','traps'], 'cable', 'advanced', 'compound', 'Un jalón al dorsal con agarre ancho llevado detrás de la cabeza, que trabaja la parte superior del dorsal y los trapecios: requiere movilidad de hombro completa sobre la cabeza.', ARRAY['Siéntate en la máquina de jalón con los muslos asegurados bajo el pad.','Agarra la barra con un agarre ancho prono, más ancho que la anchura de los hombros.','Mantén el torso erguido e inclina la barbilla ligeramente hacia adelante.','Tira de la barra hacia abajo detrás de la cabeza hasta que toque la base del cuello.','Vuelve de forma controlada al estiramiento completo sobre la cabeza.','Repite el número de repeticiones recomendado.'], ARRAY['Solo realiza este ejercicio si tienes movilidad de hombro completa y sin dolor sobre la cabeza.','Usa una carga moderada: no es un levantamiento de fuerza, es un accesorio de hipertrofia.'], '/exercises/behind-the-neck-lat-pulldown-main.webp', '/exercises/behind-the-neck-lat-pulldown-main.webp'),
  ('Press Detrás del Cuello', 'behind-the-neck-press', 'shoulders', ARRAY['traps','triceps'], 'barbell', 'intermediate', 'compound', 'Un press vertical con barra realizado por detrás de la nuca, dirigido al deltoides anterior y lateral.', ARRAY['Siéntate o párate con una barra descansando en la parte alta de los trapecios detrás del cuello.','Agarra la barra más ancho que la anchura de los hombros.','Empuja la barra directamente sobre la cabeza hasta que los brazos estén extendidos.','Baja la barra de vuelta a la posición inicial de forma controlada.','Repite el número de repeticiones deseado.'], ARRAY['Trabaja primero la movilidad de hombros si la posición resulta incómoda.','Baja la barra solo hasta donde tu rango lo permita.','Mantén el core firme para no arquear la zona lumbar.'], '/exercises/behind-the-neck-press-main.webp', '/exercises/behind-the-neck-press-main.webp'),
  ('Dominada tras nuca', 'behind-the-neck-pull-ups', 'back', ARRAY['biceps','shoulders','traps'], 'bodyweight', 'advanced', 'compound', 'Una dominada con agarre ancho en la que se tira lo suficientemente alto como para que la barra pase por detrás de la cabeza en lugar de por debajo de la barbilla, lo que obliga a los hombros a llegar al final de su rotación externa.', ARRAY['Sujeta la barra de dominadas en pronación, con las manos más separadas que los hombros, y cuélgate con los brazos extendidos y las piernas juntas.','Mantén el torso vertical en lugar de inclinarte hacia atrás y tira de los codos hacia abajo y hacia los lados.','Sigue tirando hasta que la barra pase por detrás de la cabeza y la nuca quede a su altura, sin que la barra llegue a tocarte el cuello.','Baja de forma controlada hasta la suspensión completa, manteniendo la cabeza quieta en lugar de dejar que se desplace hacia adelante.','Repite el número de repeticiones deseado.'], ARRAY['Esta variante está desaconsejada de forma generalizada. Terminar por detrás de la cabeza carga el hombro en el final de su rotación externa, donde la articulación tiene menos capacidad de protegerse, y cualquier contacto entre la barra y el cuello transmite esa carga a la columna cervical.','Una dominada normal o con agarre ancho trabaja los mismos músculos en el mismo rango de movimiento del hombro: nada en el desarrollo de la espalda exige que la barra pase por detrás de la cabeza, así que no hay ningún beneficio que compense el riesgo.','Si aun así la haces, detente bastante antes de que la barra toque el cuello, y descártala por completo si no tienes movilidad de hombro completa y sin dolor por encima de la cabeza o si tienes antecedentes de problemas de hombro o cuello.'], '/exercises/behind-the-neck-pull-ups-main.webp', '/exercises/behind-the-neck-pull-ups-main.webp'),
  ('Estiramiento de Aductores en Banco', 'bench-adductor-stretch', 'adductors', ARRAY['hamstrings'], 'bench', 'beginner', 'mobility', 'Un estiramiento de pie con una pierna estirada apoyada en el banco hacia el lado para alargar el aductor.', ARRAY['Ponte de lado al banco.','Apoya una pierna estirada sobre el banco hacia el lado.','Mantén el torso erguido y desplázate suavemente hacia el banco.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén ambas piernas estiradas.','Mantén el pie de apoyo apuntando al frente.'], '/exercises/bench-adductor-stretch-main.webp', '/exercises/bench-adductor-stretch-main.webp'),
  ('Estiramiento de Tobillo en Banco', 'bench-ankle-stretch', 'calves', NULL, 'bench', 'beginner', 'mobility', 'Un estiramiento de pie con el pie plano en el banco, llevando la rodilla por delante de los dedos para flexionar el tobillo.', ARRAY['Coloca un pie entero plano sobre el banco.','Mantén el torso erguido.','Lleva esa rodilla hacia adelante por encima de los dedos.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén el talón apoyado en el banco.','Muévete despacio y mantén el pie plano.'], '/exercises/bench-ankle-stretch-main.webp', '/exercises/bench-ankle-stretch-main.webp'),
  ('Estiramiento Búlgaro en Banco', 'bench-bulgarian-split-stretch', 'core', ARRAY['glutes'], 'bench', 'beginner', 'mobility', 'Un estiramiento en zancada con el pie trasero en un banco, bajando la cadera para abrir los flexores de cadera y el cuádriceps.', ARRAY['Apoya el empeine del pie trasero en un banco detrás de ti.','Coloca el pie delantero plano y flexiona esa rodilla.','Baja la cadera recto hacia abajo.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Apóyate en una pared si lo necesitas.','Mantén el torso erguido.'], '/exercises/bench-bulgarian-split-stretch-main.webp', '/exercises/bench-bulgarian-split-stretch-main.webp'),
  ('Estiramiento de Pantorrilla en Banco', 'bench-calf-stretch', 'calves', NULL, 'bench', 'beginner', 'mobility', 'Un estiramiento de pie con la planta del pie en el borde del banco, dejando caer el talón para alargar la pantorrilla.', ARRAY['Coloca la planta de un pie en el borde del banco.','Mantén esa rodilla estirada.','Deja caer el talón por debajo de los dedos.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Sujétate del banco o de una pared para equilibrarte.','Mantén el movimiento lento y controlado.'], '/exercises/bench-calf-stretch-main.webp', '/exercises/bench-calf-stretch-main.webp'),
  ('Estiramiento de Pecho en Banco', 'bench-chest-stretch', 'chest', ARRAY['shoulders'], 'bench', 'beginner', 'mobility', 'Un estiramiento de rodillas con las manos detrás en el banco, bajando la cadera para abrir el pecho y los hombros.', ARRAY['Arrodíllate de espaldas al banco.','Coloca ambas manos detrás en el borde del banco.','Baja la cadera para abrir el pecho.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén los hombros abajo, lejos de las orejas.','Estira hasta una tensión leve, nunca hasta el dolor.'], '/exercises/bench-chest-stretch-main.webp', '/exercises/bench-chest-stretch-main.webp'),
  ('Postura del Niño en Banco', 'bench-childs-pose', 'back', NULL, 'bench', 'beginner', 'mobility', 'Un estiramiento de rodillas con los brazos sobre el banco, llevando la cadera atrás para alargar los dorsales y la zona lumbar.', ARRAY['Arrodíllate en el suelo frente a un banco.','Extiende ambos brazos al frente y apóyalos en el banco.','Lleva la cadera hacia los talones y deja caer el pecho.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén los brazos estirados y relaja el cuello.','Relájate y sigue respirando todo el tiempo.'], '/exercises/bench-childs-pose-main.webp', '/exercises/bench-childs-pose-main.webp'),
  ('Estiramiento Couch en Banco', 'bench-couch-stretch', 'core', NULL, 'bench', 'beginner', 'mobility', 'Un estiramiento profundo de cuádriceps y flexores de cadera con la espinilla trasera apoyada en el frente del banco.', ARRAY['Arrodíllate con la espinilla trasera contra el frente del banco.','Coloca el pie delantero plano en el suelo.','Lleva el torso erguido hasta que se estire el frente del muslo.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Aprieta el glúteo trasero para proteger la zona lumbar.','Acolcha la rodilla trasera con un cojín.'], '/exercises/bench-couch-stretch-main.webp', '/exercises/bench-couch-stretch-main.webp'),
  ('Fondos en Banco', 'bench-dips', 'triceps', ARRAY['shoulders','chest'], NULL, 'intermediate', 'compound', 'Un ejercicio de fondos apoyado en un banco que trabaja principalmente el tríceps con el propio peso corporal.', ARRAY['Siéntate en un banco y coloca las manos en el borde junto a las caderas.','Desliza las caderas fuera del banco con las piernas extendidas.','Baja el cuerpo flexionando los codos hasta 90 grados.','Empuja con las palmas para volver a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Mantén la espalda cerca del banco durante todo el recorrido.','No dejes que los hombros se hundan hacia las orejas.','Flexiona las rodillas si necesitas una versión más fácil.'], '/exercises/bench-dips-main.webp', '/exercises/bench-dips-main.webp'),
  ('Estiramiento Figura 4 de Glúteos en Banco', 'bench-figure-4-glute-stretch', 'glutes', NULL, 'bench', 'beginner', 'mobility', 'Un estiramiento sentado en banco con un tobillo cruzado sobre la rodilla, inclinándose para trabajar el glúteo.', ARRAY['Siéntate en el extremo de un banco.','Cruza un tobillo sobre la rodilla opuesta.','Mantén la espalda recta e inclínate sobre la pierna cruzada.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Deja que la rodilla cruzada caiga hacia afuera.','Inclínate desde las caderas, manteniendo el pecho abierto.'], '/exercises/bench-figure-4-glute-stretch-main.webp', '/exercises/bench-figure-4-glute-stretch-main.webp'),
  ('Estiramiento de Isquiotibiales en Banco', 'bench-hamstring-stretch', 'hamstrings', ARRAY['back'], 'bench', 'beginner', 'mobility', 'Un estiramiento de pie con el talón en un banco, inclinándose sobre la pierna estirada para alargar el isquiotibial.', ARRAY['Coloca un talón en el banco con esa pierna estirada.','Mantente erguido sobre la pierna de apoyo.','Inclínate desde las caderas sobre la pierna elevada.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén la espalda recta al inclinarte.','Mantén la pierna elevada recta, con los dedos arriba.'], '/exercises/bench-hamstring-stretch-main.webp', '/exercises/bench-hamstring-stretch-main.webp'),
  ('Estiramiento de Dorsales en Banco', 'bench-lat-stretch', 'back', ARRAY['shoulders'], 'bench', 'beginner', 'mobility', 'Un estiramiento de rodillas con las manos en el banco, hundiendo el pecho hacia el suelo para alargar los dorsales.', ARRAY['Arrodíllate en el suelo frente a un banco.','Coloca ambas manos sobre el banco.','Lleva la cadera atrás y deja caer el pecho.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén los brazos estirados y la cabeza entre ellos.','Relájate y sigue respirando todo el tiempo.'], '/exercises/bench-lat-stretch-main.webp', '/exercises/bench-lat-stretch-main.webp'),
  ('Encogimiento de Piernas en Banco', 'bench-leg-pull-in', 'core', NULL, NULL, 'beginner', 'isolation', 'Un ejercicio de core en decúbito supino sobre un banco plano que trabaja el recto abdominal llevando las rodillas hacia el pecho.', ARRAY['Túmbate boca arriba sobre un banco plano y agárrate a los lados por encima de la cabeza.','Extiende las piernas rectas con los talones justo por encima de la superficie del banco.','Lleva las rodillas hacia el pecho levantando ligeramente las caderas del banco.','Devuelve las piernas a la posición extendida de forma controlada sin apoyar los talones.','Repite el número de repeticiones indicado.'], ARRAY['Presiona la zona lumbar contra el banco para reducir la participación del psoas.','Controla la fase excéntrica; no dejes que la gravedad baje las piernas sin control.','Contrae el abdomen en el punto más alto de cada repetición.'], '/exercises/bench-leg-pull-in-main.webp', '/exercises/bench-leg-pull-in-main.webp'),
  ('Press de Banca con Barra', 'bench-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Un movimiento compuesto de empuje que trabaja el pecho, los hombros y los tríceps.', ARRAY['Acuéstate en el banco con los ojos bajo la barra.','Agarra la barra ligeramente más ancho que la anchura de los hombros.','Saca la barra del rack y bájala hasta el centro del pecho.','Empuja la barra de vuelta hasta la extensión completa de los brazos.','Repite el número de repeticiones deseado.'], ARRAY['Mantén los pies planos en el suelo.','Conserva una ligera curvatura en la zona lumbar.','Impulsa con las piernas para dar estabilidad.'], '/exercises/bench-press-main.webp', '/exercises/bench-press-main.webp'),
  ('Remo en Banco', 'bench-pull', 'back', ARRAY['biceps','shoulders','traps'], 'barbell', 'intermediate', 'compound', 'Un remo tumbado boca abajo sobre un banco elevado que centra el trabajo en la espalda al apoyar el torso.', ARRAY['Acuéstate boca abajo en un banco elevado con los brazos colgando rectos hacia abajo.','Agarra una barra o mancuernas debajo de ti.','Rema el peso hasta la parte inferior del banco.','Aprieta los omóplatos en la parte superior.','Baja de forma controlada y repite.'], ARRAY['Mantén el pecho pegado al banco durante toda la serie.','Tira con los codos en lugar de con las manos.','Evita los tirones bruscos al iniciar cada repetición.'], '/exercises/bench-pull-main.webp', '/exercises/bench-pull-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Pullover con Barra y Brazos Flexionados', 'bent-arm-barbell-pullover', 'back', ARRAY['core','triceps'], 'barbell', 'intermediate', 'isolation', 'Un pullover con barra y codos flexionados que lleva el peso por detrás de la cabeza para trabajar dorsales y pectoral.', ARRAY['Acuéstate en un banco sosteniendo una barra sobre el pecho con los codos flexionados.','Mantén los codos flexionados durante todo el movimiento.','Baja la barra detrás de la cabeza en un arco.','Tira de la barra de vuelta sobre el pecho usando el dorsal.','Repite el número de repeticiones deseado.'], ARRAY['Mantén la cadera y la zona lumbar en contacto con el banco.','Baja solo hasta donde notes un estiramiento cómodo.','Empieza con un peso ligero hasta dominar la trayectoria.'], '/exercises/bent-arm-barbell-pullover-main.webp', '/exercises/bent-arm-barbell-pullover-main.webp'),
  ('Pullover con Barra Z y Brazos Flexionados', 'bent-arm-ez-bar-pullover', 'back', ARRAY['shoulders','core','triceps'], 'barbell', 'intermediate', 'compound', 'Un pullover con brazos flexionados en un banco plano usando una barra Z, más amigable para las muñecas que la versión con barra recta, manteniendo el estiramiento profundo del dorsal y el pectoral.', ARRAY['Acuéstate en un banco plano sosteniendo una barra Z con un agarre prono estrecho en las curvas internas.','Comienza con la barra sobre el pecho, codos flexionados a aproximadamente 90 grados.','Mantén el ángulo de los codos fijo y baja la barra en un arco sobre la cabeza hasta sentir un estiramiento profundo en el dorsal y el pectoral.','Tira de la barra de vuelta sobre el pecho por el mismo arco, sin extender los codos.','Repite el número de repeticiones recomendado.'], ARRAY['El ángulo de los codos permanece fijo: solo se mueve el hombro.','Carga menor que en un pullover con brazos extendidos: el rango es mayor y el brazo de palanca es menor.','Si la zona lumbar se arquea, planta los pies con más firmeza y aprieta el abdomen.'], '/exercises/bent-arm-ez-bar-pullover-main.webp', '/exercises/bent-arm-ez-bar-pullover-main.webp'),
  ('Remo con Mancuernas Inclinado', 'bent-over-db-row', 'back', ARRAY['biceps','shoulders','traps'], 'dumbbell', 'intermediate', 'compound', 'Un remo inclinado a dos brazos con una mancuerna en cada mano, que trabaja la espalda y exige estabilidad.', ARRAY['Ponte de pie con los pies a la anchura de las caderas, sujetando una mancuerna en cada mano a los lados, con las palmas hacia dentro.','Flexiona las caderas con la espalda recta hasta que el torso quede a unos 30–45 grados de la horizontal, con las mancuernas colgando justo debajo de los hombros.','Activa el core y tira de ambas mancuernas hacia arriba y ligeramente atrás, llevando los codos por detrás de las costillas.','Aprieta la parte alta de la espalda arriba, manteniendo los codos pegados.','Baja de forma controlada hasta la posición inicial con los brazos completamente estirados.','Repite el número de repeticiones recomendado.'], ARRAY['El ángulo del torso se mantiene fijo todo el rato; no te incorpores para ayudar al peso.','Tira hacia las costillas bajas o el abdomen, no hacia el pecho; así mantienes el dorsal cargado.','Si la lumbar se redondea, flexiona menos y recoloca antes de la siguiente serie.'], '/exercises/bent-over-db-row-main.webp', '/exercises/bent-over-db-row-main.webp'),
  ('Remo con Barra Z Inclinado', 'bent-over-ez-bar-row', 'back', ARRAY['biceps','shoulders'], 'barbell', 'intermediate', 'compound', 'Un movimiento de jalón horizontal con barra Z para un ejercicio de remo de espalda amigable con las muñecas.', ARRAY['Sostén una barra Z con agarre prono e inclínate en las caderas a 45 grados.','Tira de la barra hacia la parte inferior de las costillas.','Baja de forma controlada.','Repite.'], ARRAY['Mantén la espalda plana durante todo el movimiento.','Inicia el movimiento con los codos, no con las manos.'], '/exercises/bent-over-ez-bar-row-main.webp', '/exercises/bent-over-ez-bar-row-main.webp'),
  ('Curl de Bíceps con Mancuernas', 'bicep-curl', 'biceps', ARRAY['forearms'], 'dumbbell', 'beginner', 'isolation', 'Un ejercicio de aislamiento que trabaja los bíceps.', ARRAY['Párate sosteniendo mancuernas a los lados, palmas hacia adelante.','Sube las mancuernas hacia los hombros.','Aprieta en la parte superior, luego baja de forma controlada.','Repite.'], ARRAY['Mantén los codos pegados a los costados.','Evita balancear las mancuernas.'], '/exercises/bicep-curl-main.webp', '/exercises/bicep-curl-main.webp'),
  ('Crunch de Bicicleta', 'bicycle-crunch', 'core', NULL, NULL, 'beginner', 'compound', 'Una variación dinámica del crunch que trabaja tanto el recto abdominal como los oblicuos.', ARRAY['Acuéstate boca arriba con las manos detrás de la cabeza y las piernas elevadas.','Acerca una rodilla al pecho mientras rotas el torso para encontrarla con el codo opuesto.','Extiende esa pierna mientras traes la otra rodilla hacia adentro.','Continúa alternando en un movimiento de pedaleo.','Repite.'], ARRAY['No tires del cuello con las manos.','Lleva el hombro hacia la rodilla, no solo el codo.','Mantén la zona lumbar apoyada en el suelo.'], '/exercises/bicycle-crunch-main.webp', '/exercises/bicycle-crunch-main.webp'),
  ('Bird-Dog', 'bird-dog', 'back', ARRAY['glutes'], NULL, 'beginner', 'compound', 'Un ejercicio de estabilidad del core que extiende el brazo y la pierna opuestos para trabajar los erectores espinales y el core profundo.', ARRAY['Comienza a cuatro patas con la columna en posición neutra.','Extiende el brazo derecho hacia adelante y la pierna izquierda hacia atrás simultáneamente.','Aguanta un momento, luego vuelve.','Repite en el otro lado.','Alterna.'], ARRAY['Muévete lentamente y con control.','Mantén las caderas niveladas en todo momento.'], '/exercises/bird-dog-main.webp', '/exercises/bird-dog-main.webp'),
  ('Bird-Dog Isométrico', 'bird-dog-hold', 'back', ARRAY['glutes','core','shoulders'], NULL, 'intermediate', 'compound', 'Un ejercicio isométrico de core a cuatro patas que extiende un brazo y la pierna contraria manteniendo la columna estable.', ARRAY['Comienza a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.','Extiende un brazo hacia adelante y la pierna opuesta hacia atrás.','Mantén el core apretado y el cuerpo nivelado.','Aguanta la posición sin rotar el torso.','Mantén el tiempo indicado. Completa en un lado, luego cambia.'], ARRAY['Imagina que llevas un vaso de agua sobre la zona lumbar.','Evita que la cadera rote al extender la pierna.','Empuja el suelo con la mano de apoyo para estabilizar el hombro.'], '/exercises/bird-dog-hold-main.webp', '/exercises/bird-dog-hold-main.webp'),
  ('Postura del Barco', 'boat-pose', 'core', ARRAY['back','quads'], NULL, 'intermediate', 'compound', 'Un equilibrio sentado sobre los isquiones con las piernas elevadas y el pecho alto: la forma de V carga los flexores de la cadera y toda la parte frontal del tronco.', ARRAY['Siéntate en el suelo con las rodillas flexionadas y los pies apoyados, las manos detrás de los muslos.','Inclínate hacia atrás hasta equilibrarte justo por detrás de los isquiones y eleva el pecho para mantener la columna larga.','Sube las espinillas hasta dejarlas paralelas al suelo y estira las piernas todo lo que la espalda pueda mantenerse plana.','Extiende los brazos hacia delante junto a las piernas y mantén la posición durante el tiempo indicado.','Baja los pies de forma controlada para terminar.'], ARRAY['Mantén el pecho alto; en cuanto la espalda se redondee, vuelve a flexionar las rodillas.','Sujétate por detrás de los muslos si los isquiotibiales te limitan más que el core.','Respira de forma constante en lugar de aguantar el aire.'], '/exercises/boat-pose-main.webp', '/exercises/boat-pose-main.webp'),
  ('Elevación de Talones con Peso Corporal', 'bodyweight-calf-raise', 'calves', NULL, NULL, 'beginner', 'isolation', 'Una elevación de talones con el propio peso corporal, un ejercicio básico para fortalecer los gemelos.', ARRAY['Colócate de pie con los pies separados al ancho de las caderas sobre una superficie plana.','Sube de puntillas lo más alto posible.','Aprieta los gemelos en la parte superior.','Baja los talones al suelo de forma controlada.','Repite el número deseado de repeticiones.'], ARRAY['Reparte el peso entre todos los dedos al subir.','Mantén las piernas rectas para centrar el trabajo en el gemelo.','Fija la mirada en un punto para mantener el equilibrio.'], '/exercises/bodyweight-calf-raise-main.webp', '/exercises/bodyweight-calf-raise-main.webp'),
  ('Buenos Días con Peso Corporal', 'bodyweight-good-morning', 'back', ARRAY['glutes'], NULL, 'beginner', 'compound', 'Una bisagra de cadera con el propio peso corporal que fortalece los erectores espinales y los isquiotibiales.', ARRAY['Colócate de pie con los pies separados al ancho de las caderas y las manos detrás de la cabeza.','Mantén una ligera flexión en las rodillas y contrae el core.','Bisagra en las caderas y baja el torso hasta quedar casi paralelo al suelo.','Impulsa las caderas hacia adelante para volver a la posición erguida.','Repite el número deseado de repeticiones.'], ARRAY['Empuja la cadera hacia atrás como si cerraras un cajón.','Mantén la espalda recta durante toda la bajada.','Detén el descenso si notas que la zona lumbar se redondea.'], '/exercises/bodyweight-good-morning-main.webp', '/exercises/bodyweight-good-morning-main.webp'),
  ('Elevación Lateral con Peso Corporal', 'bodyweight-lateral-raise', 'shoulders', ARRAY['traps'], NULL, 'beginner', 'isolation', 'Un movimiento de aislamiento de hombros sin equipamiento para desarrollar el ancho del deltoides lateral.', ARRAY['Párate erguido con los brazos colgando a los lados.','Levanta ambos brazos hacia los lados con un ligero codo doblado hasta la altura de los hombros.','Haz una pausa breve arriba.','Baja lentamente a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Lidera el movimiento con los codos, no con las manos.','Evita encoger los hombros en la parte superior.','Controla el descenso para maximizar el tiempo bajo tensión.'], '/exercises/bodyweight-lateral-raise-main.webp', '/exercises/bodyweight-lateral-raise-main.webp'),
  ('Press por Encima de la Cabeza con Peso Corporal', 'bodyweight-overhead-press', 'shoulders', ARRAY['core','traps'], NULL, 'beginner', 'compound', 'Un press vertical de peso corporal en posición de pica que imita el patrón del press de hombros sin material.', ARRAY['Colócate de pie frente a una pared en posición de pica con las manos en el suelo.','Acerca los pies a la pared para lograr una línea corporal más vertical.','Baja la cabeza hacia el suelo flexionando los codos.','Presiona con las manos para extender los brazos.','Repite el número deseado de repeticiones.'], ARRAY['Da pasos cortos con los pies para ajustar la dificultad.','Mantén el cuello neutro, con la mirada entre las manos.','Reparte el peso por toda la palma para aliviar las muñecas.'], '/exercises/bodyweight-overhead-press-main.webp', '/exercises/bodyweight-overhead-press-main.webp'),
  ('Zancada Inversa con Peso Corporal', 'bodyweight-reverse-lunge', 'glutes', ARRAY['hamstrings'], NULL, 'beginner', 'compound', 'Una variante de zancada usando solo el peso corporal, dando un paso hacia atrás para mayor estabilidad de rodilla que una zancada hacia adelante.', ARRAY['Ponte de pie con los pies separados a la altura de las caderas.','Da un paso hacia atrás con una pierna y baja la rodilla hacia el suelo.','Baja hasta que tu muslo delantero quede paralelo al suelo.','Empuja a través del talón delantero para volver a la posición de pie.','Repite con ambas piernas.'], ARRAY['No necesitas peso -- concéntrate en el equilibrio y un descenso controlado.','Mantén el torso erguido en lugar de inclinarte hacia adelante.','Da un paso lo suficientemente atrás para que tu rodilla delantera quede detrás de los dedos del pie.'], '/exercises/bodyweight-reverse-lunge-main.webp', '/exercises/bodyweight-reverse-lunge-main.webp'),
  ('Sentadilla con Peso Corporal', 'bodyweight-squat', 'glutes', ARRAY['back','hamstrings'], NULL, 'beginner', 'compound', 'Una sentadilla con el propio peso corporal, apta para principiantes, que desarrolla los glúteos y los cuádriceps.', ARRAY['Colócate de pie con los pies separados al ancho de los hombros y los brazos extendidos al frente.','Siéntate hacia atrás y hacia abajo flexionando caderas y rodillas.','Baja hasta que los muslos queden paralelos al suelo.','Empuja con los talones para volver a la posición de pie.','Repite el número deseado de repeticiones.'], ARRAY['Empuja las rodillas hacia afuera en línea con los pies.','Mantén el pecho erguido y la mirada al frente.','Evita que los talones se despeguen del suelo al bajar.'], '/exercises/bodyweight-squat-main.webp', '/exercises/bodyweight-squat-main.webp'),
  ('Postura del Arco', 'bow-pose', 'back', ARRAY['hamstrings','chest'], NULL, 'intermediate', 'compound', 'Una extensión en decúbito prono: las manos sujetan los tobillos y las piernas empujan contra ellas, elevando pecho y muslos del suelo y activando toda la cadena posterior.', ARRAY['Túmbate boca abajo con los brazos junto al cuerpo y la frente apoyada en la esterilla.','Flexiona las rodillas y agarra la parte externa de ambos tobillos.','Empuja las espinillas contra las manos para que el pecho y los muslos se despeguen del suelo.','Mantén la posición elevada durante el tiempo indicado, con el cuello largo y la mirada al frente.','Suelta los tobillos y baja de forma controlada.'], ARRAY['La elevación viene de las piernas empujando contra las manos, no de tirar con los brazos.','Mantén las rodillas a la anchura de las caderas en lugar de dejarlas abrirse.','Si notas pinzamiento en los hombros, eleva menos y prioriza mantener el pecho abierto.'], '/exercises/bow-pose-main.webp', '/exercises/bow-pose-main.webp'),
  ('Salto al Cajón', 'box-jump', 'glutes', ARRAY['calves','hamstrings'], 'bodyweight', 'intermediate', 'compound', 'Un salto pliométrico desde media sentadilla a un cajón estable, que entrena la potencia del tren inferior.', ARRAY['Mantente a unos 30 cm frente a un cajón firme con los pies a la anchura de los hombros.','Baja a una media sentadilla y balancea los brazos atrás.','Lanza los brazos arriba y salta explosivamente al cajón.','Aterriza suave con los pies planos y rodillas flexionadas.','Baja caminando — no saltando — y reinicia.'], ARRAY['Baja siempre caminando — los saltos hacia abajo repetidos sobrecargan el Aquiles.','Aterriza suave con todo el pie, rodillas alineadas con los dedos.','Elige una altura que puedas superar sin doblar la cadera.'], '/exercises/box-jump-main.webp', '/exercises/box-jump-main.webp'),
  ('Sentadilla en Caja', 'box-squat', 'glutes', ARRAY['back','hamstrings'], NULL, 'intermediate', 'compound', 'Una sentadilla realizada hasta una caja o banco, que fija la profundidad y enseña a sentarse hacia atrás en las caderas.', ARRAY['Ponte de pie frente a una caja o banco, con los pies al ancho de los hombros y los brazos extendidos hacia adelante para el equilibrio.','Empuja las caderas hacia atrás y flexiona las rodillas, sentándote hacia la caja en lugar de bajar en línea recta.','Toca la caja ligeramente con los glúteos sin dejarte caer sobre ella.','Empuja con los pies para volver a ponerte de pie, apretando los glúteos arriba.','Repite las repeticiones deseadas.'], ARRAY['Usa una altura de caja que permita que los muslos queden aproximadamente paralelos al suelo, y bájala a medida que mejore tu movilidad.','Mantén el peso en el centro de los pies — no te inclines hacia los dedos.','No te sientes por completo en la caja: relajar todo el peso sobre ella te hace perder tensión en el core y sobrecarga la columna.'], '/exercises/box-squat-main.webp', '/exercises/box-squat-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Sentadilla Búlgara', 'bulgarian-split-squat', 'glutes', ARRAY['hamstrings'], 'dumbbell', 'intermediate', 'compound', 'Una variante de sentadilla unilateral con el pie trasero elevado.', ARRAY['Colócate de pie frente a un banco y apoya un pie detrás sobre el banco.','Sujeta mancuernas a los lados.','Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo.','Empuja con el talón delantero para volver a la posición de pie.','Repite en ambos lados.'], ARRAY['Mantén casi todo el peso sobre la pierna adelantada.','Ajusta la distancia al banco hasta que la zancada sea estable.','Completa todas las repeticiones con una pierna antes de cambiar.'], '/exercises/bulgarian-split-squat-main.webp', '/exercises/bulgarian-split-squat-main.webp'),
  ('Burpees', 'burpees', 'glutes', ARRAY['shoulders','core','triceps'], NULL, 'intermediate', 'cardio', 'Un ejercicio de acondicionamiento de cuerpo completo que combina sentadilla, plank, flexión y salto.', ARRAY['Mantente en pie con los pies a la anchura de los hombros.','Baja en sentadilla y apoya las manos en el suelo delante de ti.','Salta o lleva los pies atrás a la posición de plank y haz una flexión.','Salta o lleva los pies adelante hasta las manos.','Levántate y salta explosivamente con los brazos arriba.'], ARRAY['Mantén la espalda recta en el plank — no dejes caer las caderas.','Aterriza suavemente del salto.','Escálalo dando pasos atrás en lugar de saltar.'], '/exercises/burpees-main.webp', '/exercises/burpees-main.webp'),
  ('Estiramiento de Mariposa', 'butterfly-stretch', 'adductors', ARRAY['core'], NULL, 'beginner', 'mobility', 'Un estiramiento sentado para los aductores, juntando las plantas de los pies con las rodillas caídas hacia afuera.', ARRAY['Siéntate erguido y junta las plantas de los pies.','Deja caer las rodillas hacia el suelo.','Sujeta los pies y mantente erguido.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Presiona suavemente las rodillas con los codos para más estiramiento.','Acerca los talones al cuerpo para aumentar la intensidad.'], '/exercises/butterfly-stretch-main.webp', '/exercises/butterfly-stretch-main.webp'),
  ('Remo Inclinado con Cable', 'cable-bent-over-row', 'back', ARRAY['biceps','shoulders'], 'cable', 'intermediate', 'compound', 'Una variante de remo con cable que proporciona tensión constante durante todo el movimiento.', ARRAY['Engancha una barra recta o un agarre en V a la polea baja.','Inclínate hacia adelante desde las caderas con las rodillas ligeramente flexionadas.','Tira del agarre hacia la parte inferior del pecho.','Aprieta los omóplatos en la parte superior.','Baja de forma controlada y repite.'], ARRAY['Mantén la espalda recta y el torso estable durante toda la serie.','Piensa en llevar los codos hacia atrás, no en tirar con las manos.','No dejes que el peso te arrastre hacia delante al bajar.'], '/exercises/cable-bent-over-row-main.webp', '/exercises/cable-bent-over-row-main.webp'),
  ('Press de Pecho con Cable', 'cable-chest-press', 'chest', ARRAY['shoulders','core','triceps'], 'cable', 'intermediate', 'compound', 'Un press de pecho de pie en polea que ofrece tensión constante sobre el pectoral durante todo el recorrido.', ARRAY['Ajusta los cables a la altura del pecho y colócate de espaldas a la máquina.','Sujeta un agarre en cada mano y da un paso adelante adoptando una postura escalonada.','Empuja los agarres hacia adelante hasta extender los brazos completamente.','Aprieta el pecho en la parte superior.','Vuelve de forma controlada y repite.'], ARRAY['Evita que los hombros se adelanten al extender los brazos.','Mantén el core activo para no perder el equilibrio.','Mantén las muñecas rectas durante la fase de empuje.'], '/exercises/cable-chest-press-main.webp', '/exercises/cable-chest-press-main.webp'),
  ('Crunch con Cable', 'cable-crunch', 'core', NULL, 'cable', 'intermediate', 'isolation', 'Un encogimiento abdominal de rodillas en polea alta con cuerda, que permite añadir carga progresiva al trabajo del recto abdominal.', ARRAY['Arrodíllate frente a una máquina de cable con el accesorio de cuerda en la parte superior.','Sujeta la cuerda cerca de la frente con los codos flexionados.','Baja flexionando la columna y llevando los codos hacia los muslos.','Aprieta fuerte los abdominales en la parte inferior.','Vuelve a la posición inicial y repite.'], ARRAY['Flexiona la columna en lugar de tirar con los brazos.','Evita sentarte hacia atrás con la cadera en cada repetición.','Exhala con fuerza al bajar para contraer mejor el abdomen.'], '/exercises/cable-crunch-main.webp', '/exercises/cable-crunch-main.webp'),
  ('Curl con Cable', 'cable-curl', 'biceps', NULL, 'cable', 'beginner', 'isolation', 'Un curl de bíceps con resistencia de cable para tensión constante.', ARRAY['Colócate de pie frente a una polea baja con una barra recta o barra Z.','Agarra la barra con agarre supino y los codos pegados a los costados.','Sube la barra hacia los hombros.','Baja de forma controlada.','Repite.'], ARRAY['Evita que los codos se adelanten al subir la barra.','No balancees el torso para ayudarte con el peso.','Aleja un poco el cuerpo de la polea para mantener la tensión.'], '/exercises/cable-curl-main.webp', '/exercises/cable-curl-main.webp'),
  ('Rotación Externa con Cable', 'cable-external-rotation', 'shoulders', ARRAY['back','traps'], 'cable', 'intermediate', 'compound', 'Un ejercicio de rotación externa en polea, con el codo pegado al costado, que fortalece el deltoides posterior y la parte alta de la espalda.', ARRAY['Ajusta la polea a la altura del codo y agarra el handle.','Colócate de lado a la máquina con el codo de trabajo flexionado a 90 grados.','Mantén el codo pegado al costado y rota el antebrazo hacia afuera.','Pausa al final del movimiento.','Vuelve de forma controlada. Completa las repeticiones de un lado y luego cambia.'], ARRAY['Evita encoger los hombros mientras giras el brazo.','Trabaja con poco peso y de forma lenta y controlada.','Mantén la muñeca firme, alineada con el antebrazo.'], '/exercises/cable-external-rotation-main.webp', '/exercises/cable-external-rotation-main.webp'),
  ('Aperturas con Cable', 'cable-fly', 'chest', ARRAY['shoulders'], 'cable', 'intermediate', 'isolation', 'Un ejercicio de aislamiento para el pecho con resistencia de cable para tensión constante.', ARRAY['Colócate entre dos columnas de cable con los agarres enganchados a las poleas altas.','Con una ligera flexión en los codos, abre los brazos hacia los lados.','Junta las manos frente al pecho en un movimiento de abrazo.','Vuelve lentamente a la posición inicial.','Repite.'], ARRAY['Mantén el ángulo de los codos constante para no convertirlo en un press.','Aprieta el pecho un segundo cuando las manos se encuentren.','No adelantes los hombros cuando los brazos están abiertos.'], '/exercises/cable-fly-main.webp', '/exercises/cable-fly-main.webp'),
  ('Elevación Frontal con Cable', 'cable-front-raise', 'shoulders', ARRAY['chest'], 'cable', 'intermediate', 'isolation', 'Una elevación frontal en polea que aísla el deltoides anterior con tensión constante durante todo el recorrido.', ARRAY['Colócate de espaldas a una polea baja con un agarre.','Sujeta el agarre con el brazo extendido a la altura del muslo.','Levanta el brazo hacia adelante hasta la altura del hombro manteniéndolo recto.','Pausa en la parte superior.','Baja de forma controlada y repite.'], ARRAY['Evita balancear el torso para ayudarte a subir.','Mantén el codo casi recto, sin bloquearlo.','Baja más despacio de lo que subes para aprovechar la tensión del cable.'], '/exercises/cable-front-raise-main.webp', '/exercises/cable-front-raise-main.webp'),
  ('Curl de Martillo en Cable', 'cable-hammer-curl', 'biceps', ARRAY['forearms'], 'cable', 'intermediate', 'isolation', 'Un curl en cable con cuerda y agarre neutro que trabaja el braquial y braquiorradial con tensión constante.', ARRAY['Engancha una cuerda a la polea baja y párate frente a la máquina.','Agarra la cuerda con agarre neutro, palmas enfrentadas.','Sube la cuerda hacia los hombros manteniendo los codos fijos a los lados.','Aprieta arriba, luego baja lentamente hasta la extensión completa.','Repite el número de repeticiones deseado.'], ARRAY['Mantén los codos inmóviles durante todo el movimiento.','Separa ligeramente los extremos de la cuerda arriba para mayor contracción.','Evita balancear el torso.'], '/exercises/cable-hammer-curl-main.webp', '/exercises/cable-hammer-curl-main.webp'),
  ('Patada Trasera de Glúteos en Cable', 'cable-kickback', 'glutes', ARRAY['hamstrings'], 'cable', 'intermediate', 'isolation', 'Un ejercicio de aislamiento en cable para el glúteo mayor que extiende la cadera hacia atrás contra resistencia constante.', ARRAY['Coloca una correa de tobillo en la polea baja y sujétala alrededor de un tobillo.','De pie frente a la máquina, agárrate ligeramente al soporte e inclínate un poco desde las caderas.','Lleva la pierna con la correa hacia atrás extendiendo la cadera completamente y manteniendo la rodilla casi recta.','Aprieta el glúteo en la extensión máxima y regresa el pie lentamente a la posición inicial.','Completa todas las repeticiones de un lado antes de cambiar.'], ARRAY['Conduce el movimiento con el talón para maximizar la activación del glúteo.','Mantén las caderas paralelas; evita rotar la pelvis al patear hacia atrás.','El movimiento viene solo de la cadera: mantén la espalda y la pierna de apoyo estables.'], '/exercises/cable-kickback-main.webp', '/exercises/cable-kickback-main.webp'),
  ('Elevación Lateral en Polea', 'cable-lateral-raise', 'shoulders', ARRAY['traps'], 'cable', 'intermediate', 'isolation', 'Una elevación lateral unilateral en polea, que ofrece tensión constante sobre el deltoides lateral.', ARRAY['Colócate de lado a una polea baja y agarra el asa con la mano externa.','Mantén una ligera flexión en el codo y el cable por delante de la pierna que trabaja.','Sube el brazo hacia el lado hasta quedar paralelo al suelo.','Baja con control. Repeticiones por lado, luego cambia.','Mantén la tensión — no dejes que el peso descanse abajo.'], ARRAY['Lidera con el codo, no con la mano.','Pausa brevemente arriba, sin balanceo.','Usa menos carga que con mancuerna — la tensión del cable es constante.'], '/exercises/cable-lateral-raise-main.webp', '/exercises/cable-lateral-raise-main.webp'),
  ('Press Pallof en Polea', 'cable-pallof-press', 'core', ARRAY['shoulders','back','glutes'], 'cable', 'intermediate', 'compound', 'Un ejercicio de core antirrotación en el que la polea tira de ti hacia un lado mientras empujas el agarre recto desde el pecho y te niegas a dejar que el torso gire.', ARRAY['Coloca la polea a la altura del pecho y toma el agarre con ambas manos, situado de lado respecto a la máquina.','Sepárate hasta que haya tensión real en el cable, con los pies a la anchura de los hombros y las rodillas ligeramente flexionadas.','Lleva el agarre al centro del pecho y aprieta el tronco y los glúteos.','Empuja el agarre recto hacia delante hasta extender los brazos, resistiendo el tirón que quiere rotarte hacia la máquina.','Mantén un instante la posición extendida y devuelve después el agarre al pecho de forma controlada.','Completa las repeticiones deseadas, luego date la vuelta y repite hacia el otro lado.'], ARRAY['Nada debe rotar. Si los hombros giran hacia la polea al empujar, baja el peso — lo que entrena es la rotación que no llega a ocurrir.','Cuanto más te alejes de la máquina, más largo es el brazo de palanca y más cuesta, así que puedes cambiar la dificultad sin tocar el stack.','Mantén los brazos a la altura del pecho y los hombros abajo; dejar que el agarre suba lo convierte en una elevación frontal.'], '/exercises/cable-pallof-press-main.webp', '/exercises/cable-pallof-press-main.webp'),
  ('Patada de Tríceps con Cable', 'cable-tricep-kickback', 'triceps', ARRAY['shoulders'], 'cable', 'intermediate', 'isolation', 'Una extensión de tríceps en polea baja, realizada con el torso inclinado, que mantiene la tensión en el bloqueo final.', ARRAY['Engancha un handle a la polea baja e inclínate hacia adelante desde las caderas.','Pega la parte superior del brazo al costado con el codo flexionado a 90 grados.','Extiende el codo para empujar el handle hacia atrás.','Aprieta el tríceps al final del movimiento.','Vuelve de forma controlada. Completa las repeticiones de un lado y luego cambia.'], ARRAY['Evita que el codo caiga o se abra durante la extensión.','Mantén la espalda recta mientras el torso está inclinado.','Usa un peso ligero para no recurrir al impulso.'], '/exercises/cable-tricep-kickback-main.webp', '/exercises/cable-tricep-kickback-main.webp'),
  ('Remo al Mentón con Cable', 'cable-upright-row', 'shoulders', ARRAY['biceps'], 'cable', 'intermediate', 'compound', 'Un remo al mentón con cable para tensión constante en los deltoides laterales y el trapecio.', ARRAY['Colócate frente a la máquina de cable y agarra una barra recta o cuerda a la altura de los muslos.','Tira de la barra hacia el mentón llevando los codos por delante.','Baja de forma controlada.','Repite.'], ARRAY['Mantén los codos más altos que las muñecas.','Evita encoger los hombros en exceso.'], '/exercises/cable-upright-row-main.webp', '/exercises/cable-upright-row-main.webp'),
  ('Curl de Muñeca con Cable', 'cable-wrist-curl', 'forearms', NULL, 'cable', 'intermediate', 'isolation', 'Un curl de muñeca en polea baja, con los antebrazos apoyados en un banco, que fortalece los flexores del antebrazo.', ARRAY['Engancha una barra recta a la polea baja.','Arrodíllate o siéntate con los antebrazos sobre un banco, palmas hacia arriba.','Deja que las muñecas se flexionen sobre el borde del banco.','Sube la barra flexionando las muñecas.','Baja de forma controlada y repite.'], ARRAY['Mueve solo las muñecas, sin levantar los antebrazos del banco.','Usa cargas moderadas para no castigar las muñecas.','Sube y baja despacio, sin rebotes en el estiramiento.'], '/exercises/cable-wrist-curl-main.webp', '/exercises/cable-wrist-curl-main.webp'),
  ('Postura del Camello', 'camel-pose', 'back', ARRAY['chest','quads'], NULL, 'intermediate', 'mobility', 'Una extensión de rodillas que abre la parte frontal de las caderas, el abdomen y el pecho, con las manos apoyadas en los talones o en la zona lumbar.', ARRAY['Arrodíllate con las rodillas a la anchura de las caderas y las caderas alineadas sobre ellas.','Coloca las manos en la parte posterior de la pelvis con los dedos hacia abajo y eleva el pecho.','Empuja las caderas hacia delante y arquéate hacia atrás, buscando los talones si la posición sigue cómoda.','Mantén la postura durante el tiempo indicado, con el cuello en línea con la columna.','Devuelve las manos a la pelvis y sube liderando con el pecho.'], ARRAY['Mantén las caderas sobre las rodillas; si se van hacia atrás, la postura se derrumba.','Apoya los dedos de los pies y coloca las manos sobre los talones elevados si el alcance completo es demasiado.','Sal despacio: levantar primero la cabeza es lo que suele marear.'], '/exercises/camel-pose-main.webp', '/exercises/camel-pose-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Elevación de Rodillas en Silla Romana', 'captains-chair-knee-raise', 'core', NULL, NULL, 'beginner', 'compound', 'Un ejercicio de peso corporal en silla romana que trabaja el abdomen bajo y los flexores de cadera.', ARRAY['Colócate en la silla romana con la espalda plana contra el respaldo y los antebrazos en los apoyos.','Deja las piernas colgando rectas hacia abajo.','Activa el core y sube las rodillas hacia el pecho.','Mantén brevemente arriba, luego baja despacio a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Evita balancear las piernas para tomar impulso.','Exhala al subir las rodillas.','Mantén la espalda contra el respaldo durante todo el ejercicio.'], '/exercises/captains-chair-knee-raise-main.webp', '/exercises/captains-chair-knee-raise-main.webp'),
  ('Elevación de Piernas en Silla Romana', 'captains-chair-leg-raise', 'core', NULL, NULL, 'intermediate', 'compound', 'Un ejercicio de peso corporal en silla romana para el abdomen bajo con piernas rectas, de mayor dificultad.', ARRAY['Colócate en la silla romana con la espalda plana contra el respaldo y los antebrazos en los apoyos.','Deja las piernas colgando rectas hacia abajo.','Con las piernas rectas, súbelas hasta la horizontal o más arriba.','Mantén brevemente arriba, luego baja despacio.','Repite el número de repeticiones deseado.'], ARRAY['Mantén las piernas lo más rectas posible.','Evita el balanceo — controla el movimiento con el core.','Dobla ligeramente las rodillas para reducir la dificultad si es necesario.'], '/exercises/captains-chair-leg-raise-main.webp', '/exercises/captains-chair-leg-raise-main.webp'),
  ('Gato-Vaca', 'cat-cow', 'back', ARRAY['core','traps'], NULL, 'beginner', 'mobility', 'Un flujo a cuatro apoyos que alterna entre redondear la columna hacia el techo y dejarla descender mientras el pecho se abre, moviendo cada segmento de la espalda por su recorrido.', ARRAY['Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.','Exhala y redondea la columna hacia el techo, metiendo el coxis y dejando caer la cabeza.','Inhala e inviértelo: deja descender el abdomen, eleva el pecho y el coxis y mira ligeramente al frente.','Alterna entre ambas formas despacio, una respiración por posición.','Termina en columna neutra y siéntate sobre los talones.'], ARRAY['Deja que la respiración marque el ritmo en lugar de correr entre las dos posiciones.','Presiona las manos por igual para que los hombros no se hundan hacia el suelo.','Mueve toda la columna, incluido el cuello, en lugar de doblar solo la zona lumbar.'], '/exercises/cat-cow-main.webp', '/exercises/cat-cow-main.webp'),
  ('Estiramiento del Gato', 'cat-stretch', 'back', ARRAY['traps'], NULL, 'beginner', 'mobility', 'Un estiramiento de rodillas que redondea la columna hacia arriba para alargar los músculos de la espalda.', ARRAY['Empieza en cuadrupedia, manos bajo los hombros y rodillas bajo las caderas.','Redondea la columna hacia el techo.','Lleva el mentón hacia el pecho.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Empuja el suelo con las manos para separar los omóplatos.','Relájate y sigue respirando todo el tiempo.'], '/exercises/cat-stretch-main.webp', '/exercises/cat-stretch-main.webp'),
  ('Postura de la Silla', 'chair-pose', 'glutes', ARRAY['shoulders','back'], NULL, 'beginner', 'compound', 'Un sostén de pie con las caderas hacia atrás y los brazos arriba, donde el cuádriceps y la espalda alta trabajan de forma isométrica contra el peso corporal.', ARRAY['Ponte de pie con los pies juntos o a la anchura de las caderas y el peso en los talones.','Flexiona las rodillas y lleva las caderas atrás como si fueras a sentarte en una silla.','Eleva los brazos junto a las orejas sin dejar que las costillas se abran.','Mantén la posición durante el tiempo indicado, con el pecho alto y las rodillas siguiendo la línea de los pies.','Empuja con los talones para volver a ponerte de pie.'], ARRAY['Deja suficiente peso en los talones como para poder levantar los dedos de los pies.','Lleva los brazos algo más adelante si subirlos del todo te arquea la zona lumbar.','Baja más para exigir al cuádriceps, pero solo mientras los talones sigan apoyados.'], '/exercises/chair-pose-main.webp', '/exercises/chair-pose-main.webp'),
  ('Curl con Impulso', 'cheat-curl', 'biceps', ARRAY['back'], 'barbell', 'intermediate', 'isolation', 'Un curl de bíceps que emplea un ligero impulso de cadera para iniciar la subida y enfatiza una bajada lenta y controlada.', ARRAY['Colócate de pie sujetando el peso a la altura de los muslos con agarre supino.','Usa un ligero impulso de cadera para iniciar el curl.','Sube el peso hacia los hombros de forma explosiva.','Baja el peso lentamente de forma controlada por todo el rango de movimiento.','Repite el número deseado de repeticiones.'], ARRAY['Evita convertir el ejercicio en un balanceo de todo el cuerpo.','Si no puedes controlar la bajada, reduce la carga.','Mantén el abdomen firme para proteger la zona lumbar.'], '/exercises/cheat-curl-main.webp', '/exercises/cheat-curl-main.webp'),
  ('Press de Pecho en Máquina', 'chest-press-machine', 'chest', ARRAY['shoulders','triceps'], 'machine', 'beginner', 'compound', 'Un movimiento de empuje para el pecho en máquina, ideal para principiantes.', ARRAY['Siéntate en la máquina con la espalda plana contra el respaldo.','Agarra los mangos a la altura del pecho.','Empuja los mangos hacia adelante hasta extender los brazos completamente.','Vuelve lentamente a la posición inicial.','Repite.'], ARRAY['Ajusta el asiento para que las manijas queden a la altura del pecho.','Empuja sin bloquear los codos de golpe.','Vuelve atrás con control, sin soltar el peso de golpe.'], '/exercises/chest-press-machine-main.webp', '/exercises/chest-press-machine-main.webp'),
  ('Remo con Mancuernas con Apoyo en el Pecho', 'chest-supported-db-row', 'back', ARRAY['biceps','shoulders'], 'dumbbell', 'intermediate', 'compound', 'Un remo con mancuernas con apoyo en el pecho para eliminar la tensión en la zona lumbar y aislar los músculos de la espalda.', ARRAY['Túmbate boca abajo en un banco inclinado con las mancuernas colgando por debajo.','Rema las mancuernas hacia los lados.','Aprieta en la parte superior y baja.','Repite.'], ARRAY['El apoyo en el pecho elimina la fatiga de la espalda.','Concéntrate en juntar los omóplatos.'], '/exercises/chest-supported-db-row-main.webp', '/exercises/chest-supported-db-row-main.webp'),
  ('Encogimiento de Hombros con Mancuernas y Apoyo en el Pecho', 'chest-supported-dumbbell-shrug', 'traps', ARRAY['shoulders','back'], 'dumbbell', 'intermediate', 'isolation', 'Un encogimiento de hombros boca abajo en un banco inclinado, donde el apoyo del pecho aísla el trapecio y elimina el impulso.', ARRAY['Ajusta un banco inclinado a unos 30 grados.','Túmbate boca abajo en el banco sujetando mancuernas con los brazos extendidos.','Encoge los hombros hacia arriba y hacia atrás en dirección a las orejas.','Aprieta el trapecio superior en la parte superior.','Baja de forma controlada y repite.'], ARRAY['Encoge hacia arriba y atrás hacia las orejas, no solo recto hacia arriba.','Mantén el pecho pegado a la almohadilla para no usar impulso.','Haz una pausa y aprieta arriba antes de bajar con control.'], '/exercises/chest-supported-dumbbell-shrug-main.webp', '/exercises/chest-supported-dumbbell-shrug-main.webp'),
  ('Remo con Kettlebell Apoyado en el Pecho', 'chest-supported-kettlebell-row', 'back', ARRAY['biceps','shoulders','traps'], 'kettlebell', 'beginner', 'compound', 'Este ejercicio trabaja los músculos de tu espalda, principalmente el dorsal ancho y los romboides, al tirar de una kettlebell hacia tu pecho mientras tu torso está apoyado.', ARRAY['Acuéstate boca abajo en un banco inclinado, dejando que tus brazos cuelguen libremente con una kettlebell en cada mano.','Contrae tu abdomen y retrae tus escápulas.','Tira de las kettlebells hacia tus caderas, apretando tus escápulas.','Haz una breve pausa en la parte superior, sintiendo la contracción en tu espalda.','Baja lentamente las kettlebells a la posición inicial con control.'], ARRAY['Mantén el torso estable durante todo el movimiento; evita balancearte.','Concéntrate en iniciar el tirón con los músculos de la espalda, no solo con los brazos.','Mantén los codos cerca de tu cuerpo para enfatizar el dorsal ancho.'], '/exercises/chest-supported-kettlebell-row-main.webp', '/exercises/chest-supported-kettlebell-row-main.webp'),
  ('Remo con Apoyo en el Pecho en Máquina Smith', 'chest-supported-smith-machine-row', 'back', ARRAY['biceps','shoulders'], 'smith_machine', 'beginner', 'compound', 'Un remo contra un respaldo inclinado dentro de la máquina Smith, donde el apoyo del pecho saca la zona lumbar del movimiento y la barra guiada mantiene el tirón en una sola línea.', ARRAY['Coloca un banco inclinado dentro de la máquina Smith mirando hacia la barra, y baja la barra lo suficiente para que tus brazos cuelguen rectos al apoyarte en el respaldo.','Ponte de pie a horcajadas del banco con los pies firmes y el pecho apoyado en la parte alta del respaldo.','Toma un agarre prono algo más ancho que los hombros y desengancha la barra con los brazos extendidos.','Tira de la barra hacia la parte baja del pecho, guiando con los codos y juntando las escápulas arriba.','Baja la barra de forma controlada hasta estirar los brazos de nuevo y repite el número de repeticiones deseado.'], ARRAY['Mantén el pecho en el respaldo en cada repetición. En cuanto te separas de él para mover el peso lo has convertido otra vez en un remo inclinado y has perdido la razón del montaje.','Guía con los codos y detente cuando pasen del torso. Tirar más solo adelanta los hombros, y la trayectoria fija de la barra no les deja escapatoria.','Como aquí la zona lumbar no hace nada, este es el remo para los días en que un remo inclinado no es opción: ajusta el peso a lo que tu espalda puede tirar, no a lo que tus piernas podrían aguantar.'], '/exercises/chest-supported-smith-machine-row-main.webp', '/exercises/chest-supported-smith-machine-row-main.webp'),
  ('Postura del Niño', 'childs-pose', 'back', ARRAY['traps'], NULL, 'beginner', 'mobility', 'Un estiramiento de descanso de rodillas que alarga los dorsales, la zona lumbar y los hombros con los brazos al frente.', ARRAY['Arrodíllate y lleva la cadera hacia los talones.','Inclina el torso hacia adelante sobre los muslos.','Extiende ambos brazos largos sobre el suelo al frente.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Abre más las rodillas para apoyar el pecho más abajo.','Relájate y sigue respirando todo el tiempo.'], '/exercises/childs-pose-main.webp', '/exercises/childs-pose-main.webp'),
  ('Retracción de Mentón Sostenida', 'chin-tuck-hold', 'traps', ARRAY['back'], NULL, 'intermediate', 'compound', 'Un ejercicio estático de cuello que retrae la cabeza hacia atrás para fortalecer los flexores profundos del cuello y contrarrestar la postura de cabeza adelantada.', ARRAY['Ponte de pie o siéntate erguido con los hombros relajados.','Lleva el mentón recto hacia atrás, creando una papada.','Mantén la cabeza nivelada sin inclinarla.','Mantén la posición durante el tiempo deseado.','Suelta y repite durante varias series.'], ARRAY['Imagina deslizar la cabeza hacia atrás sobre la columna, no asentir hacia abajo.','Mantén la mirada nivelada y la respiración relajada.'], '/exercises/chin-tuck-hold-main.webp', '/exercises/chin-tuck-hold-main.webp'),
  ('Dominadas en Supinación', 'chin-ups', 'biceps', ARRAY['back'], 'bodyweight', 'intermediate', 'compound', 'Una variante de dominadas con agarre supino que activa fuertemente los bíceps junto con el dorsal ancho.', ARRAY['Cuélgate de una barra con agarre supino a la anchura de los hombros.','Sube hasta que el mentón supere la barra.','Baja de forma controlada.','Repite.'], ARRAY['Mantén el core contraído durante todo el ejercicio.','Evita el balanceo excesivo.'], '/exercises/chin-ups-main.webp', '/exercises/chin-ups-main.webp'),
  ('Almejas', 'clamshells', 'abductors', ARRAY['glutes'], NULL, 'intermediate', 'compound', 'Un ejercicio de abducción de cadera, realizado tumbado de lado, que activa el glúteo medio sin material adicional.', ARRAY['Túmbate de lado con las rodillas dobladas y apiladas una sobre la otra.','Mantén los pies juntos y las caderas alineadas.','Abre la rodilla superior hacia el techo sin rotar las caderas.','Aprieta el glúteo externo en la posición superior.','Baja de forma controlada. Completa las repeticiones de un lado y luego cambia.'], ARRAY['Sube la rodilla solo hasta donde la pelvis no se mueva.','Hazlo lento y controlado para notar bien el glúteo medio.','Exhala al abrir la rodilla y mantén el abdomen activo.'], '/exercises/clamshells-main.webp', '/exercises/clamshells-main.webp'),
  ('Almejas Isométricas', 'clamshells-hold', 'abductors', ARRAY['glutes'], NULL, 'intermediate', 'compound', 'La posición final de la almeja mantenida en el tiempo: tumbado de lado con las rodillas flexionadas y apiladas, la rodilla superior se abre y la pelvis se mantiene firme, de modo que el glúteo medio trabaja de forma isométrica en lugar de por repeticiones.', ARRAY['Túmbate de lado con las caderas y las rodillas flexionadas unos 45 y 90 grados, los talones juntos y las rodillas apiladas.','Alinea los hombros y las caderas en vertical y aprieta el tronco para que la pelvis no ruede hacia atrás.','Abre la rodilla superior todo lo que puedas sin que la pelvis rote, manteniendo los talones en contacto.','Mantén esa posición abierta durante el tiempo indicado, respirando con normalidad.','Baja la rodilla de forma controlada y repite del otro lado.'], ARRAY['Detén la apertura donde la pelvis empieza a rodar hacia atrás; el recorrido es menor de lo que la mayoría espera.','Mantén los talones presionados entre sí para que el movimiento se quede en la cadera y no en el tobillo.','Añade una banda circular por encima de las rodillas solo cuando la pelvis se mantenga completamente quieta.'], '/exercises/clamshells-hold-main.webp', '/exercises/clamshells-hold-main.webp'),
  ('Flexiones con Palmada', 'clap-push-ups', 'chest', ARRAY['triceps'], NULL, 'advanced', 'compound', 'Una flexión pliométrica explosiva que desarrolla la potencia del pecho y las fibras musculares de contracción rápida.', ARRAY['Comienza en la posición estándar de flexión.','Baja el pecho hacia el suelo.','Empuja hacia arriba de forma explosiva para que las manos despeguen del suelo.','Da una palmada y aterriza suavemente, volviendo a la posición inicial.','Repite.'], ARRAY['Aterriza con los codos ligeramente flexionados para absorber el impacto.','Asegúrate de tener suficiente fuerza en la parte superior del cuerpo antes de intentarlo.'], '/exercises/clap-push-ups-main.webp', '/exercises/clap-push-ups-main.webp'),
  ('Clean', 'clean', 'glutes', ARRAY['shoulders','back','hamstrings','traps'], 'barbell', 'intermediate', 'compound', 'Un levantamiento olímpico en el que tiras de la barra de forma explosiva desde el suelo hasta la posición de rack frontal sobre los hombros.', ARRAY['Colócate sobre una barra cargada con los pies a la anchura de las caderas.','Agarra la barra justo por fuera de las rodillas con un agarre prono.','Empuja de forma explosiva con las piernas y extiende las caderas.','Métete bajo la barra y recíbela sobre los deltoides anteriores.','Ponte completamente erguido para completar el levantamiento.'], ARRAY['Mantén la barra cerca del cuerpo mientras sube.','Completa el empuje de piernas antes de tirar por debajo de la barra.','Recibe con los codos altos para que la barra descanse en los hombros.'], '/exercises/clean-main.webp', '/exercises/clean-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Clean and Jerk', 'clean-and-jerk', 'shoulders', ARRAY['back','traps','triceps'], 'barbell', 'intermediate', 'compound', 'Un levantamiento olímpico en dos partes: cargas la barra hasta los hombros y luego la impulsas por encima de la cabeza en posición de tijera.', ARRAY['Lleva la barra cargada desde el suelo hasta los hombros como en un clean.','Ponte completamente erguido con la barra apoyada en los deltoides anteriores.','Flexiona ligeramente las rodillas y lanza la barra sobre la cabeza de forma explosiva.','Separa las piernas para recibir la barra con los brazos extendidos.','Recupera la posición juntando los pies.'], ARRAY['Ponte de pie por completo y recoloca tu posición antes de iniciar el envión.','Impulsa la barra con las piernas, no solo con los brazos.','Bloquea los brazos mientras los pies aterrizan en la tijera.'], '/exercises/clean-and-jerk-main.webp', '/exercises/clean-and-jerk-main.webp'),
  ('Curl de Barra con Agarre Cerrado', 'close-grip-barbell-curl', 'biceps', NULL, 'barbell', 'beginner', 'isolation', 'Un curl de barra de pie con agarre estrecho que enfatiza la cabeza larga del bíceps y el braquial.', ARRAY['De pie, sujeta la barra con un agarre supino con las manos más juntas que la anchura de los hombros.','Comienza con la barra a la altura de los muslos, brazos extendidos y codos pegados a los costados.','Sube la barra hasta los hombros flexionando los codos.','Aprieta los bíceps en la parte superior y luego baja de forma controlada.','Repite el número de repeticiones recomendado.'], ARRAY['Mantén los codos pegados a los costados; no dejes que se desplacen hacia adelante.','Si el agarre estrecho molesta las muñecas, usa una barra Z.'], '/exercises/close-grip-barbell-curl-main.webp', '/exercises/close-grip-barbell-curl-main.webp'),
  ('Press de Banca con Agarre Cerrado', 'close-grip-bench-press', 'triceps', ARRAY['shoulders','chest'], 'barbell', 'intermediate', 'compound', 'Una variación del press de banca con agarre estrecho que desplaza el énfasis hacia los tríceps.', ARRAY['Túmbate en un banco plano y agarra la barra con las manos a la anchura de los hombros.','Baja la barra hasta el pecho inferior manteniendo los codos cerca de los costados.','Vuelve a empujar hasta la extensión completa.','Repite.'], ARRAY['Mantén los codos pegados para maximizar la activación de los tríceps.','Evita un agarre demasiado estrecho para prevenir tensión en las muñecas.'], '/exercises/close-grip-bench-press-main.webp', '/exercises/close-grip-bench-press-main.webp'),
  ('Press de Banca con Mancuernas y Agarre Cerrado', 'close-grip-db-bench-press', 'triceps', ARRAY['shoulders','chest'], 'dumbbell', 'intermediate', 'compound', 'Un press de banca con mancuernas sostenidas juntas para aumentar la participación de los tríceps.', ARRAY['Túmbate en un banco plano y sostén dos mancuernas juntas sobre el pecho.','Bájalas hasta el pecho manteniendo los codos cerca.','Empuja hacia arriba.','Repite.'], ARRAY['Mantén las mancuernas presionadas entre sí durante todo el movimiento.','Mantén los codos pegados.'], '/exercises/close-grip-db-bench-press-main.webp', '/exercises/close-grip-db-bench-press-main.webp'),
  ('Press de Banca con Barra Z y Agarre Cerrado', 'close-grip-ez-bar-bench-press', 'triceps', ARRAY['shoulders','chest'], 'barbell', 'intermediate', 'compound', 'Un press enfocado en los tríceps con barra Z y agarre estrecho para mayor comodidad en las muñecas.', ARRAY['Túmbate en un banco plano y agarra las curvas internas de la barra Z.','Baja la barra hasta el pecho con los codos pegados.','Empuja hacia arriba hasta la extensión completa.','Repite.'], ARRAY['La barra Z reduce la incomodidad en las muñecas.','Mantén el movimiento controlado.'], '/exercises/close-grip-ez-bar-bench-press-main.webp', '/exercises/close-grip-ez-bar-bench-press-main.webp'),
  ('Curl con Barra Z y Agarre Cerrado', 'close-grip-ez-bar-curl', 'biceps', NULL, 'barbell', 'beginner', 'isolation', 'Un curl de bíceps con barra Z y manos juntas, que carga más la cabeza larga del bíceps.', ARRAY['Sujeta una barra Z con las manos en las curvas internas, palmas arriba.','Mantén los codos pegados al cuerpo.','Sube la barra hasta los hombros contrayendo el bíceps.','Baja con control hasta el estiramiento completo.','Repite el número de repeticiones indicado.'], ARRAY['Mantén los codos pegados — no dejes que se vayan adelante.','Contrae fuerte arriba.','Evita balancear el torso para tomar impulso.'], '/exercises/close-grip-ez-bar-curl-main.webp', '/exercises/close-grip-ez-bar-curl-main.webp'),
  ('Press de Banca Inclinado con Agarre Cerrado', 'close-grip-incline-bench', 'triceps', ARRAY['shoulders','chest'], 'barbell', 'intermediate', 'compound', 'Un press de banca inclinado con agarre cerrado que trabaja los tríceps y el pecho superior.', ARRAY['Ajusta el banco en inclinación. Agarra la barra con las manos a la anchura de los hombros o más juntas.','Baja la barra hasta el pecho superior.','Empuja hacia arriba.','Repite.'], ARRAY['La inclinación aumenta el estiramiento de la cabeza larga de los tríceps.','Mantén los codos pegados para mantener el foco en los tríceps.'], '/exercises/close-grip-incline-bench-main.webp', '/exercises/close-grip-incline-bench-main.webp'),
  ('Jalón al Pecho con Agarre Cerrado', 'close-grip-lat-pulldown', 'back', ARRAY['biceps','shoulders'], 'cable', 'intermediate', 'compound', 'Una variante del jalón al pecho con agarre cerrado y paralelo que enfatiza la parte baja del dorsal y el bíceps.', ARRAY['Siéntate en una máquina de jalón al pecho y asegura tus muslos bajo la almohadilla.','Sujeta el agarre cerrado con las palmas enfrentadas.','Tira de la barra hacia la parte superior del pecho.','Contrae el dorsal en la parte baja.','Vuelve con control y repite.'], ARRAY['Inclínate hacia atrás solo ligeramente, no en exceso.','Evita usar impulso para bajar la barra.','Lleva los codos hacia abajo y atrás, no solo las manos.'], '/exercises/close-grip-lat-pulldown-main.webp', '/exercises/close-grip-lat-pulldown-main.webp'),
  ('Dominadas con Agarre Cerrado', 'close-grip-pull-ups', 'biceps', ARRAY['back'], 'bodyweight', 'intermediate', 'compound', 'Una dominada con agarre prono estrecho que aumenta la activación de los bíceps y la parte interna de la espalda.', ARRAY['Cuélgate de la barra de dominadas con las manos a la anchura de los hombros o más juntas, palmas mirando hacia afuera.','Súbete hasta que la barbilla supere la barra.','Baja de forma controlada.','Repite.'], ARRAY['El agarre estrecho aumenta la participación de los bíceps.','Evita los impulsos para el desarrollo de fuerza.'], '/exercises/close-grip-pull-ups-main.webp', '/exercises/close-grip-pull-ups-main.webp'),
  ('Flexiones con Agarre Cerrado', 'close-grip-push-ups', 'chest', ARRAY['shoulders','core'], NULL, 'intermediate', 'compound', 'Una variante de flexión con las manos juntas que enfatiza el tríceps.', ARRAY['Adopta una posición de flexión con las manos directamente bajo los hombros.','Mantén los codos pegados a las costillas.','Baja el pecho hacia el suelo.','Empuja de vuelta a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Lleva los codos hacia atrás, no hacia los lados.','Mantén el cuerpo rígido como una tabla durante todo el movimiento.','Baja despacio para mayor activación del tríceps.'], '/exercises/close-grip-push-ups-main.webp', '/exercises/close-grip-push-ups-main.webp'),
  ('Prensa de piernas con postura cerrada', 'close-stance-leg-press', 'quads', ARRAY['glutes','hamstrings'], 'machine', 'beginner', 'compound', 'Una prensa de piernas con los pies juntos, que aumenta la flexión de rodilla y mantiene el énfasis en los cuádriceps con la espalda apoyada.', ARRAY['Ajusta el asiento y el respaldo para que la zona lumbar permanezca apoyada durante toda la repetición.','Coloca los pies juntos cerca del centro de la plataforma y alinea rodillas y puntas de los pies.','Baja el carro flexionando rodillas y caderas mientras mantienes ambos pies planos.','Empuja la plataforma con todo el pie y extiende las piernas sin golpear el bloqueo de las rodillas.','Regresa bajo control y repite el número deseado de repeticiones.'], ARRAY['Usa solo la postura más cerrada que permita que las rodillas sigan cómodamente a los pies.','Mantén los talones abajo y evita que las rodillas se junten al descender.','No sacrifiques la posición de la pelvis para conseguir más profundidad.'], '/exercises/close-stance-leg-press-main.webp', '/exercises/close-stance-leg-press-main.webp'),
  ('Estiramiento de la Cobra', 'cobra-stretch', 'core', NULL, NULL, 'beginner', 'mobility', 'Una extensión boca abajo que estira los abdominales y la parte frontal del torso al elevar el pecho.', ARRAY['Acuéstate boca abajo con las manos bajo los hombros.','Empuja con las manos para levantar el pecho del suelo.','Mantén caderas y piernas en el suelo, con los hombros relajados.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén los codos algo flexionados, no fuerces la extensión completa.','Baja los hombros alejándolos de las orejas.'], '/exercises/cobra-stretch-main.webp', '/exercises/cobra-stretch-main.webp'),
  ('Cocoons', 'cocoons', 'core', NULL, NULL, 'intermediate', 'compound', 'Un ejercicio abdominal dinámico que combina un encogimiento de rodillas con un crunch desde una posición extendida boca arriba.', ARRAY['Túmbate boca arriba con los brazos extendidos sobre la cabeza; manos y pies ligeramente elevados.','Lleva las rodillas al pecho y balancea los brazos hacia adelante en un crunch simultáneamente.','Intenta tocar las espinillas con las manos en el punto máximo.','Extiende brazos y piernas de forma controlada sin tocar el suelo.','Repite el movimiento durante las repeticiones indicadas.'], ARRAY['Las manos y los pies no tocan el suelo entre repeticiones.','Exhala con fuerza al llegar al punto máximo.'], '/exercises/cocoons-main.webp', '/exercises/cocoons-main.webp'),
  ('Curl de Concentración', 'concentration-curl', 'biceps', NULL, 'dumbbell', 'beginner', 'isolation', 'Un curl de aislamiento realizado sentado para la máxima contracción del bíceps.', ARRAY['Siéntate en un banco con las piernas separadas y sujeta una mancuerna en una mano.','Apoya el codo en la cara interna del muslo.','Sube la mancuerna hacia el hombro.','Baja con control.','Repite en ambos lados.'], ARRAY['No balancees el torso para ayudarte a subir.','Gira ligeramente la muñeca hacia fuera para contraer más el bíceps.','Trabaja ambos brazos por igual, empezando por el más débil.'], '/exercises/concentration-curl-main.webp', '/exercises/concentration-curl-main.webp'),
  ('Sentadilla cosaca', 'cossack-squat', 'glutes', ARRAY['adductors','hamstrings'], NULL, 'intermediate', 'compound', 'Una sentadilla lateral de base amplia que hunde el cuerpo profundamente sobre una pierna flexionada mientras la otra permanece recta, entrenando fuerza unilateral, movilidad de cadera y flexibilidad de aductores.', ARRAY['Ponte en una postura amplia con las puntas de los pies ligeramente hacia afuera.','Desplaza el peso hacia un lado, flexiona esa rodilla y húndete en una sentadilla profunda.','Mantén la pierna contraria recta, con el talón en el suelo y los dedos hacia arriba.','Baja tanto como te permita tu movilidad, manteniendo el pecho erguido.','Empuja con la pierna flexionada para volver al centro y repite hacia el otro lado.'], ARRAY['Mantén el talón de la pierna que trabaja apoyado: no ruedes hacia las puntas.','Apunta con los dedos de la pierna recta hacia arriba para mantener tensión en los aductores.','Sujeta un peso ligero frente al pecho como contrapeso si lo necesitas.'], '/exercises/cossack-squat-main.webp', '/exercises/cossack-squat-main.webp'),
  ('Postura de la Cara de Vaca', 'cow-face-pose', 'glutes', ARRAY['shoulders','triceps'], NULL, 'beginner', 'mobility', 'Una postura sentada con las rodillas apiladas y los brazos enlazados a la espalda, que estira la cadera externa de un lado y los hombros en direcciones opuestas.', ARRAY['Siéntate en el suelo y cruza una rodilla justo encima de la otra para que queden apiladas en la línea media.','Camina los pies hacia las caderas y apoya ambos isquiones por igual.','Sube el brazo del lado de la rodilla superior y flexiónalo por detrás de la cabeza; sube el otro brazo por la espalda hasta engancharlos.','Mantén la posición durante el tiempo indicado, con el pecho abierto y la columna larga.','Suelta y repite con la otra pierna y el otro brazo arriba.'], ARRAY['Siéntate sobre una manta doblada si un isquion se despega del suelo.','Usa una cinta entre las manos cuando los dedos no se toquen; forzar el enganche redondea la espalda.','Mantén el codo de arriba apuntando al techo en lugar de dejarlo abrirse hacia el lado.'], '/exercises/cow-face-pose-main.webp', '/exercises/cow-face-pose-main.webp'),
  ('Fondos de Cangrejo', 'crab-dips', 'triceps', ARRAY['shoulders','glutes','chest'], NULL, 'intermediate', 'compound', 'Un ejercicio de tríceps en el suelo desde la mesa invertida: con las manos detrás de las caderas y el tronco elevado, los codos se flexionan y estiran para subir y bajar el cuerpo.', ARRAY['Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti, con los dedos hacia los talones.','Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas.','Flexiona los codos hacia atrás para bajar las caderas hacia el suelo sin sentarte.','Empuja de nuevo hasta estirar los brazos, manteniendo las caderas elevadas.','Repite las veces indicadas y baja las caderas para terminar.'], ARRAY['Mantén los codos apuntando hacia atrás, sin abrirlos hacia los lados.','Sostén las caderas altas toda la serie; dejarlas caer convierte el ejercicio en un descanso.','Aleja más los pies para alargar la palanca y exigir más al tríceps.'], '/exercises/crab-dips-main.webp', '/exercises/crab-dips-main.webp'),
  ('Zancada Alta', 'crescent-lunge', 'glutes', ARRAY['back','core'], NULL, 'intermediate', 'compound', 'Un sostén en paso largo con el talón trasero elevado y los brazos arriba, que carga la pierna delantera mientras la cadera trasera se mantiene larga.', ARRAY['Adelanta un pie a un paso largo con el talón trasero elevado y los dedos apuntando al frente.','Flexiona la rodilla delantera unos noventa grados para que quede sobre el tobillo.','Lleva la cadera trasera hacia delante hasta que ambas apunten al frente de la esterilla y eleva los brazos.','Mantén la posición durante el tiempo indicado, con las costillas cerradas y la pierna trasera estirada.','Junta los pies y repite del otro lado.'], ARRAY['Separa un poco los pies lateralmente si el equilibrio es lo que te limita.','Empuja el talón trasero hacia la pared de detrás para mantener activa la pierna de atrás.','Baja los brazos a las caderas si estirarlos arriba te arquea la zona lumbar.'], '/exercises/crescent-lunge-main.webp', '/exercises/crescent-lunge-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Crunch Cruzado', 'cross-body-crunch', 'core', NULL, NULL, 'beginner', 'isolation', 'Un crunch de oblicuos en el suelo que acerca el codo y la rodilla opuestos entre sí, trabajando los oblicuos y el recto abdominal juntos.', ARRAY['Túmbate boca arriba en el suelo con las rodillas dobladas y las manos ligeramente detrás de las orejas.','Contrae y rota llevando el codo derecho hacia la rodilla izquierda mientras la rodilla sube.','Regresa a la posición inicial de forma controlada.','Repite del otro lado, alternando en cada repetición.'], ARRAY['Gira desde la caja torácica, no desde los brazos; los codos siguen a los hombros.','La zona lumbar permanece en el suelo durante todo el ejercicio.'], '/exercises/cross-body-crunch-main.webp', '/exercises/cross-body-crunch-main.webp'),
  ('Curl Martillo Cruzado', 'cross-body-hammer-curl', 'biceps', ARRAY['forearms'], 'dumbbell', 'intermediate', 'isolation', 'Un curl con agarre neutro que lleva la mancuerna cruzando el cuerpo hacia el hombro opuesto, enfatizando el braquial y los antebrazos.', ARRAY['De pie, sujeta una mancuerna en cada mano con agarre neutro.','Sube una mancuerna cruzando el cuerpo hacia el hombro opuesto.','Mantén el codo fijo a tu costado.','Baja de forma controlada y repite del otro lado.','Continúa alternando el número de repeticiones deseado.'], ARRAY['Mantén el codo pegado al costado durante todo el curl.','Evita balancear el torso para levantar el peso.','Baja con control en lugar de dejar caer la mancuerna.'], '/exercises/cross-body-hammer-curl-main.webp', '/exercises/cross-body-hammer-curl-main.webp'),
  ('Estiramiento de Hombro Cruzado', 'cross-body-shoulder-stretch', 'shoulders', ARRAY['back'], NULL, 'beginner', 'mobility', 'Un estiramiento de pie para el hombro posterior llevando un brazo en horizontal sobre el pecho.', ARRAY['Párate erguido y cruza un brazo estirado sobre el pecho.','Engancha el otro antebrazo por debajo.','Tira suavemente del brazo hacia el pecho.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén el hombro estirado abajo, sin encogerlo.','No tires de la articulación del codo en sí.'], '/exercises/cross-body-shoulder-stretch-main.webp', '/exercises/cross-body-shoulder-stretch-main.webp'),
  ('Postura del Cuervo', 'crow-pose', 'shoulders', ARRAY['core'], NULL, 'advanced', 'compound', 'Un equilibrio sobre brazos: las rodillas descansan en la parte posterior de los brazos y los pies se elevan, sostenidos por hombros, brazos y tronco.', ARRAY['Ponte en cuclillas con los pies juntos y apoya las palmas en el suelo a la anchura de los hombros.','Flexiona los codos hacia atrás y coloca las rodillas altas sobre la parte posterior de los brazos.','Desplaza el peso hacia delante sobre las manos hasta que los pies se despeguen del suelo.','Mantén el equilibrio durante el tiempo indicado, con la espalda alta redondeada y la mirada algo adelante.','Baja los pies de forma controlada.'], ARRAY['Mira al suelo por delante de las manos, no hacia los pies; la mirada dirige el equilibrio.','Coloca un cojín delante mientras aprendes, para caer hacia delante sin riesgo.','Agarra el suelo con las yemas de los dedos para que el peso no se vaya a las muñecas.'], '/exercises/crow-pose-main.webp', '/exercises/crow-pose-main.webp'),
  ('Crunches', 'crunches', 'core', NULL, NULL, 'beginner', 'isolation', 'Un ejercicio abdominal básico enfocado en el recto abdominal.', ARRAY['Túmbate boca arriba con las rodillas dobladas y las manos detrás de la cabeza.','Enrolla el tronco superior hacia las rodillas levantando los omóplatos del suelo.','Aprieta el abdomen en la posición superior.','Baja con control.','Repite.'], ARRAY['No tires del cuello con las manos al subir.','Exhala al subir y mantén la zona lumbar pegada al suelo.','Piensa en acercar las costillas a la pelvis, no en sentarte.'], '/exercises/crunches-main.webp', '/exercises/crunches-main.webp'),
  ('Postura del Bailarín', 'dancer-pose', 'glutes', ARRAY['back','core'], NULL, 'advanced', 'compound', 'Un equilibrio de pie sobre una pierna en el que el pie libre se sujeta por detrás y empuja hacia atrás, combinando extensión de columna y sostén unipodal.', ARRAY['Ponte de pie y pasa el peso a un pie, con esa rodilla ligeramente flexionada.','Flexiona la otra rodilla y agarra la cara interna de ese tobillo por detrás.','Empuja el pie elevado contra la mano y estira el brazo contrario hacia delante mientras el pecho sube.','Mantén la forma durante el tiempo indicado, con la cadera de apoyo nivelada y la mirada fija.','Suelta el pie y repite del otro lado.'], ARRAY['Fija los ojos en un punto; una mirada que se mueve es lo primero que rompe el equilibrio.','Mantén la rodilla elevada en línea con la cadera en lugar de dejarla abrirse hacia fuera.','Usa una cinta alrededor del pie si el hombro no permite el agarre directo.'], '/exercises/dancer-pose-main.webp', '/exercises/dancer-pose-main.webp'),
  ('Press de Banca con Mancuernas', 'db-bench-press', 'chest', ARRAY['shoulders','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un ejercicio compuesto de pecho con mancuernas que permite mayor rango de movimiento que el press de banca con barra.', ARRAY['Túmbate en un banco plano sosteniendo una mancuerna en cada mano a la altura del pecho.','Empuja las mancuernas hacia arriba hasta extender completamente los brazos.','Bájalas lentamente hasta la posición inicial.','Repite.'], ARRAY['Mantén las muñecas neutras durante todo el ejercicio.','Aprieta el pecho en la parte superior del movimiento.'], '/exercises/db-bench-press-main.webp', '/exercises/db-bench-press-main.webp'),
  ('Aperturas con Mancuernas', 'db-fly', 'chest', ARRAY['shoulders'], 'dumbbell', 'beginner', 'isolation', 'Un ejercicio de aislamiento que estira y contrae el pectoral a través de un amplio arco de movimiento.', ARRAY['Túmbate en un banco con las mancuernas sobre el pecho y las palmas mirándose entre sí.','Con una ligera flexión de codos, baja las mancuernas hacia los lados.','Regresa a la posición inicial apretando el pecho.','Repite.'], ARRAY['Mantén una flexión constante en los codos durante todo el ejercicio.','No bajes demasiado las mancuernas.'], '/exercises/db-fly-main.webp', '/exercises/db-fly-main.webp'),
  ('Peso Muerto Kickstand con Mancuerna', 'db-kickstand-deadlift', 'glutes', ARRAY['adductors','back'], 'dumbbell', 'intermediate', 'compound', 'Un movimiento de bisagra de cadera en postura escalonada con una mancuerna que carga la pierna delantera mientras el pie trasero ofrece apoyo ligero.', ARRAY['Coloca un pie detrás de modo que solo los dedos rocen el suelo.','Sostén una mancuerna en la mano del lado del pie trasero.','Bisagra en la cadera bajando la mancuerna hacia la espinilla con la espalda recta.','Mantén la mayor parte del peso en el pie delantero.','Empuja con el talón delantero para volver a la posición inicial. Completa todas las repeticiones antes de cambiar de lado.'], ARRAY['Mantén la mancuerna cerca de la pierna durante el descenso.','Para cuando notes el estiramiento en el isquiotibial de la pierna delantera.','Completa todas las repeticiones en un lado antes de cambiar.'], '/exercises/db-kickstand-deadlift-main.webp', '/exercises/db-kickstand-deadlift-main.webp'),
  ('Zancada con Mancuernas', 'db-lunge', 'glutes', ARRAY['hamstrings'], 'dumbbell', 'intermediate', 'compound', 'Un ejercicio unilateral de tren inferior con mancuernas que trabaja los cuádriceps y los glúteos mediante un paso adelante.', ARRAY['De pie, sujeta mancuernas a los costados.','Da un paso adelante con un pie y baja la rodilla trasera hacia el suelo.','Empuja con el pie delantero para volver.','Alterna las piernas.','Repite.'], ARRAY['Mantén el torso erguido.','La rodilla delantera debe seguir la dirección de los pies.'], '/exercises/db-lunge-main.webp', '/exercises/db-lunge-main.webp'),
  ('Paseo con Mancuerna sobre la Cabeza', 'db-overhead-carry', 'shoulders', ARRAY['core','lower_back','traps','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un paseo cargado con una sola mancuerna bloqueada por encima del hombro, que exige estabilidad de hombro y un tronco erguido en cada paso.', ARRAY['Lleva una mancuerna, en cargada o press, hasta quedar bloqueada justo encima del hombro.','Estira el brazo del todo, con el codo bloqueado y el bíceps cerca de la oreja.','Lleva las costillas hacia abajo en lugar de arquear la zona lumbar para sostener el peso arriba.','Camina hacia delante con zancadas controladas, manteniendo la mancuerna alineada sobre hombro y cadera.','Mira al frente — echar la cabeza atrás para vigilar el peso arrastra contigo toda la postura.','Carga la distancia deseada, baja de forma controlada y repite con el otro brazo.'], ARRAY['Iguala la distancia con ambos brazos para que la carga asimétrica no se convierta en una adaptación asimétrica.','El codo bloqueado no es opcional. Con el codo blando toda la carga recae en el músculo en lugar del esqueleto y la serie se acaba enseguida.','Si las costillas se abren y la espalda se arquea, el peso excede tu posición actual por encima de la cabeza — corrige la posición antes de añadir carga.'], '/exercises/db-overhead-carry-main.webp', '/exercises/db-overhead-carry-main.webp'),
  ('Pullover con Mancuerna', 'db-pullover', 'back', ARRAY['triceps'], 'dumbbell', 'intermediate', 'compound', 'Un movimiento compuesto que trabaja los dorsales y el pecho con un movimiento de estiramiento.', ARRAY['Túmbate en un banco plano con una mancuerna sobre el pecho y los brazos extendidos.','Baja la mancuerna detrás de la cabeza en arco, manteniendo una ligera flexión de codos.','Estira hasta sentir tensión en los dorsales y el pecho.','Tira de la mancuerna de vuelta a la posición inicial.','Repite.'], ARRAY['Baja la mancuerna solo hasta donde el hombro lo permita.','Evita arquear la zona lumbar en la fase de estiramiento.','Mantén la flexión de los codos constante durante todo el arco.'], '/exercises/db-pullover-main.webp', '/exercises/db-pullover-main.webp'),
  ('Curl Inverso con Mancuernas', 'db-reverse-curl', 'biceps', NULL, 'dumbbell', 'beginner', 'isolation', 'Una variación del curl con agarre prono que trabaja el braquial y los extensores del antebrazo.', ARRAY['Sujeta las mancuernas con agarre prono a los costados.','Súbelas hasta la altura de los hombros.','Baja de forma controlada.','Repite.'], ARRAY['Mantén las muñecas neutras durante todo el ejercicio.','El movimiento controlado es clave.'], '/exercises/db-reverse-curl-main.webp', '/exercises/db-reverse-curl-main.webp'),
  ('Curl de Muñeca Inverso con Mancuerna', 'db-reverse-wrist-curl', 'forearms', NULL, 'dumbbell', 'beginner', 'isolation', 'Un curl de muñeca con mancuerna y palma hacia abajo, que entrena los extensores del antebrazo.', ARRAY['Siéntate en un banco con el antebrazo sobre el muslo, palma hacia abajo.','Sujeta una mancuerna con la muñeca fuera de la rodilla.','Deja caer la muñeca, bajando la mancuerna.','Levanta el dorso de la mano hacia el techo extendiendo la muñeca.','Baja con control. Repeticiones por lado.'], ARRAY['Usa una carga mucho más ligera que en el curl de muñeca normal.','Mueve solo la muñeca.','Contrae la parte posterior del antebrazo arriba.'], '/exercises/db-reverse-wrist-curl-main.webp', '/exercises/db-reverse-wrist-curl-main.webp'),
  ('Encogimiento de Hombros con Mancuernas', 'db-shrug', 'traps', ARRAY['back'], 'dumbbell', 'beginner', 'isolation', 'Un encogimiento de hombros con mancuernas que trabaja el trapecio superior para dar volumen al cuello y la espalda alta.', ARRAY['De pie, sujeta mancuernas a los costados.','Encoge los hombros hacia arriba lo más alto posible.','Mantén brevemente y luego baja.','Repite.'], ARRAY['No hagas círculos con los hombros.','Concéntrate en apretar el trapecio en la posición superior.'], '/exercises/db-shrug-main.webp', '/exercises/db-shrug-main.webp'),
  ('Skull Crusher con Mancuernas', 'db-skull-crusher', 'triceps', NULL, 'dumbbell', 'intermediate', 'isolation', 'Una extensión de tríceps tumbado con mancuernas que permite el movimiento independiente de cada brazo.', ARRAY['Túmbate en un banco plano sosteniendo mancuernas sobre el pecho.','Baja las mancuernas hacia los lados de la cabeza.','Extiende los brazos hacia arriba.','Repite.'], ARRAY['Mantén los codos apuntando hacia el techo.','Usa un tempo controlado.'], '/exercises/db-skull-crusher-main.webp', '/exercises/db-skull-crusher-main.webp'),
  ('Sentadilla Somersault con Mancuerna', 'db-somersault-squat', 'glutes', ARRAY['hamstrings','core'], 'dumbbell', 'intermediate', 'compound', 'Una sentadilla unilateral con alcance y mancuerna, que añade rotación y movilidad de hombro al patrón de sentadilla.', ARRAY['Pies a la anchura de los hombros, sostén una mancuerna en una mano a la altura del hombro.','Baja en sentadilla mientras llevas la mancuerna al frente y cruzando el cuerpo.','Alcanza el punto bajo con la mancuerna extendida pasando la rodilla opuesta.','Empuja con los talones para subir, regresando la mancuerna al hombro.','Repeticiones por lado, luego cambia.'], ARRAY['Mueve lento durante la rotación para mantener la columna controlada.','Usa una mancuerna ligera — la palanca larga exige al hombro.','Empuja las rodillas afuera para mantener la trayectoria estable.'], '/exercises/db-somersault-squat-main.webp', '/exercises/db-somersault-squat-main.webp'),
  ('Sentadilla con Mancuernas', 'db-squat', 'glutes', ARRAY['hamstrings'], 'dumbbell', 'beginner', 'compound', 'Un patrón de sentadilla cargado con una mancuerna en cada mano, accesible sin barra.', ARRAY['Pies a la anchura de los hombros, una mancuerna en cada mano a los lados.','Activa el core y mantén el pecho arriba.','Baja en sentadilla flexionando caderas y rodillas.','Desciende hasta que los muslos queden paralelos o más abajo.','Empuja con los talones para volver a subir.'], ARRAY['Mantén el pecho arriba y la espalda recta.','Empuja las rodillas en línea con los dedos del pie.','Usa straps si el agarre se convierte en el factor limitante.'], '/exercises/db-squat-main.webp', '/exercises/db-squat-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Sentadilla Sumo con Mancuernas', 'db-sumo-squat', 'glutes', ARRAY['adductors','hamstrings'], 'dumbbell', 'beginner', 'compound', 'Una sentadilla de pies anchos con mancuernas sujetadas a los lados, que enfatiza la cara interna de los muslos y los glúteos.', ARRAY['Ponte de pie con los pies más anchos que los hombros y las puntas giradas hacia afuera unos 30 grados.','Sujeta una mancuerna en cada mano a los lados.','Activa el core y mantén el pecho alto.','Flexiona caderas y rodillas para bajar recto en una sentadilla profunda.','Empuja con los talones para volver a ponerte de pie.','Repite el número de repeticiones deseado.'], ARRAY['Alinea las rodillas con las puntas de los pies; no dejes que se vayan hacia dentro.','Mantén el torso tan erguido como te permita la movilidad de cadera.','Elige mancuernas más ligeras que en una sentadilla normal; el agarre es el límite.'], '/exercises/db-sumo-squat-main.webp', '/exercises/db-sumo-squat-main.webp'),
  ('Press Svend con Mancuernas', 'db-svend-press', 'chest', ARRAY['shoulders','triceps'], 'dumbbell', 'beginner', 'isolation', 'Un ejercicio de pecho de pie presionando dos mancuernas entre sí frente al cuerpo, aísla el pecho interno.', ARRAY['De pie, junta dos mancuernas horizontalmente a la altura del pecho.','Mantén la presión hacia adentro sobre las mancuernas todo el tiempo.','Empuja las mancuernas al frente hasta extender los brazos.','Tíralas de regreso al pecho con control.','Repite el número de repeticiones indicado.'], ARRAY['La presión entre las mancuernas hace el ejercicio — no dejes que se separen.','Usa carga ligera — el objetivo es activar el pecho, no levantar mucho.','Mantén los codos ligeramente flexionados en el lockout.'], '/exercises/db-svend-press-main.webp', '/exercises/db-svend-press-main.webp'),
  ('Dead Bug', 'dead-bug', 'core', NULL, NULL, 'beginner', 'compound', 'Un ejercicio de core en decúbito supino que coordina la extensión de extremidades opuestas para entrenar la estabilidad del core profundo.', ARRAY['Túmbate boca arriba con los brazos extendidos hacia el techo y las rodillas a 90 grados.','Baja el brazo derecho y la pierna izquierda hacia el suelo manteniendo la zona lumbar presionada contra el suelo.','Regresa a la posición inicial.','Repite del otro lado.','Alterna.'], ARRAY['Presiona la zona lumbar contra el suelo en todo momento.','Muévete despacio.'], '/exercises/dead-bug-main.webp', '/exercises/dead-bug-main.webp'),
  ('Dead Bug Isométrico', 'dead-bug-hold', 'core', NULL, NULL, 'beginner', 'compound', 'La posición extendida del dead bug mantenida en el tiempo: tumbado boca arriba con un brazo por encima de la cabeza y la pierna contraria estirada justo por encima del suelo, con la zona lumbar pegada al suelo.', ARRAY['Túmbate boca arriba con los brazos apuntando al techo y las caderas y rodillas flexionadas a 90 grados.','Presiona la zona lumbar contra el suelo y mantenla ahí durante toda la serie.','Extiende un brazo por encima de la cabeza y estira la pierna contraria hasta que ambos queden suspendidos justo sobre el suelo.','Mantén esa posición extendida durante el tiempo indicado, sin que las costillas se abran ni la espalda se arquee.','Vuelve al inicio y repite con el otro brazo y la otra pierna.'], ARRAY['Si la zona lumbar se despega del suelo, mantén la pierna más alta en lugar de buscar el suelo.','Exhala despacio durante el mantenimiento; aguantar la respiración es lo que suele romper la tensión del tronco.','Mantén el brazo extendido junto a la oreja, no abierto hacia el lado.'], '/exercises/dead-bug-hold-main.webp', '/exercises/dead-bug-hold-main.webp'),
  ('Colgado Pasivo', 'dead-hang', 'forearms', ARRAY['back','core','traps'], 'bodyweight', 'intermediate', 'compound', 'Una suspensión estática en barra de dominadas que fortalece el agarre y la musculatura de antebrazos y espalda.', ARRAY['Agarra la barra de dominadas con las palmas mirando hacia afuera, a la anchura de los hombros.','Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.','Relaja los hombros y deja que el cuerpo cuelgue.','Mantén el core ligeramente activo.','Aguanta el tiempo deseado.'], ARRAY['Empieza con tiempos cortos y auméntalos de forma gradual.','Respira tranquilo y evita tensar el cuello.','Baja con control en lugar de soltarte de golpe.'], '/exercises/dead-hang-main.webp', '/exercises/dead-hang-main.webp'),
  ('Peso Muerto con Barra', 'deadlift', 'back', ARRAY['quads','traps'], 'barbell', 'intermediate', 'compound', 'Un levantamiento compuesto de cuerpo completo que trabaja principalmente la cadena posterior.', ARRAY['De pie con los pies a la anchura de las caderas y la barra sobre el medio del pie.','Bisagra en las caderas y agarra la barra.','Contrae el core y levanta extendiendo caderas y rodillas.','Ponte completamente erguido arriba y luego baja de forma controlada.','Repite.'], ARRAY['Mantén la barra cerca del cuerpo.','No redondees la zona lumbar.'], '/exercises/deadlift-main.webp', '/exercises/deadlift-main.webp'),
  ('Press de Banca Declinado', 'decline-bench-press', 'chest', ARRAY['shoulders','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un press de pecho compuesto en banco declinado que trabaja el pectoral inferior.', ARRAY['Ajusta el banco en declinación. Túmbate y asegura los pies.','Descuelga la barra y bájala hasta el pecho inferior.','Vuelve a empujar hasta la posición inicial.','Repite.'], ARRAY['Mantén la espalda plana sobre el banco.','Usa un ayudante cuando trabajes con cargas más pesadas.'], '/exercises/decline-bench-press-main.webp', '/exercises/decline-bench-press-main.webp'),
  ('Press de Banca Declinado con Barra', 'decline-bench-press-barbell', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Un press compuesto con barra en banco declinado que enfatiza el pecho inferior.', ARRAY['Ajusta el banco en declinación. Túmbate y asegura los pies.','Agarra la barra ligeramente más ancha que la anchura de los hombros.','Baja la barra hasta el pecho inferior y luego empuja hacia arriba.','Repite.'], ARRAY['Controla el descenso.','Mantén los codos a unos 45 grados respecto al torso.'], '/exercises/decline-bench-press-barbell-main.webp', '/exercises/decline-bench-press-barbell-main.webp'),
  ('Press de Banca Declinado con Barra Z', 'decline-bench-press-ez-bar', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Un press declinado con barra Z y agarre cómodo para las muñecas que trabaja el pecho inferior.', ARRAY['Ajusta el banco en declinación. Asegura los pies y agarra la barra Z.','Baja la barra hasta el pecho inferior.','Empuja hacia arriba de forma explosiva.','Repite.'], ARRAY['El agarre angulado reduce la tensión en las muñecas.','Mantén el core contraído.'], '/exercises/decline-bench-press-ez-bar-main.webp', '/exercises/decline-bench-press-ez-bar-main.webp'),
  ('Crunch Declinado', 'decline-crunch', 'core', NULL, NULL, 'intermediate', 'isolation', 'Un crunch realizado en banco declinado, aumentando el rango de movimiento y la resistencia sobre los abdominales.', ARRAY['Asegura los pies en la parte superior del banco declinado.','Recuéstate con las manos cruzadas sobre el pecho o detrás de la cabeza.','Sube contrayendo la columna hacia las rodillas.','Aprieta el abdomen en la posición superior.','Baja de forma controlada y repite.'], ARRAY['Enrolla la columna en lugar de tirar del cuello.','Exhala al subir y aprieta los abdominales arriba.','Baja despacio en lugar de dejarte caer sobre el banco.'], '/exercises/decline-crunch-main.webp', '/exercises/decline-crunch-main.webp'),
  ('Aperturas con Mancuernas en Banco Declinado', 'decline-db-fly', 'chest', ARRAY['shoulders'], 'dumbbell', 'intermediate', 'isolation', 'Un movimiento de apertura en banco declinado para enfatizar el pecho inferior.', ARRAY['Túmbate en un banco declinado sosteniendo mancuernas sobre el pecho.','Con una ligera flexión de codos, baja las mancuernas ampliamente hacia los lados.','Aprieta el pecho para subirlas de nuevo.','Repite.'], ARRAY['No extiendas completamente los codos.','Concéntrate en el estiramiento en la posición inferior.'], '/exercises/decline-db-fly-main.webp', '/exercises/decline-db-fly-main.webp'),
  ('Flexión Declinada', 'decline-push-up', 'chest', ARRAY['shoulders','triceps'], NULL, 'intermediate', 'compound', 'Una flexión con los pies elevados para aumentar la activación del pecho superior y los hombros.', ARRAY['Coloca los pies en una superficie elevada y las manos en el suelo.','Baja el pecho hacia el suelo de forma controlada.','Vuelve a empujar hasta la posición inicial.','Repite.'], ARRAY['Mantén el cuerpo en línea recta.','Cuanto mayor sea la elevación, más se trabaja el pecho superior.'], '/exercises/decline-push-up-main.webp', '/exercises/decline-push-up-main.webp'),
  ('Peso Muerto en Déficit', 'deficit-deadlift', 'back', ARRAY['quads','traps'], 'barbell', 'advanced', 'compound', 'Un peso muerto ejecutado sobre una plataforma baja que amplía el recorrido y exige más a isquiotibiales y glúteos.', ARRAY['De pie sobre una plataforma pequeña con una barra cargada sobre el medio del pie.','Bisagra hacia abajo y agarra la barra justo por fuera de las rodillas.','Empuja con las piernas para ponerte erguido manteniendo la barra cerca.','Bloquea caderas y rodillas en la parte superior.','Baja de forma controlada y repite.'], ARRAY['Mantén la columna neutra en todo el recorrido ampliado.','Usa menos peso del que mueves en tu peso muerto habitual.','Domina el peso muerto convencional antes de probar esta variante.'], '/exercises/deficit-deadlift-main.webp', '/exercises/deficit-deadlift-main.webp'),
  ('Flexiones en Déficit', 'deficit-push-ups', 'chest', ARRAY['shoulders','core','triceps'], NULL, 'advanced', 'compound', 'Una flexión de brazos con las manos sobre soportes elevados, que aumenta el rango de movimiento y el estiramiento del pectoral.', ARRAY['Coloca las manos en dos superficies elevadas como parallettes o bloques.','Adopta la posición de plancha con las manos bajo los hombros.','Baja el pecho por debajo del nivel de las manos.','Empuja hacia arriba para extender los brazos.','Repite el número de repeticiones deseado.'], ARRAY['Baja solo hasta donde tus hombros toleren el estiramiento.','Mantén el cuerpo en línea recta, sin hundir la cadera.','Progresa desde las flexiones normales antes de añadir déficit.'], '/exercises/deficit-push-ups-main.webp', '/exercises/deficit-push-ups-main.webp'),
  ('Flexiones en Diamante', 'diamond-push-ups', 'chest', ARRAY['shoulders','core'], NULL, 'intermediate', 'compound', 'Una flexión con las manos juntas formando un diamante con pulgares e índices, trasladando el énfasis a los tríceps.', ARRAY['Adopta la posición de flexión con las manos juntas formando un diamante.','Mantén los codos pegados a los costados.','Baja el pecho hacia las manos.','Empuja hacia arriba para extender los brazos.','Repite el número de repeticiones deseado.'], ARRAY['Lleva los codos hacia atrás pegados a los costados, sin abrirlos.','Mantén el cuerpo en una línea recta y rígida de la cabeza a los talones.','Baja con control hasta que el pecho llegue a las manos.'], '/exercises/diamond-push-ups-main.webp', '/exercises/diamond-push-ups-main.webp'),
  ('Fondos para Pecho', 'dips', 'chest', ARRAY['shoulders'], 'bodyweight', 'intermediate', 'compound', 'Un ejercicio compuesto de peso corporal que trabaja el pecho inferior y los tríceps.', ARRAY['Agarra las barras paralelas y súbete a la posición superior con los brazos extendidos.','Inclina el torso ligeramente hacia adelante.','Baja el cuerpo doblando los codos hasta que los hombros queden por debajo de los codos.','Vuelve a empujar hasta la posición inicial.','Repite.'], ARRAY['Acentúa la inclinación del torso si quieres más trabajo de pecho.','Detén la bajada si notas molestia en el hombro.','Evita encoger los hombros hacia las orejas al empujar.'], '/exercises/dips-main.webp', '/exercises/dips-main.webp'),
  ('Postura del Delfín', 'dolphin-pose', 'shoulders', ARRAY['hamstrings','core'], NULL, 'intermediate', 'compound', 'Una V invertida sostenida sobre los antebrazos: las caderas suben hacia el techo mientras los hombros asumen la carga, la preparación estándar para las inversiones sobre antebrazos.', ARRAY['Arrodíllate y apoya los antebrazos en el suelo a la anchura de los hombros, con los codos bajo los hombros.','Mete los dedos de los pies y eleva las caderas arriba y atrás hasta formar una V invertida.','Presiona los antebrazos contra el suelo y aleja los hombros de las orejas; los talones pueden quedar altos.','Mantén la posición durante el tiempo indicado, con el cuello relajado entre los brazos.','Baja las rodillas al suelo para salir.'], ARRAY['Evita que los codos se abran; una cinta alrededor de los brazos mantiene la distancia.','Flexiona bien las rodillas para que la columna siga larga en lugar de perseguir piernas rectas.','Acerca un poco los pies a los codos para llevar más peso a los hombros.'], '/exercises/dolphin-pose-main.webp', '/exercises/dolphin-pose-main.webp'),
  ('Elevación de Pantorrilla a la Burra', 'donkey-calf-raise', 'calves', NULL, NULL, 'intermediate', 'isolation', 'Una elevación de pantorrilla inclinada que maximiza el estiramiento al flexionar las caderas.', ARRAY['Flexiona las caderas y apoya los antebrazos sobre un banco.','Coloca las puntas de los pies en una plataforma elevada, talones al aire.','Baja los talones por debajo de la plataforma para un estiramiento completo.','Empuja arriba sobre las puntas tanto como puedas, contrayendo las pantorrillas.','Baja con control hasta el estiramiento profundo.'], ARRAY['Pausa brevemente arriba para maximizar la contracción.','Usa una excéntrica lenta para el estiramiento completo.','Añade un compañero o peso sobre la zona lumbar para más resistencia.'], '/exercises/donkey-calf-raise-main.webp', '/exercises/donkey-calf-raise-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Estiramiento de Pecho en el Marco', 'doorway-chest-stretch', 'chest', ARRAY['shoulders'], NULL, 'beginner', 'mobility', 'Un estiramiento de brazos abiertos que alarga el pecho y los hombros frontales al llevar los brazos atrás.', ARRAY['Párate erguido y sube los brazos en posición de portería.','Flexiona los codos noventa grados, antebrazos verticales.','Lleva los codos atrás y junta los omóplatos.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén las costillas abajo y evita arquear la espalda.','Estira hasta una tensión leve, nunca hasta el dolor.'], '/exercises/doorway-chest-stretch-main.webp', '/exercises/doorway-chest-stretch-main.webp'),
  ('Peso Muerto Kickstand con Doble Mancuerna', 'double-db-kickstand-deadlift', 'glutes', ARRAY['adductors','back'], 'dumbbell', 'intermediate', 'compound', 'Un movimiento de bisagra de cadera en postura escalonada con dos mancuernas que carga principalmente la pierna delantera con el pie trasero como apoyo de equilibrio.', ARRAY['Coloca un pie detrás de modo que solo los dedos toquen el suelo.','Sostén una mancuerna en cada mano a la altura de la cadera.','Bisagra en la cadera bajando ambas mancuernas hacia la espinilla con la espalda recta.','Mantén la mayor parte del peso en el pie delantero.','Empuja con el talón delantero para volver a posición inicial. Cambia de lado.'], ARRAY['Mantén las mancuernas cerca de las piernas.','Para al notar el estiramiento en el isquiotibial de la pierna delantera.','Completa todas las repeticiones en un lado antes de cambiar.'], '/exercises/double-db-kickstand-deadlift-main.webp', '/exercises/double-db-kickstand-deadlift-main.webp'),
  ('Paseo con Dos Mancuernas sobre la Cabeza', 'double-db-overhead-carry', 'shoulders', ARRAY['back','core','traps','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un paseo cargado con una mancuerna bloqueada sobre cada hombro, que duplica la carga por encima de la cabeza y elimina el brazo libre que de otro modo te ayudaría a equilibrarte.', ARRAY['Lleva una mancuerna, en cargada o press, hasta el bloqueo sobre cada hombro.','Estira ambos codos del todo y empuja las escápulas hacia los pesos en lugar de encogerte alejándote de ellos.','Aprieta fuerte y mantén las costillas abajo — con los dos brazos arriba la tentación de arquearse es mucho mayor.','Camina hacia delante con zancadas cortas y deliberadas, manteniendo ambas mancuernas alineadas sobre los hombros.','Sigue respirando de forma superficial y constante en vez de aguantar el aire todo el recorrido.','Carga la distancia deseada y baja después ambos pesos de forma controlada.'], ARRAY['Empieza con menos peso por mano que en el paseo a un brazo. Dos brazos por encima de la cabeza no son la mitad de fáciles, son el doble de estabilizar.','Ten pensado cómo abandonar la serie antes de empezar, y carga donde puedas soltar los pesos sin peligro.','Distancias cortas bien hechas superan a las largas hechas torcido. Corta la serie cuando se abran las costillas, no cuando cedan los hombros.'], '/exercises/double-db-overhead-carry-main.webp', '/exercises/double-db-overhead-carry-main.webp'),
  ('Curl de Bíceps con Dos Pesas Rusas', 'double-kettlebell-bicep-curl', 'biceps', ARRAY['forearms'], 'kettlebell', 'beginner', 'isolation', 'Un curl de bíceps de pie con una pesa rusa en cada mano, sujeta por el asa. La masa descentrada en la parte inferior de la pesa añade un ligero reto de agarre y estabilidad.', ARRAY['Ponte de pie sujetando una pesa rusa en cada mano por el asa, con las palmas mirando hacia adelante.','Mantén los codos pegados a los costados y las pesas colgando a lo largo de los brazos.','Sube ambas pesas rusas hacia los hombros flexionando los codos.','Aprieta los bíceps en la parte superior, luego baja de forma controlada hasta la posición inicial.','Repite el número de repeticiones recomendado.'], ARRAY['No dejes que las pesas oscilen — controla la fase excéntrica.','Los codos permanecen pegados a los costados; sin flexión de hombros.','Agarra con fuerza durante todo el movimiento; la pesa tiende a extender la muñeca.'], '/exercises/double-kettlebell-bicep-curl-main.webp', '/exercises/double-kettlebell-bicep-curl-main.webp'),
  ('Clean con Dos Pesas Rusas', 'double-kettlebell-clean', 'glutes', ARRAY['shoulders','back','forearms','traps'], 'kettlebell', 'advanced', 'compound', 'Un jalón de cadera explosivo que lleva dos pesas rusas simultáneamente hasta los hombros en posición de rack, base para los press y jerk con doble pesa rusa.', ARRAY['Ponte de pie con dos pesas rusas en el suelo entre tus pies, con las asas ligeramente giradas hacia adentro.','Inclínate desde las caderas, agarra las asas y envía las pesas rusas hacia atrás entre las piernas.','Extiende las caderas de forma explosiva para impulsar las pesas rusas hacia arriba a lo largo del cuerpo.','Cuando lleguen a la altura del pecho, mete las manos por las asas para recibirlas en la posición de rack sobre los hombros.','Baja de vuelta a la posición colgante inclinándote desde las caderas y guiando las pesas entre las piernas.','Repite el número de repeticiones recomendado.'], ARRAY['Mete las manos por las asas — no dejes que las pesas se vuelquen y golpeen las muñecas.','El impulso viene de las caderas; los brazos solo guían el trayecto.'], '/exercises/double-kettlebell-clean-main.webp', '/exercises/double-kettlebell-clean-main.webp'),
  ('Clean and press con doble kettlebell', 'double-kettlebell-clean-and-press', 'shoulders', ARRAY['glutes','quads','core','traps','triceps'], 'kettlebell', 'advanced', 'compound', 'Un ejercicio de fuerza de cuerpo completo que sube dos kettlebells desde el suelo hasta la posición de rack en los hombros y luego las presiona por encima de la cabeza hasta la extensión completa en una secuencia continua.', ARRAY['Colócate con dos kettlebells en el suelo entre los pies, separados a la anchura de las caderas, y flexiona las caderas para agarrar un asa con cada mano.','Empuja con las piernas y extiende las caderas de forma explosiva para tirar de ambas kettlebells hacia arriba; luego rota los codos por debajo y recibe las pesas en la posición de rack, al frente de los hombros.','Activa el core y presiona ambas kettlebells por encima de la cabeza hasta bloquear los brazos por completo.','Baja las kettlebells de vuelta a la posición de rack y después al suelo de forma controlada.','Repite las repeticiones deseadas.'], ARRAY['Mantén las kettlebells cerca del cuerpo durante el clean y pasa las manos alrededor y a través de las asas al recibirlas, para que las pesas se asienten sobre los antebrazos en lugar de golpearlos.','Inicia la presión con un breve impulso de piernas y caderas (dip-drive) y termina con los hombros; mantén el core firme para no inclinarte hacia atrás bajo la carga.','En el bloqueo mantén las muñecas rectas y las kettlebells alineadas sobre los codos y los hombros, con la cabeza en posición neutra entre las pesas.'], '/exercises/double-kettlebell-clean-and-press-main.webp', '/exercises/double-kettlebell-clean-and-press-main.webp'),
  ('Dead Clean con Dos Pesas Rusas', 'double-kettlebell-dead-clean', 'glutes', ARRAY['back','forearms','quads','traps'], 'kettlebell', 'intermediate', 'compound', 'Un clean con dos pesas rusas desde el suelo que desarrolla potencia de cadera llevando ambas pesas a la posición de rack.', ARRAY['Coloca dos pesas rusas en el suelo entre tus pies.','Inclínate y agarra ambas asas.','Empuja de forma explosiva con las piernas y las caderas.','Tira de las pesas rusas hacia arriba y gíralas hasta la posición de rack.','Bájalas de vuelta al suelo y repite.'], ARRAY['Genera la fuerza con las caderas, no con los brazos.','Mantén las pesas cerca del cuerpo durante la subida.','Recibe en el rack con suavidad, sin golpear los antebrazos.'], '/exercises/double-kettlebell-dead-clean-main.webp', '/exercises/double-kettlebell-dead-clean-main.webp'),
  ('Dead Split Snatch con Dos Pesas Rusas', 'double-kettlebell-dead-split-snatch', 'shoulders', ARRAY['back','hamstrings','quads','traps'], 'kettlebell', 'intermediate', 'compound', 'Un snatch con dos pesas rusas desde el suelo que se recibe en posición de tijera con los brazos bloqueados arriba.', ARRAY['Coloca dos pesas rusas en el suelo entre tus pies.','Inclínate y agarra ambas asas con firmeza.','Tira de las pesas rusas por encima de la cabeza de forma explosiva en un solo movimiento.','Cae en postura dividida para recibirlas con los brazos bloqueados.','Recupera la posición juntando los pies.'], ARRAY['Practica la tijera sin peso hasta dominar la recepción.','Recibe con los codos completamente bloqueados.','Mantén el torso erguido al entrar en la tijera.'], '/exercises/double-kettlebell-dead-split-snatch-main.webp', '/exercises/double-kettlebell-dead-split-snatch-main.webp'),
  ('Jerk con Dos Pesas Rusas', 'double-kettlebell-jerk', 'shoulders', ARRAY['glutes','traps','triceps'], 'kettlebell', 'advanced', 'compound', 'Un levantamiento por encima de la cabeza que utiliza un doble impulso de piernas para elevar dos pesas rusas desde el rack hasta el bloqueo, el movimiento emblema del deporte de pesas rusas.', ARRAY['Comienza con dos pesas rusas en rack sobre los hombros, con los codos apoyados sobre las caderas.','Realiza una pequeña flexión de rodillas y luego extiende las piernas de forma explosiva para impulsar las pesas hacia arriba.','Cuando suban, realiza una segunda flexión de rodillas por debajo de ellas.','Recibe las pesas rusas por encima de la cabeza con los brazos bloqueados y ponte completamente de pie.','Bájalas de vuelta al rack de forma controlada y repite.'], ARRAY['El jerk tiene dos impulsos, no uno — el segundo impulso es el que te permite bloquear con los brazos relajados.','Respira en cada repetición; el hold es una habilidad aparte.'], '/exercises/double-kettlebell-jerk-main.webp', '/exercises/double-kettlebell-jerk-main.webp'),
  ('Paseo con Dos Kettlebells sobre la Cabeza', 'double-kettlebell-overhead-carry', 'shoulders', ARRAY['back','forearms','core','traps','triceps'], 'kettlebell', 'advanced', 'compound', 'Un paseo cargado con una kettlebell bloqueada sobre cada hombro — el más difícil de sostener quieto de todos los paseos, ya que combina la masa descentrada de las bolas con el doble de carga por encima de la cabeza.', ARRAY['Lleva dos kettlebells al rack y luego pásalas a bloqueo por encima de la cabeza con press o push press.','Estira ambos codos y asienta cada bola por detrás y por encima de su muñeca, con las muñecas rectas.','Lleva las costillas abajo y aprieta fuerte antes del primer paso; con las dos bolas arriba no queda nada con lo que contrapesar.','Camina hacia delante con zancadas cortas y controladas, manteniendo ambas bolas alineadas sobre los hombros.','Sigue mirando al frente y respira de forma constante durante todo el paseo.','Cubre la distancia deseada y baja después ambas bolas al rack y al suelo de forma controlada.'], ARRAY['Gánate este ejercicio. Domina el paseo con una sola kettlebell por ambos lados antes de cargar dos.','Hazlo solo donde puedas soltar ambas bolas con seguridad, y ten claro hacia dónde te apartarás si hace falta.','La distancia debe ser corta y la postura perfecta. En cuanto la espalda se arquee o se doble una muñeca, la serie ha terminado.'], '/exercises/double-kettlebell-overhead-carry-main.webp', '/exercises/double-kettlebell-overhead-carry-main.webp'),
  ('Press por Encima de la Cabeza con Dos Pesas Rusas', 'double-kettlebell-overhead-press', 'shoulders', ARRAY['core','traps'], 'kettlebell', 'intermediate', 'compound', 'Un press vertical con dos pesas rusas desde la posición de rack que desarrolla hombros y tríceps con gran exigencia del core.', ARRAY['Lleva dos pesas rusas al rack sobre los hombros.','Ponte de pie con los pies separados al ancho de las caderas.','Empuja ambas pesas rusas directamente hacia arriba.','Bloquea los brazos en la parte superior.','Baja de vuelta a la posición de rack y repite.'], ARRAY['Aprieta el abdomen para evitar arquear la zona lumbar.','Adelanta ligeramente la cabeza cuando las pesas pasen la frente.','Baja al rack con control entre repeticiones.'], '/exercises/double-kettlebell-overhead-press-main.webp', '/exercises/double-kettlebell-overhead-press-main.webp'),
  ('Push Press con Dos Pesas Rusas', 'double-kettlebell-push-press', 'shoulders', ARRAY['glutes','quads','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un push press con dos pesas rusas en rack. El impulso de piernas (un solo descenso) permite lanzar más carga por encima de la cabeza que en un press estricto — el nivel intermedio entre el press militar estricto y el jerk.', ARRAY['Ponte de pie con dos pesas rusas en rack sobre los hombros, codos hacia abajo y pegados.','Pies al ancho de los hombros, core contraído.','Flexiona ligeramente las rodillas manteniendo el torso vertical.','Extiende las piernas de forma explosiva y empuja ambas pesas por encima de la cabeza en un solo movimiento.','Bloquea los brazos con las pesas sobre el punto medio del pie.','Baja de vuelta al rack de forma controlada.','Repite el número de repeticiones recomendado.'], ARRAY['Solo UN descenso — si vuelves a doblar las rodillas bajo las pesas, eso es un jerk.','El impulso viene de las piernas; los brazos terminan el movimiento.','El torso permanece vertical en todo momento; sin inclinación.'], '/exercises/double-kettlebell-push-press-main.webp', '/exercises/double-kettlebell-push-press-main.webp'),
  ('Remo con Dos Pesas Rusas para Deltoides Posterior', 'double-kettlebell-rear-delt-row', 'shoulders', ARRAY['biceps','back','traps'], 'kettlebell', 'intermediate', 'compound', 'Un remo inclinado con una pesa rusa en cada mano y los codos abiertos hacia fuera, lejos del torso, que traslada el trabajo de los dorsales a los deltoides posteriores y la parte alta de la espalda.', ARRAY['Coloca una pesa rusa justo por fuera de cada pie, con los pies separados a la anchura de las caderas.','Inclínate desde las caderas con la espalda plana hasta que el torso quede casi paralelo al suelo, con las rodillas ligeramente flexionadas.','Sujeta ambas asas con agarre prono y deja los brazos colgando rectos desde los hombros.','Rema ambas pesas llevando los codos hacia los lados, alejándolos de las costillas en lugar de deslizarlos hacia atrás junto a ellas.','Detente cuando los brazos queden más o menos en línea con los hombros y aprieta los omóplatos.','Baja las pesas de forma controlada hasta que los brazos vuelvan a colgar rectos y repite las repeticiones deseadas.'], ARRAY['El codo abierto es toda la clave. Si se pega a las costillas estarás haciendo un remo con dos pesas rusas normal y trabajando los dorsales en lugar de los deltoides posteriores.','Usa menos carga que en un remo convencional. El codo abierto es una palanca larga y el deltoides posterior es un motor mucho más pequeño que el dorsal.','Mantén constante el ángulo de la inclinación. Enderezarte al tirar traslada el trabajo al trapecio y a la zona lumbar y acorta justo el rango en el que trabaja el deltoides posterior.'], '/exercises/double-kettlebell-rear-delt-row-main.webp', '/exercises/double-kettlebell-rear-delt-row-main.webp'),
  ('Remo con Dos Pesas Rusas', 'double-kettlebell-row', 'back', ARRAY['biceps','traps'], 'kettlebell', 'intermediate', 'compound', 'Un remo inclinado con dos pesas rusas que desarrolla dorsales y romboides con fuerte trabajo postural.', ARRAY['Sujeta una pesa rusa en cada mano e inclínate hacia adelante desde las caderas.','Deja los brazos colgando rectos desde los hombros.','Rema ambas pesas rusas hacia las caderas llevando los codos hacia atrás.','Aprieta los omóplatos en la parte superior.','Baja de forma controlada y repite.'], ARRAY['No redondees la zona lumbar al mantener la inclinación.','Evita los tirones y rema con un movimiento fluido.','Si la fatiga rompe tu postura, termina la serie.'], '/exercises/double-kettlebell-row-main.webp', '/exercises/double-kettlebell-row-main.webp'),
  ('Split Jerk con Dos Pesas Rusas', 'double-kettlebell-split-jerk', 'shoulders', ARRAY['glutes','traps','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un jerk con dos pesas rusas que combina un impulso de piernas con una recepción en tijera bajo la carga.', ARRAY['Lleva dos pesas rusas al rack sobre los hombros.','Flexiona ligeramente las rodillas.','Impulsa las pesas rusas por encima de la cabeza de forma explosiva.','Separa las piernas para recibirlas con los brazos bloqueados.','Recupera la posición juntando los pies.'], ARRAY['Haz el dip corto y vertical, sin inclinar el torso.','Genera el empuje con las piernas, no con los hombros.','Bloquea los codos antes de juntar los pies.'], '/exercises/double-kettlebell-split-jerk-main.webp', '/exercises/double-kettlebell-split-jerk-main.webp'),
  ('Swing Snatch con Dos Pesas Rusas', 'double-kettlebell-swing-snatch', 'glutes', ARRAY['shoulders','back','forearms','traps'], 'kettlebell', 'intermediate', 'compound', 'Un snatch con dos pesas rusas iniciado con un swing entre las piernas y finalizado con ambas pesas bloqueadas arriba.', ARRAY['Ponte de pie con los pies al ancho de los hombros sujetando dos pesas rusas.','Inclínate desde las caderas para balancear las pesas entre las piernas.','Extiende las caderas de forma explosiva para balancear las pesas hacia arriba.','Empuja hacia arriba para recibir ambas pesas rusas por encima de la cabeza con los brazos bloqueados.','Baja de forma controlada y repite.'], ARRAY['Genera la potencia con un golpe seco de cadera.','Mantén la espalda plana cuando las pesas pasan entre las piernas.','Suaviza la recepción arriba para que las pesas no golpeen tus antebrazos.'], '/exercises/double-kettlebell-swing-snatch-main.webp', '/exercises/double-kettlebell-swing-snatch-main.webp'),
  ('Perro Boca Abajo', 'downward-dog', 'calves', ARRAY['back','glutes'], NULL, 'beginner', 'mobility', 'Un estiramiento en V invertida que alarga a la vez isquiotibiales, pantorrillas, hombros y espalda.', ARRAY['Empieza en cuadrupedia con las manos algo por delante de los hombros.','Apoya los dedos de los pies y eleva la cadera hacia arriba y atrás.','Estira las piernas y lleva los talones hacia el suelo.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Flexiona las rodillas si la zona lumbar se redondea.','Empuja el suelo para alargar la columna.'], '/exercises/downward-dog-main.webp', '/exercises/downward-dog-main.webp'),
  ('Rodilla al Pecho en Perro Boca Abajo', 'downward-dog-knee-tuck', 'core', ARRAY['shoulders'], NULL, 'intermediate', 'compound', 'Un ejercicio dinámico de core sostenido en perro boca abajo: las caderas se mantienen altas mientras una rodilla se lleva bajo el pecho y vuelve al inicio, alternando lados. Los hombros sostienen toda la serie, de modo que el tronco trabaja sin la posición baja de cadera de una plancha.', ARRAY['Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas.','Empuja el suelo y aprieta el tronco para que la zona lumbar siga larga.','Lleva una rodilla hacia el pecho, redondeando ligeramente la espalda alta al entrar.','Extiende la pierna de vuelta a la posición inicial de forma controlada.','Repite con la otra pierna y sigue alternando las veces indicadas.'], ARRAY['Mantén las caderas altas; si caen, esto se convierte en un escalador.','Lleva la rodilla con el abdomen en lugar de impulsarte con el pie de apoyo.','Aleja los hombros de las orejas para que el tronco no se hunda entre los brazos.'], '/exercises/downward-dog-knee-tuck-main.webp', '/exercises/downward-dog-knee-tuck-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Pedaleo en Perro Boca Abajo', 'downward-dog-pedal', 'calves', ARRAY['hamstrings'], NULL, 'beginner', 'mobility', 'Un calentamiento dentro del perro boca abajo: las rodillas se flexionan alternando, de modo que cada talón presiona hacia el suelo por turnos y la pantorrilla y el tobillo reciben un estiramiento en movimiento en lugar de un mantenimiento estático.', ARRAY['Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas.','Flexiona una rodilla y deja que ese talón se eleve mientras el talón contrario presiona hacia el suelo.','Cambia de lado con fluidez, como pedaleando, manteniendo las caderas altas todo el tiempo.','Presiona las manos por igual para que los hombros se mantengan estables.','Sigue alternando las veces o el tiempo indicados.'], ARRAY['Mantén las caderas altas; el objetivo son las pantorrillas, no una flexión más profunda.','Presiona toda la mano contra el suelo para que las muñecas no carguen con todo.','Muévete lo bastante despacio como para sentir cada lado en lugar de rebotar.'], '/exercises/downward-dog-pedal-main.webp', '/exercises/downward-dog-pedal-main.webp'),
  ('Rodilla al Codo desde Perro de Tres Patas', 'downward-dog-to-knee-drive', 'core', ARRAY['shoulders','glutes'], NULL, 'intermediate', 'compound', 'Desde el perro de tres patas, la pierna elevada se pliega hacia delante para llevar la rodilla hacia el codo o la nariz y vuelve a extenderse. Los hombros sostienen la posición y el tronco hace el plegado, un lado cada vez.', ARRAY['Colócate en perro boca abajo y eleva una pierna por detrás a perro de tres patas.','Presiona ambas manos contra el suelo y desplaza el peso ligeramente hacia delante.','Redondea la espalda alta y lleva esa rodilla hacia el codo o la nariz.','Extiende la pierna de vuelta arriba de forma controlada.','Termina las repeticiones de ese lado y cambia.'], ARRAY['Deja que la espalda alta se redondee al entrar la rodilla; con la espalda plana la rodilla se queda corta.','Mantén los hombros sobre las muñecas al desplazarte en lugar de pasarte por delante.','Eleva la pierna solo hasta donde las caderas sigan niveladas al salir.'], '/exercises/downward-dog-to-knee-drive-main.webp', '/exercises/downward-dog-to-knee-drive-main.webp'),
  ('Perro Boca Abajo a Zancada Baja', 'downward-dog-to-low-lunge', 'core', ARRAY['glutes','quads'], NULL, 'beginner', 'mobility', 'El paso al frente clásico: desde el perro boca abajo un pie viaja entre las manos hasta una zancada baja y regresa. Abre el flexor de la cadera de la pierna trasera y ensaya la transición que aparece en toda práctica de flujo.', ARRAY['Empieza en perro boca abajo con las manos a la anchura de los hombros.','Desplaza el peso hacia delante y lleva un pie entre las manos.','Baja la rodilla trasera al suelo y hunde las caderas en una zancada baja.','Empuja con las manos, levanta la rodilla trasera y devuelve el pie delantero al perro boca abajo.','Repite del otro lado y sigue alternando.'], ARRAY['Lleva el pie hasta la altura de las manos en lugar de quedarte corto y arrastrarlo.','Acolcha la rodilla trasera con una esterilla doblada si el suelo es duro.','Mantén la rodilla delantera sobre el tobillo cuando bajen las caderas.'], '/exercises/downward-dog-to-low-lunge-main.webp', '/exercises/downward-dog-to-low-lunge-main.webp'),
  ('Perro Boca Abajo a Plancha', 'downward-dog-to-plank', 'shoulders', ARRAY['hamstrings','core','traps'], NULL, 'intermediate', 'compound', 'Una transición en movimiento entre el perro boca abajo y la plancha alta: las caderas viajan de arriba a la horizontal y de vuelta, de modo que hombros y tronco trabajan en recorrido completo en lugar de sostener una posición.', ARRAY['Colócate en perro boca abajo con las caderas altas y las manos a la anchura de los hombros.','Desplaza el peso hacia delante y baja las caderas hasta formar una línea recta en plancha alta.','Sostén la plancha un instante con las costillas cerradas y los glúteos activos.','Empuja el suelo y eleva las caderas de vuelta al perro boca abajo.','Sigue alternando las veces indicadas.'], ARRAY['Lo que se mueve son las caderas, no las manos; las palmas se quedan en el mismo sitio toda la serie.','Mantén los hombros alejados de las orejas en ambas posiciones.','Frena la transición si la zona lumbar se hunde al entrar en la plancha.'], '/exercises/downward-dog-to-plank-main.webp', '/exercises/downward-dog-to-plank-main.webp'),
  ('Perro Boca Abajo a Perro Boca Arriba', 'downward-dog-to-upward-dog', 'shoulders', ARRAY['chest','core','triceps'], NULL, 'intermediate', 'compound', 'La transición del vinyasa: el cuerpo viaja desde el perro boca abajo hacia delante al perro boca arriba y de vuelta, alternando entre una V invertida cargada en los hombros y una extensión con el pecho abierto.', ARRAY['Empieza en perro boca abajo con las caderas altas y las manos a la anchura de los hombros.','Desplázate hacia delante pasando por la plancha, baja un poco y lleva el pecho al frente hasta el perro boca arriba con los muslos despegados.','Lleva los hombros atrás y abajo y mantén el cuello largo.','Mete los dedos de los pies, empuja el suelo y eleva las caderas de vuelta al perro boca abajo.','Sigue moviéndote entre ambas posiciones las veces indicadas.'], ARRAY['Lo que se mueve son las caderas, no las manos; las palmas siguen plantadas toda la serie.','Presiona el empeine en el perro boca arriba para que los muslos se despeguen de verdad.','Frena en mitad de la transición en lugar de balancearte entre los extremos.'], '/exercises/downward-dog-to-upward-dog-main.webp', '/exercises/downward-dog-to-upward-dog-main.webp'),
  ('Drag Curl', 'drag-curl', 'biceps', NULL, 'barbell', 'intermediate', 'isolation', 'Un curl con barra en el que los codos viajan hacia atrás y la barra se desliza por el torso, eliminando la asistencia del deltoides anterior y enfatizando la cabeza larga del bíceps.', ARRAY['Ponte de pie sujetando una barra con agarre supino, con las manos al ancho de los hombros.','Comienza con la barra en los muslos y los codos a los costados.','Sube la barra deslizándola (arrastrándola) hacia arriba a lo largo del cuerpo.','A medida que sube, deja que los codos viajen hacia atrás para que la barra permanezca en contacto con el torso.','Para cuando la barra llegue a la altura del pecho; los bíceps estarán completamente contraídos.','Baja de forma controlada siguiendo el mismo trayecto y repite.'], ARRAY['Usa significativamente menos peso que en un curl estándar — la mecánica modificada lo hace mucho más difícil.','La barra nunca debe separarse del cuerpo.'], '/exercises/drag-curl-main.webp', '/exercises/drag-curl-main.webp'),
  ('Dragon Flag', 'dragon-flag', 'core', ARRAY['back'], NULL, 'advanced', 'compound', 'Un exigente ejercicio de core en banco: agarrando detrás de la cabeza, elevas todo el cuerpo en una línea recta y rígida apoyada solo en la parte alta de la espalda.', ARRAY['Túmbate en un banco y agárralo firmemente detrás de la cabeza.','Eleva el cuerpo de forma que solo la parte superior de la espalda permanezca apoyada en el banco.','Mantén el cuerpo rígido en línea recta.','Baja el cuerpo de forma controlada hasta quedar casi horizontal.','Sube de vuelta y repite.'], ARRAY['Mantén el cuerpo rígido de hombros a pies y muévete solo desde los hombros.','Baja tan despacio como puedas: la fase excéntrica es el ejercicio.','Empieza con progresiones con piernas recogidas o a una pierna antes del dragon flag completo.'], '/exercises/dragon-flag-main.webp', '/exercises/dragon-flag-main.webp'),
  ('Remo en Banco con Mancuernas', 'dumbbell-bench-pull', 'back', ARRAY['biceps','shoulders'], 'dumbbell', 'intermediate', 'compound', 'Un movimiento de remo boca abajo sobre un banco para trabajar la parte superior de la espalda de forma estricta.', ARRAY['Túmbate boca abajo en un banco inclinado sujetando mancuernas.','Deja los brazos colgando rectos hacia abajo.','Tira de las mancuernas hacia el pecho apretando los omóplatos.','Baja de forma controlada.','Repite.'], ARRAY['Mantén el pecho pegado al banco en todo momento.','Inicia el tirón con la espalda, no con los bíceps.','Controla la bajada hasta estirar por completo los brazos.'], '/exercises/dumbbell-bench-pull-main.webp', '/exercises/dumbbell-bench-pull-main.webp'),
  ('Elevación de Talones con Mancuernas', 'dumbbell-calf-raise', 'calves', ARRAY['forearms'], 'dumbbell', 'intermediate', 'isolation', 'Una elevación de talones con mancuernas sobre una superficie elevada que trabaja gemelos y sóleo en rango completo.', ARRAY['Ponte de pie sujetando una mancuerna en cada mano a los costados.','Coloca las puntas de los pies sobre una superficie elevada con los talones colgando.','Empuja a través de las puntas de los pies para subir los talones lo más alto posible.','Aprieta los gemelos en la parte superior del movimiento.','Baja los talones por debajo de la plataforma para estirar los gemelos.','Repite el número de repeticiones deseado.'], ARRAY['Evita rebotar abajo y haz una pausa breve en el estiramiento.','Mantén las rodillas extendidas pero sin bloquearlas.','Sube y baja despacio para no perder el equilibrio.'], '/exercises/dumbbell-calf-raise-main.webp', '/exercises/dumbbell-calf-raise-main.webp'),
  ('Peso Muerto con Mancuernas', 'dumbbell-deadlift', 'back', ARRAY['quads','traps'], 'dumbbell', 'intermediate', 'compound', 'Un peso muerto con mancuernas que fortalece la cadena posterior mediante un patrón de bisagra de cadera.', ARRAY['Ponte de pie con las mancuernas frente a los muslos y los pies al ancho de las caderas.','Inclínate desde las caderas y baja las mancuernas a lo largo de las piernas con la espalda recta.','Mantén las mancuernas cerca de las espinillas durante el descenso.','Empuja a través de los talones para volver a la posición de pie.','Extiende completamente las caderas en la parte superior sin hiperlordosis lumbar.','Repite el número de repeticiones deseado.'], ARRAY['Empuja la cadera hacia atrás en lugar de redondear la espalda.','Mira al frente o ligeramente hacia abajo para alinear el cuello.','Levanta con las piernas y la cadera, no con la zona lumbar.'], '/exercises/dumbbell-deadlift-main.webp', '/exercises/dumbbell-deadlift-main.webp'),
  ('Face Pull con Mancuernas', 'dumbbell-face-pull', 'shoulders', ARRAY['biceps','traps'], 'dumbbell', 'intermediate', 'isolation', 'Un ejercicio para el deltoides posterior y la espalda alta, tirando de mancuernas hacia la cara con los codos muy abiertos.', ARRAY['Ponte de pie o siéntate sosteniendo una mancuerna en cada mano con los brazos extendidos hacia adelante.','Flexiona los codos y tira de las mancuernas hacia la cara.','Abre los codos hasta la altura de los hombros.','Contrae el deltoides posterior y la espalda alta en el punto máximo.','Baja las mancuernas con control.','Repite el número de repeticiones deseado.'], ARRAY['Lidera el movimiento con los codos, no con las manos.','Mantén los brazos superiores casi paralelos al suelo.','Usa un peso ligero y prioriza la técnica.'], '/exercises/dumbbell-face-pull-main.webp', '/exercises/dumbbell-face-pull-main.webp'),
  ('Caminata del Granjero con Mancuernas', 'dumbbell-farmers-walk', 'forearms', ARRAY['glutes','core','quads'], 'dumbbell', 'beginner', 'compound', 'Este ejercicio de cuerpo completo implica caminar sosteniendo mancuernas pesadas, desarrollando eficazmente la fuerza de agarre, la estabilidad del core y la resistencia muscular general.', ARRAY['Párate erguido con una mancuerna en cada mano, los brazos extendidos a los lados.','Retrae tus escápulas y activa tu core, manteniendo una columna vertebral neutra.','Camina lenta y deliberadamente por una distancia o duración establecida, dando pasos cortos y controlados.','Mantén el pecho erguido y evita inclinarte hacia un lado mientras caminas.','Concéntrate en mantener una postura fuerte y estable durante todo el movimiento.'], ARRAY['Usa las mancuernas más pesadas que puedas controlar sin comprometer la forma.','Respira profunda y rítmicamente para mantener la tensión del core.','Imagina que estás equilibrando un vaso de agua sobre tu cabeza.'], '/exercises/dumbbell-farmers-walk-main.webp', '/exercises/dumbbell-farmers-walk-main.webp'),
  ('Press de Suelo con Mancuernas', 'dumbbell-floor-press', 'chest', ARRAY['shoulders','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un press con mancuernas realizado tumbado en el suelo, que limita el rango de movimiento para un press más amigable con las articulaciones.', ARRAY['Túmbate en el suelo con una mancuerna en cada mano a la altura del pecho.','Empuja las mancuernas hacia arriba hasta que los brazos queden extendidos.','Baja de forma controlada hasta que los codos toquen el suelo.','Repite.'], ARRAY['El suelo limita la tensión en el hombro en la posición inferior.','Mantén las muñecas alineadas sobre los codos.'], '/exercises/dumbbell-floor-press-main.webp', '/exercises/dumbbell-floor-press-main.webp'),
  ('Elevación Frontal con Mancuernas', 'dumbbell-front-raise', 'shoulders', NULL, 'dumbbell', 'beginner', 'isolation', 'Un ejercicio de aislamiento que trabaja el deltoides anterior mediante una elevación hacia adelante.', ARRAY['Ponte de pie con las mancuernas a los costados, palmas frente a los muslos.','Sube una o ambas mancuernas hacia adelante hasta la altura de los hombros.','Baja de forma controlada.','Repite.'], ARRAY['Evita usar el impulso.','Una ligera flexión de codo reduce el estrés articular.'], '/exercises/dumbbell-front-raise-main.webp', '/exercises/dumbbell-front-raise-main.webp'),
  ('Sentadilla Frontal con Mancuernas', 'dumbbell-front-squat', 'glutes', ARRAY['back','hamstrings','core'], 'dumbbell', 'intermediate', 'compound', 'Una sentadilla sosteniendo mancuernas apoyadas en los hombros, manteniendo el torso erguido y enfatizando los cuádriceps.', ARRAY['Sujeta una mancuerna en cada mano apoyadas sobre los hombros.','Mantén los codos en alto y el torso erguido.','Baja las caderas flexionando las rodillas hasta que los muslos queden paralelos al suelo.','Empuja a través de los talones para ponerte de pie.','Mantén la columna en posición neutra durante todo el movimiento.','Repite el número de repeticiones deseado.'], ARRAY['Mantén los codos altos para que las mancuernas queden apoyadas en los hombros.','Siéntate entre las caderas en lugar de plegarte hacia delante.','Empuja con todo el pie y mantén los talones en el suelo.'], '/exercises/dumbbell-front-squat-main.webp', '/exercises/dumbbell-front-squat-main.webp'),
  ('Empuje de Cadera con Mancuerna', 'dumbbell-hip-thrust', 'glutes', ARRAY['hamstrings','quads'], 'dumbbell', 'beginner', 'compound', 'El Empuje de Cadera con Mancuerna es un ejercicio compuesto muy eficaz para construir glúteos y isquiotibiales fuertes, realizado empujando las caderas hacia arriba con una mancuerna sobre la pelvis.', ARRAY['Siéntate en el suelo con la parte superior de la espalda contra un banco, rodillas flexionadas, pies planos y una mancuerna sobre tus caderas.','Contrae tu abdomen y empuja a través de tus talones, levantando las caderas del suelo hasta que tu cuerpo forme una línea recta de hombros a rodillas.','Aprieta tus glúteos con fuerza en la parte superior del movimiento, asegurando una extensión completa de la cadera.','Baja lentamente tus caderas a la posición inicial con control, manteniendo la tensión.','Repite el ejercicio por el número deseado de repeticiones.'], ARRAY['Mantén la barbilla pegada al pecho para mantener una columna vertebral neutra durante todo el movimiento.','Concéntrate en empujar a través de los talones para maximizar la activación de los glúteos.','Controla la fase excéntrica (descenso) para mejorar el crecimiento muscular.','Usa una almohadilla o toalla debajo de la mancuerna para mayor comodidad.'], '/exercises/dumbbell-hip-thrust-main.webp', '/exercises/dumbbell-hip-thrust-main.webp'),
  ('Sentadilla Pistola con Mancuerna', 'dumbbell-pistol-squat', 'glutes', ARRAY['hamstrings'], 'dumbbell', 'advanced', 'compound', 'La Sentadilla Pistola con Mancuerna es una variación avanzada de sentadilla a una pierna que desarrolla fuerza significativa en la parte inferior del cuerpo, equilibrio y movilidad, apuntando principalmente a los cuádriceps y glúteos.', ARRAY['Ponte de pie, sosteniendo una mancuerna en cada mano con los brazos colgando a los lados.','Levanta una pierna recta hacia adelante, manteniéndola extendida durante todo el movimiento.','Baja tu cuerpo doblando la rodilla de tu pierna de apoyo, manteniendo el pecho erguido y la espalda recta.','Desciende hasta que tus glúteos estén cerca de tu talón o tu muslo esté paralelo al suelo, manteniendo el equilibrio.','Empuja a través de tu talón para volver a la posición inicial, extendiendo completamente tu pierna de apoyo.','Completa todas las repeticiones de un lado, luego cambia de pierna y repite para el otro lado por serie.'], ARRAY['Empieza con sentadillas pistola sin peso para dominar el patrón de movimiento antes de añadir mancuernas.','Deja que las mancuernas cuelguen rectas a los lados y mantén el pecho erguido para conservar el equilibrio sobre el pie que trabaja.','Concéntrate en controlar la fase excéntrica (de descenso) para mejorar la estabilidad y la fuerza.','Eleva ligeramente el talón sobre un disco pequeño si la movilidad del tobillo es un factor limitante.'], '/exercises/dumbbell-pistol-squat-main.webp', '/exercises/dumbbell-pistol-squat-main.webp'),
  ('Press de Empuje con Mancuernas', 'dumbbell-push-press', 'shoulders', ARRAY['glutes','quads','traps'], 'dumbbell', 'intermediate', 'compound', 'Un press de hombros compuesto que usa el impulso de las piernas para desarrollar potencia en hombros y tríceps.', ARRAY['Párate sosteniendo mancuernas a la altura de los hombros, palmas hacia adelante.','Dobla ligeramente las rodillas en una cuarta sentadilla.','Empuja con las piernas para generar impulso y presiona las mancuernas hacia arriba.','Extiende los brazos completamente arriba.','Baja las mancuernas con control a la altura de los hombros.'], ARRAY['Usa un descenso poco profundo — no es una sentadilla completa.','Empuja los talones contra el suelo para iniciar el press.','Mantén el core activado para proteger la zona lumbar.'], '/exercises/dumbbell-push-press-main.webp', '/exercises/dumbbell-push-press-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Pájaro Invertido con Mancuernas', 'dumbbell-reverse-fly', 'shoulders', ARRAY['back','traps'], 'dumbbell', 'intermediate', 'isolation', 'Un ejercicio de aislamiento inclinado que levanta las mancuernas hacia los lados, trabajando los deltoides posteriores y la espalda alta.', ARRAY['Inclínate hacia adelante desde las caderas sujetando mancuernas con los brazos colgando.','Mantén la espalda recta y las rodillas ligeramente dobladas.','Sube las mancuernas hacia los lados hasta la altura de los hombros.','Aprieta los omóplatos en la parte superior.','Baja las mancuernas de forma controlada.','Repite el número de repeticiones deseado.'], ARRAY['Usa un peso ligero para que trabajen los deltoides posteriores, no el impulso.','Aprieta los omóplatos juntos arriba.','Mantén una flexión suave y fija en los codos en todo momento.'], '/exercises/dumbbell-reverse-fly-main.webp', '/exercises/dumbbell-reverse-fly-main.webp'),
  ('Peso Muerto Rumano con Mancuernas', 'dumbbell-romanian-deadlift', 'glutes', ARRAY['back','forearms'], 'dumbbell', 'intermediate', 'compound', 'Un peso muerto rumano con mancuernas que enfatiza el estiramiento de los isquiotibiales mediante una bisagra de cadera.', ARRAY['Ponte de pie sujetando mancuernas frente a los muslos con una ligera flexión de rodillas.','Inclínate desde las caderas y empuja los glúteos hacia atrás.','Baja las mancuernas a lo largo de las piernas hasta sentir el estiramiento en los isquiotibiales.','Mantén la espalda recta y los hombros hacia atrás.','Empuja las caderas hacia adelante para volver a la posición de pie.','Repite el número de repeticiones deseado.'], ARRAY['Baja hasta donde tu flexibilidad lo permita, sin forzar.','Mantén la misma flexión suave de rodillas en todo el recorrido.','No conviertas el movimiento en una sentadilla.'], '/exercises/dumbbell-romanian-deadlift-main.webp', '/exercises/dumbbell-romanian-deadlift-main.webp'),
  ('Press de Hombros con Mancuernas', 'dumbbell-shoulder-press', 'shoulders', ARRAY['traps','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un press vertical con mancuernas, sentado o de pie, que desarrolla las porciones anterior y lateral del deltoides.', ARRAY['Siéntate o ponte de pie sujetando mancuernas a la altura de los hombros con las palmas mirando hacia adelante.','Empuja ambas mancuernas por encima de la cabeza hasta que los brazos queden completamente extendidos.','Mantén el core contraído y evita arquear la zona lumbar.','Baja las mancuernas de forma controlada hasta la altura de los hombros.','No dejes que las mancuernas se desplacen detrás de la cabeza.','Repite el número de repeticiones deseado.'], ARRAY['Sube las mancuernas en línea recta, sin chocarlas arriba.','Mantén las muñecas firmes, alineadas con los antebrazos.','Si tu zona lumbar se arquea, reduce el peso.'], '/exercises/dumbbell-shoulder-press-main.webp', '/exercises/dumbbell-shoulder-press-main.webp'),
  ('Flexión Lateral con Mancuerna', 'dumbbell-side-bend', 'core', ARRAY['back','lower_back'], 'dumbbell', 'beginner', 'isolation', 'Un ejercicio de aislamiento de oblicuos de pie con mancuerna para desarrollar la fuerza lateral del core.', ARRAY['Párate erguido sosteniendo una mancuerna a un lado.','Coloca la otra mano en la cadera o detrás de la cabeza.','Inclínate lateralmente hacia el lado de la mancuerna, bajándola por el muslo.','Vuelve a la posición erguida, luego inclínate al lado opuesto con los oblicuos.','Completa todas las repeticiones por lado.'], ARRAY['Evita inclinarte hacia adelante o atrás — muévete estrictamente de lado.','Usa un tempo controlado en ambas direcciones.','Mantén el peso cerca de la pierna durante todo el movimiento.'], '/exercises/dumbbell-side-bend-main.webp', '/exercises/dumbbell-side-bend-main.webp'),
  ('Snatch con Mancuerna', 'dumbbell-snatch', 'shoulders', ARRAY['back','hamstrings','quads'], 'dumbbell', 'intermediate', 'compound', 'Un levantamiento explosivo a un brazo que impulsa la mancuerna desde el suelo hasta encima de la cabeza en un movimiento fluido.', ARRAY['Ponte de pie con los pies al ancho de los hombros y la mancuerna en el suelo entre tus pies.','Inclínate y agarra la mancuerna con una mano.','Extiende caderas, rodillas y tobillos de forma explosiva para tirar de la mancuerna hacia arriba.','Empuja la mancuerna por encima de la cabeza en un movimiento fluido.','Bloquea el brazo y estabiliza en la parte superior.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Extiende completamente caderas y rodillas antes de tirar con el brazo.','Empuja la mancuerna hacia arriba hasta un bloqueo estable sobre la cabeza.','Mantén la mancuerna cerca del cuerpo mientras sube.'], '/exercises/dumbbell-snatch-main.webp', '/exercises/dumbbell-snatch-main.webp'),
  ('Sentadilla en Postura Dividida con Mancuernas', 'dumbbell-split-squat', 'glutes', ARRAY['hamstrings'], 'dumbbell', 'intermediate', 'compound', 'Una sentadilla en posición de tijera sosteniendo mancuernas a los lados, que trabaja los cuádriceps y glúteos una pierna a la vez.', ARRAY['Ponte en postura dividida sujetando mancuernas a los costados.','Mantén el torso erguido y el core contraído.','Baja la rodilla trasera hacia el suelo doblando ambas rodillas.','Para cuando el muslo delantero quede paralelo al suelo.','Empuja a través del talón delantero para volver a la posición de pie.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mantén la mayor parte del peso en la pierna delantera.','Baja la rodilla trasera recta hacia el suelo.','Lleva la rodilla delantera sobre los dedos sin dejar que se hunda hacia dentro.'], '/exercises/dumbbell-split-squat-main.webp', '/exercises/dumbbell-split-squat-main.webp'),
  ('Extensión de Tríceps con Mancuerna', 'dumbbell-tricep-extension', 'triceps', NULL, 'dumbbell', 'beginner', 'isolation', 'Una extensión de tríceps en una mano por encima de la cabeza para un desarrollo equilibrado del brazo.', ARRAY['Ponte de pie sujetando una mancuerna en una mano por encima de la cabeza.','Baja la mancuerna detrás de la cabeza doblando el codo.','Extiende el brazo de vuelta a la posición inicial.','Mantén el codo cerca de la cabeza.','Repite en ambos lados.'], ARRAY['Mantén el codo apuntando al techo durante todo el movimiento.','Baja la mancuerna despacio hasta sentir el estiramiento del tríceps.','Evita arquear la espalda baja manteniendo el abdomen firme.'], '/exercises/dumbbell-tricep-extension-main.webp', '/exercises/dumbbell-tricep-extension-main.webp'),
  ('Remo al Mentón con Mancuernas', 'dumbbell-upright-row', 'shoulders', ARRAY['biceps','back'], 'dumbbell', 'intermediate', 'compound', 'Un movimiento de tirón compuesto con mancuernas que trabaja los deltoides laterales y el trapecio superior.', ARRAY['Párate sosteniendo dos mancuernas frente a los muslos, palmas hacia el cuerpo.','Tira de las mancuernas recto hacia arriba a lo largo del cuerpo, liderando con los codos.','Sube hasta la altura del mentón con los codos por encima de las muñecas.','Pausa brevemente, luego baja con control.','Repite el número de repeticiones deseado.'], ARRAY['Mantén las mancuernas cerca del cuerpo durante todo el movimiento.','Lidera con los codos, no con las manos.','Evita un agarre muy estrecho para reducir el riesgo de impingement de hombro.'], '/exercises/dumbbell-upright-row-main.webp', '/exercises/dumbbell-upright-row-main.webp'),
  ('Molino con Mancuerna', 'dumbbell-windmill', 'shoulders', ARRAY['glutes','hamstrings'], 'dumbbell', 'intermediate', 'compound', 'Este ejercicio de cuerpo completo desarrolla estabilidad del core, fuerza de hombros y movilidad de cadera al rotar el torso con una mancuerna sobre la cabeza, trabajando principalmente los oblicuos y deltoides laterales.', ARRAY['Ponte de pie con los pies al ancho de los hombros, sosteniendo una mancuerna sobre la cabeza con un brazo extendido.','Gira tus pies ligeramente alejándolos del lado de la mancuerna, manteniendo el brazo recto y la vista en el peso.','Inclínate desde las caderas, empujándolas hacia el lado de la mancuerna, y baja lentamente el torso hacia el suelo.','Mantén la espalda recta y el brazo de la mancuerna vertical mientras alcanzas con tu mano libre el pie o el suelo.','Invierte el movimiento impulsándote con las caderas y los oblicuos para regresar a la posición inicial.','Completa todas las repeticiones por lado, luego cambia y repite para el otro lado.'], ARRAY['Mantén el core contraído durante todo el movimiento para proteger tu columna y mejorar la estabilidad.','Mantén la vista fija en la mancuerna sobre la cabeza para ayudar a mantener el equilibrio y el brazo recto.','Concéntrate en inclinarte desde las caderas, no en redondear la espalda, para activar los isquiotibiales y glúteos.','Comienza con un peso ligero para dominar la forma antes de progresar a cargas más pesadas.'], '/exercises/dumbbell-windmill-main.webp', '/exercises/dumbbell-windmill-main.webp'),
  ('Curl de Muñeca con Mancuerna', 'dumbbell-wrist-curl', 'forearms', ARRAY['biceps'], 'dumbbell', 'beginner', 'isolation', 'Un curl de muñeca con mancuerna que aísla los flexores del antebrazo y trabaja ambos brazos por separado.', ARRAY['Siéntate en un banco con el antebrazo sobre el muslo, palma hacia arriba.','Sujeta una mancuerna con la muñeca fuera de la rodilla.','Deja que la mancuerna ruede hasta las puntas de los dedos.','Sube la mancuerna flexionando la muñeca.','Baja con control. Repeticiones por lado.'], ARRAY['Mueve solo la muñeca — el antebrazo permanece quieto.','Rueda la mancuerna a las puntas de los dedos para el rango completo.','Entrena ambos brazos con la misma carga y repeticiones.'], '/exercises/dumbbell-wrist-curl-main.webp', '/exercises/dumbbell-wrist-curl-main.webp'),
  ('Postura del Águila', 'eagle-pose', 'glutes', ARRAY['shoulders','traps'], NULL, 'intermediate', 'compound', 'Un equilibrio de pie con una pierna enroscada sobre la otra y los brazos entrelazados frente al pecho, sosteniendo una forma estrecha y compacta sobre una pierna flexionada.', ARRAY['Ponte de pie, flexiona ligeramente ambas rodillas y pasa el peso a un pie.','Cruza el otro muslo sobre el muslo de apoyo y engancha el pie por detrás de la pantorrilla si llega.','Cruza el brazo contrario por debajo, enrosca los antebrazos y acerca las palmas.','Baja un poco sobre la pierna de apoyo y mantén durante el tiempo indicado, con los codos elevados.','Desenrosca y repite del otro lado.'], ARRAY['Deja el pie cruzado sobre un bloque o el suelo si engancharlo tras la pantorrilla no es posible.','Sube los codos a la altura de los hombros para que la espalda alta trabaje en lugar de hundirse.','Baja más solo mientras la rodilla de apoyo siga sobre el centro del pie.'], '/exercises/eagle-pose-main.webp', '/exercises/eagle-pose-main.webp'),
  ('Postura Fácil', 'easy-pose', 'back', ARRAY['adductors','glutes'], NULL, 'beginner', 'mobility', 'Un sencillo sentado con las piernas cruzadas para respirar y meditar: la pelvis se mantiene erguida, la columna larga y las caderas se asientan sin tensión.', ARRAY['Siéntate en el suelo y cruza las espinillas con comodidad, cada pie bajo la rodilla contraria.','Elévate sobre una manta doblada o un cojín hasta que las rodillas queden por debajo de las caderas.','Alinea las costillas sobre la pelvis y deja las manos sobre los muslos.','Mantén el sentado durante el tiempo indicado, respirando lenta y regularmente.','Cambia qué espinilla queda delante en la siguiente ronda para repartir el tiempo entre ambos lados.'], ARRAY['Si las rodillas quedan altas, sube la altura del asiento en lugar de forzarlas hacia abajo.','Mantén la barbilla nivelada para que el cuello siga la línea de la columna.','Apoya las rodillas sobre cojines cuando un sentado largo se vuelva incómodo.'], '/exercises/easy-pose-main.webp', '/exercises/easy-pose-main.webp'),
  ('Elíptica', 'elliptical-trainer', 'glutes', ARRAY['calves','hamstrings','back','chest','triceps'], 'machine', 'beginner', 'cardio', 'Un ejercicio de máquina cardiovascular de bajo impacto en el que los pies describen un óvalo continuo sobre las plataformas mientras los manillares móviles se empujan y se tiran, trabajando piernas y tren superior a la vez.', ARRAY['Súbete a las plataformas de una en una sujetándote al poste central fijo hasta estar estable, y luego toma un manillar móvil con cada mano.','Pon los pedales en marcha hacia delante manteniendo el pie entero apoyado en la plataforma, sin levantar el talón.','Empuja un manillar hacia delante mientras el pie de ese mismo lado avanza, y tira del otro hacia atrás, de modo que brazos y piernas trabajen en oposición.','Mantente erguido con la cadera sobre los pedales y el core activo, en lugar de dejarte caer hacia atrás sobre los manillares.','Ajusta la resistencia y la rampa para sostener una zancada fluida y continúa durante el tiempo o la distancia deseados.'], ARRAY['Mueve tú los manillares en lugar de dejar que las piernas te los empujen — el trabajo de brazos es lo que convierte a la elíptica en una máquina de cuerpo completo.','Mantén los talones apoyados en las plataformas. Ir de puntillas acalambra los gemelos y deja los glúteos fuera de la zancada.','Pedalear hacia atrás durante parte de la sesión desplaza el énfasis hacia isquiotibiales y glúteos y rompe la monotonía de un esfuerzo largo y constante.'], '/exercises/elliptical-trainer-main.webp', '/exercises/elliptical-trainer-main.webp'),
  ('Ángulo Lateral Extendido', 'extended-side-angle', 'core', ARRAY['adductors','glutes'], NULL, 'intermediate', 'compound', 'Una postura de pie con base amplia, la rodilla delantera flexionada y el torso extendido sobre ese muslo, formando una línea larga desde el talón trasero hasta la mano de arriba.', ARRAY['Sepárate en una base amplia con el pie delantero girado hacia fuera y el trasero algo hacia dentro.','Flexiona la rodilla delantera hasta que quede sobre el tobillo y mantén la pierna trasera estirada.','Apoya el antebrazo delantero sobre el muslo, o la mano en el suelo o un bloque, y estira el brazo de arriba por encima de la oreja.','Mantén la posición durante el tiempo indicado, girando el pecho hacia el techo.','Estira la pierna delantera para subir y repite del otro lado.'], ARRAY['Presiona el borde externo del pie trasero; la postura pierde su base en cuanto ese talón se levanta.','Mantén la rodilla delantera apuntando a los dedos centrales en lugar de dejarla caer hacia dentro.','Apoya el antebrazo en el muslo en lugar de la mano en el suelo para conservar el pecho abierto.'], '/exercises/extended-side-angle-main.webp', '/exercises/extended-side-angle-main.webp'),
  ('Press de Banca con Barra Z', 'ez-bar-bench-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Un press de pecho en banco plano realizado con una barra Z, cuyos agarres angulados son más cómodos para las muñecas mientras trabajan el pectoral, los deltoides anteriores y los tríceps.', ARRAY['Túmbate en un banco plano con los pies apoyados en el suelo y agarra las curvas anguladas de la barra Z sobre el pecho.','Desengancha la barra y sostenla sobre la parte baja del pecho con los brazos extendidos.','Baja la barra de forma controlada hacia la parte baja del pecho.','Empuja la barra de nuevo hacia arriba hasta extender completamente los brazos.','Repite durante el número de repeticiones deseado.'], ARRAY['Mantén los pies apoyados en el suelo y un ligero arco en la zona lumbar para una base estable.','El agarre angulado de la barra Z es más cómodo para las muñecas que una barra recta.','Baja la barra hacia la parte baja del pecho y mantén los codos a unos 45 grados para proteger los hombros.'], '/exercises/ez-bar-bench-press-main.webp', '/exercises/ez-bar-bench-press-main.webp'),
  ('Curl con Barra Z', 'ez-bar-curl', 'biceps', NULL, 'barbell', 'beginner', 'isolation', 'Un ejercicio de aislamiento para el bíceps con barra Z, que reduce la tensión en las muñecas en comparación con una barra recta.', ARRAY['Ponte de pie sujetando la barra Z con agarre supino en las partes anguladas.','Sube la barra hacia los hombros manteniendo los codos fijos.','Aprieta en la parte superior y luego baja de forma controlada.','Repite.'], ARRAY['Usa el agarre interior o exterior para variar el énfasis.','Mantén las muñecas en posición neutra en los agarres angulados.'], '/exercises/ez-bar-curl-main.webp', '/exercises/ez-bar-curl-main.webp'),
  ('Elevación Frontal con Barra Z', 'ez-bar-front-raise', 'shoulders', ARRAY['core'], 'barbell', 'beginner', 'isolation', 'Una elevación frontal con ambas manos usando una barra Z. El agarre angulado es más cómodo para las muñecas que una barra recta y permite a ambas manos manejar la misma carga.', ARRAY['Ponte de pie sujetando la barra Z con agarre prono en las curvas internas, con los brazos colgando frente a los muslos.','Mantén los codos ligeramente doblados y fijos durante todo el movimiento.','Sube la barra en un arco suave hasta la altura de los hombros.','Haz una breve pausa en la parte superior y luego baja de forma controlada.','Repite el número de repeticiones recomendado.'], ARRAY['La barra debe desplazarse en línea recta frente al cuerpo.','No balancees el torso; mantén el core contraído y las rodillas ligeramente flexionadas.','Para a la altura de los hombros — subir más desplaza la tensión fuera de los deltoides anteriores.'], '/exercises/ez-bar-front-raise-main.webp', '/exercises/ez-bar-front-raise-main.webp'),
  ('Extensión de Tríceps Tumbado con Barra Z', 'ez-bar-lying-tricep-extension', 'triceps', NULL, 'barbell', 'intermediate', 'isolation', 'Una extensión de tríceps tumbado realizada con una barra Z para aislar el tríceps a lo largo de todo el rango de movimiento.', ARRAY['Túmbate en un banco plano sujetando una barra Z sobre el pecho con un agarre estrecho.','Baja la barra hacia la frente flexionando los codos.','Extiende los brazos de vuelta a la posición inicial.','Repite.'], ARRAY['Mantén los brazos superiores verticales en todo momento para que trabaje el tríceps.','El agarre angulado de la barra Z es más cómodo para las muñecas que una barra recta.','Baja despacio para proteger los codos.'], '/exercises/ez-bar-lying-tricep-extension-main.webp', '/exercises/ez-bar-lying-tricep-extension-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;